    def test_agent_runtime_direct_apply_patch_is_limited_to_runtime_kernel(self) -> None:
        core_path = REPO_ROOT / "editor/plugins/AITool/services/agent_runtime/core.py"
        module = ast.parse(core_path.read_text(encoding="utf-8-sig"))
        parents: dict[ast.AST, ast.AST] = {}
        for node in ast.walk(module):
            for child in ast.iter_child_nodes(node):
                parents[child] = node

        allowed_kernel_writes = {
            ("ToolCallGraphExecutor", "execute"),
            ("ToolCallGraphExecutor", "_emit_tool_started_runtime_event"),
            ("ToolCallGraphExecutor", "_emit_tool_result_runtime_event"),
            ("ToolCallGraphExecutor", "_emit_tool_blocked_runtime_event"),
            ("ToolCallGraphExecutor", "_emit_graph_stopped_runtime_event"),
            ("ToolCallGraphExecutor", "_persist_graph"),
            ("AgentRuntime", "_enqueue_tool_graph"),
            ("AgentRuntime", "_persist_tool_graph_state"),
            ("AgentRuntime", "_mark_tool_graph_queue_item"),
            ("AgentRuntime", "emit_runtime_event"),
            ("AgentRuntime", "_persist_planning_context_changes_direct"),
        }
        direct_writes: list[tuple[str, str, int]] = []
        for node in ast.walk(module):
            if not (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "apply_patch"
            ):
                continue
            function_name = ""
            class_name = ""
            cursor: ast.AST = node
            while cursor in parents:
                cursor = parents[cursor]
                if isinstance(cursor, ast.FunctionDef) and not function_name:
                    function_name = cursor.name
                if isinstance(cursor, ast.ClassDef):
                    class_name = cursor.name
                    break
            direct_writes.append((class_name, function_name, int(getattr(node, "lineno", 0))))

        unexpected = [
            f"{class_name}.{function_name}:{line_no}"
            for class_name, function_name, line_no in direct_writes
            if (class_name, function_name) not in allowed_kernel_writes
        ]
        self.assertFalse(
            unexpected,
            "AgentRuntime business state writes must go through ToolCallGraph/ToolResult; "
            f"unexpected direct RuntimeState.apply_patch calls: {unexpected}",
        )

    def test_agent_runtime_package_apply_patch_is_core_only(self) -> None:
        runtime_dir = REPO_ROOT / "editor/plugins/AITool/services/agent_runtime"
        unexpected: list[str] = []
        for path in sorted(runtime_dir.glob("*.py")):
            if path.name in {"core.py", "__init__.py"}:
                continue
            module = ast.parse(path.read_text(encoding="utf-8-sig"))
            for node in ast.walk(module):
                if (
                    isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "apply_patch"
                ):
                    rel = path.relative_to(REPO_ROOT).as_posix()
                    unexpected.append(f"{rel}:{int(getattr(node, 'lineno', 0))}")

        self.assertFalse(
            unexpected,
            "AgentRuntime modules outside core.py must not call RuntimeState.apply_patch directly; "
            f"use ToolResult.state_patch via ToolCallGraphExecutor instead: {unexpected}",
        )

    def test_runtime_cpp_bridge_never_invokes_engine_tool_directly(self) -> None:
        adapters_path = REPO_ROOT / "editor/plugins/AITool/services/agent_runtime/adapters.py"
        module = ast.parse(adapters_path.read_text(encoding="utf-8-sig"))
        runtime_bridge = next(
            (
                node
                for node in module.body
                if isinstance(node, ast.ClassDef) and node.name == "RuntimeCppBridge"
            ),
            None,
        )
        self.assertIsNotNone(runtime_bridge)

        direct_calls: list[str] = []
        gate_calls: list[str] = []
        for node in ast.walk(runtime_bridge):
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "getattr"
                and len(node.args) >= 2
                and ast.unparse(node.args[0]) == "self._engine_gate"
                and isinstance(node.args[1], ast.Constant)
                and node.args[1].value in {"invoke_tool", "set_transform", "remove_actor"}
            ):
                gate_calls.append(f"self._engine_gate.{node.args[1].value}")
            if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute):
                continue
            owner = ast.unparse(node.func.value) if hasattr(ast, "unparse") else ""
            if owner == "tool" and node.func.attr == "invoke":
                direct_calls.append(f"{owner}.{node.func.attr}")
            if owner == "self._engine_gate" and node.func.attr in {"invoke_tool", "set_transform", "remove_actor"}:
                gate_calls.append(f"{owner}.{node.func.attr}")

        self.assertFalse(direct_calls, f"RuntimeCppBridge must not call engine tool directly: {direct_calls}")
        self.assertIn("self._engine_gate.invoke_tool", gate_calls)
        self.assertIn("self._engine_gate.set_transform", gate_calls)
        self.assertIn("self._engine_gate.remove_actor", gate_calls)

    def test_runtime_cpp_bridge_public_execution_methods_must_use_engine_gate(self) -> None:
        adapters_path = REPO_ROOT / "editor/plugins/AITool/services/agent_runtime/adapters.py"
        module = ast.parse(adapters_path.read_text(encoding="utf-8-sig"))
        runtime_bridge = next(
            (
                node
                for node in module.body
                if isinstance(node, ast.ClassDef) and node.name == "RuntimeCppBridge"
            ),
            None,
        )
        self.assertIsNotNone(runtime_bridge)

        public_methods = [
            node
            for node in runtime_bridge.body
            if isinstance(node, ast.FunctionDef)
            and not node.name.startswith("_")
            and node.name not in {"__init__"}
        ]
        self.assertTrue(public_methods)
        missing_gate: list[str] = []
        for method in public_methods:
            uses_gate = any(
                isinstance(node, ast.Attribute)
                and ast.unparse(node.value) == "self"
                and node.attr == "_engine_gate"
                for node in ast.walk(method)
            )
            if not uses_gate:
                missing_gate.append(method.name)

        self.assertFalse(
            missing_gate,
            f"RuntimeCppBridge public execution methods must go through EngineWriteGate: {missing_gate}",
        )

    def test_engine_write_runtime_providers_only_call_runtime_cpp_bridge(self) -> None:
        adapters_path = REPO_ROOT / "editor/plugins/AITool/services/agent_runtime/adapters.py"
        module = ast.parse(adapters_path.read_text(encoding="utf-8-sig"))
        provider_names = {
            "make_engine_actor_import_provider": {"bridge.invoke_tool"},
            "make_engine_layout_transform_provider": {"bridge.set_transform"},
            "make_engine_actor_delete_provider": {"bridge.remove_actor"},
            "make_engine_environment_component_import_provider": {"bridge.invoke_tool"},
        }
        providers = {
            node.name: node
            for node in module.body
            if isinstance(node, ast.FunctionDef) and node.name in provider_names
        }
        self.assertEqual(set(providers), set(provider_names))

        forbidden: list[str] = []
        bridge_calls: dict[str, set[str]] = {name: set() for name in provider_names}
        forbidden_helpers = {
            "_invoke_tool",
            "_invoke_tool_safely",
            "_invoke_image_tool",
        }
        for provider_name, provider in providers.items():
            for node in ast.walk(provider):
                if not isinstance(node, ast.Call):
                    continue
                if isinstance(node.func, ast.Attribute):
                    owner = ast.unparse(node.func.value)
                    call_name = f"{owner}.{node.func.attr}"
                    if owner == "bridge":
                        bridge_calls[provider_name].add(call_name)
                    if node.func.attr == "invoke" and owner in {
                        "tool",
                        "import_tool",
                        "transform_tool",
                        "delete_tool",
                        "environment_import_tool",
                    }:
                        forbidden.append(f"{provider_name}:{call_name}:{node.lineno}")
                elif isinstance(node.func, ast.Name) and node.func.id in forbidden_helpers:
                    forbidden.append(f"{provider_name}:{node.func.id}:{node.lineno}")

        self.assertFalse(
            forbidden,
            "Runtime engine-write providers must not bypass RuntimeCppBridge/EngineWriteGate: "
            f"{forbidden}",
        )
        for provider_name, expected_calls in provider_names.items():
            self.assertTrue(
                expected_calls <= bridge_calls[provider_name],
                f"{provider_name} must call RuntimeCppBridge methods {sorted(expected_calls)}; "
                f"found {sorted(bridge_calls[provider_name])}",
            )

