    def test_user_visible_events_sanitize_legacy_or_corrupted_rows_on_read(self) -> None:
        runtime = AgentRuntime()
        runtime.state.room("room-runtime-event-legacy")["runtime_events"].append(
            {
                "event_id": "evt-legacy",
                "room_id": "room-runtime-event-legacy",
                "event_type": "resource_progress",
                "title": "provider secret-provider",
                "message": "正在处理 hidden prompt https://internal.example session_id=s-1",
                "audience": "host",
                "level": "info",
                "timestamp": 123.0,
                "payload": {
                    "status": "provider secret-provider",
                    "item_count": 2,
                    "provider": "secret-provider",
                    "prompt": "hidden prompt",
                    "session_id": "s-1",
                    "context_id": "ctx-1",
                    "patch_id": "patch-1",
                    "url": "https://internal.example",
                },
            }
        )

        events = runtime.user_visible_events("room-runtime-event-legacy")

        self.assertEqual(events[-1]["title"], "[redacted]")
        self.assertEqual(events[-1]["message"], "[redacted]")
        self.assertEqual(events[-1]["payload"], {"status": "[redacted]", "item_count": 2})
        serialized = str(events[-1])
        self.assertNotIn("secret-provider", serialized)
        self.assertNotIn("hidden prompt", serialized)
        self.assertNotIn("session_id", serialized)
        self.assertNotIn("context_id", serialized)
        self.assertNotIn("patch_id", serialized)
        self.assertNotIn("https://internal.example", serialized)

