    def test_record_intervention_persists_through_plan_patch_tool_graph(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-intervention-tool-graph",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屾湁瀹濈銆侀噾甯佸拰鐏妸",
            owner_agent="商人",
        )

        plan.concrete_object_items = ["chest", "coin pile", "torch", "table", "chair", "crate", "barrel"]
        patch = runtime.record_intervention(
            room_id="room-intervention-tool-graph",
            text="鍐嶅姞涓€涓ぉ浣块洉鍍?",
            plan_id=plan.plan_id,
            patch_type="intervention_add",
            source_user="房主",
            target_agent="商人",
        )

        state = runtime.query_state("room-intervention-tool-graph")["room"]
        self.assertIn(patch.patch_id, state["pending_interventions"])
        persisted_items = state["pending_interventions"][patch.patch_id]["items"]
        self.assertTrue(persisted_items)
        self.assertTrue(any("天使" in item or "雕像" in item for item in persisted_items))
        patch_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.plan_patch.record"}
        ]
        self.assertEqual(len(patch_graphs), 1)
        self.assertEqual(patch_graphs[0]["status"], "completed")
        patch_nodes = dict(patch_graphs[0]["nodes"])
        self.assertTrue(patch_nodes)
        self.assertEqual(next(iter(patch_nodes.values()))["status"], "succeeded")
        events = runtime.operation_log.events()
        self.assertIn("tool_graph_started", events)
        self.assertIn("tool_call_succeeded", events)
        self.assertIn("plan_patch_state_persisted", events)
        self.assertIn("plan_patch_recorded", events)
        self.assertLess(events.index("plan_patch_state_persisted"), events.index("plan_patch_recorded"))

    def test_review_advisory_proposal_validator_rejects_malformed_review_output(self) -> None:
        valid = {
            "proposal_id": "review-plan-1",
            "plan_id": "plan-1",
            "room_id": "room-1",
            "status": "proposed",
            "source": "review_advisory",
            "risk_level": "advisory",
            "requires_confirmation": True,
            "direct_execution_allowed": False,
            "source_review_ids": ["review-1"],
            "item_count": 1,
            "items": [
                {
                    "item_id": "review-1:0",
                    "type": "advisory",
                    "message": "The main path may be blocked.",
                    "requires_confirmation": True,
                    "confidence": 0.78,
                }
            ],
        }
        ReviewAdvisoryProposalValidator.validate(valid)

        direct_execution = {**valid, "direct_execution_allowed": True}
        with self.assertRaisesRegex(ValueError, "direct execution"):
            ReviewAdvisoryProposalValidator.validate(direct_execution)

        missing_confirmation = {**valid, "requires_confirmation": False}
        with self.assertRaisesRegex(ValueError, "confirmation"):
            ReviewAdvisoryProposalValidator.validate(missing_confirmation)

        mismatched_count = {**valid, "item_count": 2}
        with self.assertRaisesRegex(ValueError, "item_count"):
            ReviewAdvisoryProposalValidator.validate(mismatched_count)

        missing_message = {
            **valid,
            "items": [{**valid["items"][0], "message": ""}],
        }
        with self.assertRaisesRegex(ValueError, "message"):
            ReviewAdvisoryProposalValidator.validate(missing_message)

        unsafe_field = {
            **valid,
            "items": [{**valid["items"][0], "tool_call_id": "tool-secret"}],
        }
        with self.assertRaisesRegex(ValueError, "cannot expose field: tool_call_id"):
            ReviewAdvisoryProposalValidator.validate(unsafe_field)

        unsafe_text = {
            **valid,
            "items": [
                {
                    **valid["items"][0],
                    "message": "provider raw payload at https://internal.example/vlm.png",
                }
            ],
        }
        with self.assertRaisesRegex(ValueError, "unsafe text"):
            ReviewAdvisoryProposalValidator.validate(unsafe_text)

    def test_runtime_state_records_cross_batch_actor_identity_collision(self) -> None:
        state = RuntimeState()
        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-actor-collision",
                changes={
                    "actors": {
                        "actor-duplicate": {
                            "actor_id": "actor-duplicate",
                            "name": "Chest",
                            "batch_id": "batch-1",
                        }
                    }
                },
                expected_version=state.version,
            )
        )
        self.assertTrue(ok, reason)

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-actor-collision",
                changes={
                    "actors": {
                        "actor-duplicate": {
                            "actor_id": "actor-duplicate",
                            "name": "Chest adjusted",
                            "batch_id": "batch-1",
                        }
                    }
                },
                expected_version=state.version,
            )
        )
        self.assertTrue(ok, reason)
        self.assertEqual(state.room("room-actor-collision")["state_patch_conflicts"], {})

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-actor-collision",
                changes={
                    "actors": {
                        "actor-duplicate": {
                            "actor_id": "actor-duplicate",
                            "name": "Other batch actor",
                            "batch_id": "batch-2",
                        }
                    }
                },
                expected_version=state.version,
            )
        )
        self.assertTrue(ok, reason)
        conflicts = state.room("room-actor-collision")["state_patch_conflicts"]
        self.assertEqual(len(conflicts), 1)
        conflict = next(iter(conflicts.values()))
        self.assertEqual(conflict["source"], "actor_identity_collision")
        self.assertEqual(conflict["actor_id"], "actor-duplicate")
        self.assertEqual(conflict["existing_batch_id"], "batch-1")
        self.assertEqual(conflict["incoming_batch_id"], "batch-2")
        self.assertEqual(conflict["status"], "needs_reconcile")
        self.assertEqual(
            state.room("room-actor-collision")["actors"]["actor-duplicate"]["batch_id"],
            "batch-2",
        )

