    def test_agent_runtime_package_does_not_import_or_call_legacy_main_workflow(self) -> None:
        runtime_dir = EDITOR_ROOT / "plugins" / "AITool" / "services" / "agent_runtime"
        forbidden_patterns = {
            "SceneComposer import": re.compile(r"^\s*(?:from|import)\s+.*SceneComposer", re.MULTILINE),
            "scene_composer module import": re.compile(r"^\s*(?:from|import)\s+.*scene_composer(?:\s|\.|$)", re.MULTILINE),
            "run_progressive_workflow import": re.compile(r"^\s*(?:from|import)\s+.*run_progressive_workflow", re.MULTILINE),
            "GenerationScheduler import": re.compile(r"^\s*(?:from|import)\s+.*GenerationScheduler", re.MULTILINE),
            "SceneComposerJobRunner import": re.compile(r"^\s*(?:from|import)\s+.*SceneComposerJobRunner", re.MULTILINE),
            "generation_composer_adapter module import": re.compile(
                r"^\s*(?:from|import)\s+.*generation_composer_adapter(?:\s|\.|$)",
                re.MULTILINE,
            ),
            "GenerationScheduler submit": re.compile(
                r"\b(?:generation_scheduler|scheduler)\.submit\s*\(",
                re.IGNORECASE,
            ),
            "SceneComposer compose": re.compile(r"\.compose\s*\("),
            "legacy big workflow tool": re.compile(r"legacy\.(?:scene_compose|progressive_compose|workflow_orchestrator)"),
        }

        violations: list[str] = []
        for path in sorted(runtime_dir.glob("*.py")):
            source = path.read_text(encoding="utf-8")
            for label, pattern in forbidden_patterns.items():
                if pattern.search(source):
                    violations.append(f"{path.name}: {label}")

        self.assertEqual(violations, [])

