    def test_confirmed_plan_executes_through_tool_graph_and_operation_log(self) -> None:
        runtime = AgentRuntime()

        plan = runtime.propose_scene_plan(
            room_id="room-1",
            text="强盗藏宝室，要有藏宝箱、金币堆和火把",
            owner_agent="商人",
            source_context_agents=["长者"],
        )
        self.assertEqual(plan.status, ScenePlanStatus.PROPOSED)
        self.assertEqual(plan.owner_agent, "商人")
        self.assertIn("藏宝箱", plan.concrete_object_items)

        runtime.scene_plans.pop(plan.plan_id, None)
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")
        runtime.scene_plans.pop(plan.plan_id, None)
        result = runtime.execute_scene_plan(plan.plan_id)

        self.assertEqual(result["plan"]["status"], ScenePlanStatus.COMPLETED.value)
        self.assertEqual(result["graph"]["status"], "completed")
        self.assertGreaterEqual(result["graph"]["node_count"], 1)
        self.assertNotIn("nodes", result["graph"])
        self.assertNotIn("nodes", result["queued"]["graph"])
        self.assertTrue(all("nodes" not in graph for graph in result["drain"]["graphs"]))
        state = runtime.query_state("room-1")
        self.assertGreaterEqual(len(state["room"]["actors"]), 1)
        self.assertIn(plan.plan_id, state["room"]["asset_request_plans"])
        self.assertIn(plan.plan_id, state["room"]["placement_proposals"])
        self.assertGreaterEqual(len(state["room"]["tool_graphs"]), 1)
        self.assertGreaterEqual(len(state["room"]["tool_graph_queue"]), 1)
        graph_snapshot = next(iter(state["room"]["tool_graphs"].values()))
        self.assertEqual(graph_snapshot["status"], "completed")
        self.assertIn("nodes", graph_snapshot)
        queue_item = next(iter(state["room"]["tool_graph_queue"].values()))
        self.assertEqual(queue_item["status"], "completed")
        self.assertEqual(queue_item["plan_id"], plan.plan_id)
        first_actor = next(iter(state["room"]["actors"].values()))
        self.assertIn("position", first_actor)
        self.assertEqual(first_actor.get("zone_hint"), "indoor_floor")
        self.assertGreaterEqual(result["report"]["tool_graph_summary"]["graph_count"], 1)
        report_graph = result["report"]["tool_graph_summary"]["graphs"][0]
        self.assertNotIn("graph_id", report_graph)
        self.assertEqual(report_graph["status"], "completed")
        self.assertGreaterEqual(report_graph["node_count"], 1)
        events = runtime.operation_log.events()
        self.assertIn("scene_plan_created", events)
        self.assertIn("scene_plan_state_persisted", events)
        self.assertLess(events.index("scene_plan_state_persisted"), events.index("scene_plan_created"))
        self.assertIn("scene_plan_confirmed", events)
        self.assertIn("batch_plan_created", events)
        self.assertIn("tool_graph_queued", events)
        self.assertIn("tool_graph_dequeued", events)
        self.assertIn("tool_graph_state_recorded", events)
        self.assertIn("tool_graph_started", events)
        self.assertIn("tool_call_succeeded", events)
        self.assertIn("user_report_generated", events)
        execution_graph_id = result["graph"]["graph_id"]
        queue_facts = runtime.query_state("room-1")["room"]["custom_queue_facts"]
        selection_fact = queue_facts[f"room-1:{plan.plan_id}:next_tool_graph"]
        self.assertEqual(selection_fact["selected_graph_ref"], execution_graph_id)
        self.assertEqual(selection_fact["status"], "selected")
        self.assertNotIn("graph_id", selection_fact)
        execution_graph_events = [
            entry.event
            for entry in runtime.operation_log.entries()
            if entry.payload.get("graph_id") == execution_graph_id
        ]
        self.assertLess(
            execution_graph_events.index("tool_graph_queued"),
            execution_graph_events.index("tool_graph_started"),
        )
        self.assertLess(
            execution_graph_events.index("tool_graph_dequeued"),
            execution_graph_events.index("tool_graph_started"),
        )
        summary = runtime.status_summary("room-1", plan_id=plan.plan_id)
        self.assertEqual(summary["tool_graph_summary"]["queue_count"], 1)
        self.assertEqual(summary["tool_graph_summary"]["queue_status_counts"], {"completed": 1})
        self.assertEqual(summary["tool_graph_summary"]["latest_queue"][0]["status"], "completed")
        replay = runtime.operation_replay(room_id="room-1", plan_id=plan.plan_id)
        lifecycle_summary = replay["scene_plan_lifecycle_summary"]
        self.assertEqual(lifecycle_summary["created_count"], 1)
        self.assertEqual(lifecycle_summary["confirmed_count"], 1)
        self.assertGreaterEqual(lifecycle_summary["state_persisted_count"], 2)
        self.assertGreaterEqual(lifecycle_summary["status_persisted_count"], 1)
        self.assertEqual(lifecycle_summary["state_persist_failed_count"], 0)
        self.assertEqual(lifecycle_summary["status_persist_failed_count"], 0)
        self.assertEqual(lifecycle_summary["status_counts"][ScenePlanStatus.COMPLETED.value], 1)
        self.assertIn("execute_scene_plan", lifecycle_summary["reason_counts"])
        self.assertNotIn(plan.design_brief, str(lifecycle_summary))
        report_lifecycle_summary = result["report"]["operation_replay_summary"]["scene_plan_lifecycle_summary"]
        self.assertEqual(report_lifecycle_summary["created_count"], 1)
        self.assertEqual(report_lifecycle_summary["confirmed_count"], 1)
        runtime_event_summary = replay["runtime_event_replay_summary"]
        self.assertGreater(runtime_event_summary["emitted_count"], 0)
        self.assertEqual(runtime_event_summary["emit_failed_count"], 0)
        self.assertIn("plan_confirmed", runtime_event_summary["event_type_counts"])
        self.assertNotIn(plan.design_brief, str(runtime_event_summary))
        report_runtime_event_summary = result["report"]["operation_replay_summary"]["runtime_event_replay_summary"]
        self.assertGreater(report_runtime_event_summary["emitted_count"], 0)
        self.assertEqual(report_runtime_event_summary["emit_failed_count"], 0)

