        graph = runtime._build_batch_execution_graph(plan, batch)
        runtime._enqueue_tool_graph(graph, room_id="room-drain-final-queue-fail")
        original_apply_patch = runtime.state.apply_patch

        def fail_completed_queue_state_once(patch: StatePatch) -> tuple[bool, str]:
            queue_patch = dict((patch.changes or {}).get("tool_graph_queue") or {})
            if queue_patch:
                queue_item = next(iter(queue_patch.values()))
                if dict(queue_item).get("status") == "completed":
                    return False, "simulated queue completed persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = fail_completed_queue_state_once  # type: ignore[method-assign]

        with self.assertRaises(RuntimeError):
            runtime.drain_next_tool_graph("room-drain-final-queue-fail", plan_id=plan.plan_id)

