    def test_propose_scene_plan_persists_before_extracting_items_through_tool_call_graph(self) -> None:
        runtime = AgentRuntime()

        plan = runtime.propose_scene_plan(
            room_id="room-plan-extract",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            owner_agent="山贼",
        )

        self.assertGreaterEqual(len(plan.concrete_object_items), 1)
        state = runtime.query_state("room-plan-extract")["room"]
        self.assertIn(plan.plan_id, state["plan_extractions"])
        extraction = state["plan_extractions"][plan.plan_id]
        self.assertGreaterEqual(len(extraction["candidate_items"]), 1)
        self.assertIn(plan.plan_id, state["model_item_lists"])
        self.assertGreaterEqual(len(state["model_item_lists"][plan.plan_id]), 1)
        self.assertIn(plan.plan_id, state["element_routes"])
        tool_messages = [
            event for event in state["runtime_events"]
            if event.get("event_type") == "tool_result_message"
        ]
        extraction_messages = [
            event for event in tool_messages
            if str(event.get("message") or "").startswith("物体提炼完成")
        ]
        classification_messages = [
            event for event in tool_messages
            if str(event.get("message") or "").startswith("元素分类完成")
        ]
        self.assertTrue(extraction_messages)
        self.assertTrue(classification_messages)
        self.assertEqual(extraction_messages[-1]["payload"]["status"], "succeeded")
        self.assertGreaterEqual(extraction_messages[-1]["payload"]["item_count"], 1)
        self.assertGreaterEqual(classification_messages[-1]["payload"]["item_count"], 1)
        self.assertIn("component_count", classification_messages[-1]["payload"])
        serialized_messages = f"{extraction_messages} {classification_messages}"
        self.assertNotIn("provider raw", serialized_messages)
        self.assertNotIn("prompt=hidden", serialized_messages)
        self.assertNotIn("model_path", serialized_messages)
        self.assertNotIn("E:/private", serialized_messages)
        graphs = [
            graph for graph in state["tool_graphs"].values()
            if graph["plan_id"] == plan.plan_id
        ]
        graph_tool_sets = [
            [node["tool_name"] for node in graph["nodes"].values()]
            for graph in graphs
        ]
        self.assertIn(["runtime.scene_plan.persist"], graph_tool_sets)
        self.assertTrue(
            any(
                {
                    "scene.extract_objects",
                    "scene.classify_type",
                    "scene.extract_constraints",
                    "room.estimate_bounds",
                    "zone.decompose",
                    "scene.extract_environment",
                    "asset.route_item",
                    "placement.prepare_items",
                    "runtime.elements.classify",
                }
                <= set(tool_set)
                for tool_set in graph_tool_sets
            )
        )
        persist_graph = next(
            graph
            for graph in graphs
            if [node["tool_name"] for node in graph["nodes"].values()] == ["runtime.scene_plan.persist"]
        )
        self.assertEqual(persist_graph["status"], "completed")
        events = runtime.operation_log.events()
        self.assertIn("scene_plan_extracted_via_tool_graph", events)
        self.assertIn("scene_plan_created", events)
        self.assertLess(events.index("scene_plan_state_persisted"), events.index("scene_plan_extracted_via_tool_graph"))
        self.assertLess(events.index("scene_plan_extracted_via_tool_graph"), events.index("scene_plan_created"))
        extraction_persist_entries = [
            entry for entry in runtime.operation_log.entries()
            if entry.event == "scene_plan_status_persisted"
            and entry.payload.get("reason") == "propose_scene_plan_extracted_fields"
        ]
        self.assertTrue(extraction_persist_entries)
        self.assertLess(events.index("scene_plan_extracted_via_tool_graph"), events.index("scene_plan_status_persisted"))
        history = state["state_patch_history"]
        self.assertIn(
            ["active_plan_id", "custom_scene_design_contract_facts", "scene_plans"],
            [entry["change_keys"] for entry in history],
        )
        self.assertIn(
            ["custom_scene_design_contract_facts", "scene_plans"],
            [entry["change_keys"] for entry in history],
        )
        self.assertIn(plan.plan_id, state["custom_scene_design_contract_facts"])

