    def test_sync_external_plan_context_does_not_leave_orphan_plan_when_external_link_persist_fails(self) -> None:
        runtime = AgentRuntime()
        original_apply_patch = runtime.state.apply_patch

        def fail_external_link_once(patch: StatePatch) -> tuple[bool, str]:
            if "external_plan_links" in (patch.changes or {}):
                return False, "simulated external link persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = fail_external_link_once  # type: ignore[method-assign]

        with self.assertRaises(RuntimeError):
            runtime.sync_external_plan_context(
                room_id="room-external-link-fail",
                external_plan_id="seed-external-link-fail",
                text="鍥寸粫寮虹洍钘忓疂瀹ゅ仛涓€涓柟妗堬紝鍖呭惈瀹濈銆侀噾甯佸拰鐏妸銆?",
                owner_agent="山贼",
            )

        state = runtime.query_state("room-external-link-fail")["room"]
        self.assertEqual(state["active_plan_id"], "")
        self.assertEqual(state["scene_plans"], {})
        self.assertEqual(state["external_plan_links"], {})
        self.assertEqual(state["planning_context_events"], [])
        persist_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.scene_plan.persist"}
        ]
        self.assertEqual(len(persist_graphs), 1)
        self.assertEqual(persist_graphs[0]["status"], "failed")
        self.assertEqual(state["plan_extractions"], {})
        self.assertEqual(state["model_item_lists"], {})
        self.assertEqual(state["element_routes"], {})
        self.assertEqual(runtime.scene_plans, {})
        events = runtime.operation_log.events()
        self.assertIn("scene_plan_state_persist_failed", events)
        self.assertIn("external_plan_link_state_persist_failed", events)
        self.assertIn("planning_context_state_persist_failed", events)
        self.assertNotIn("external_plan_linked", events)
        self.assertNotIn("scene_plan_created", events)

