    def test_handle_message_confirm_and_enqueue_persist_failure_returns_safe_failure(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-message-enqueue-fail",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            owner_agent="山贼",
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_confirm_patch(patch):
            if "scene_plans" in patch.changes:
                return False, "simulated provider/raw/internal confirm persistence failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_confirm_patch

        result = runtime.handle_message(
            room_id="room-message-enqueue-fail",
            text="纭鐢熸垚",
            sender_id="host-1",
            sender_name="房主",
            owner_agent="山贼",
            action="confirm_and_enqueue",
            max_items_per_batch=2,
        )
        state = runtime.query_state("room-message-enqueue-fail")["room"]

        self.assertTrue(result["handled"])
        self.assertFalse(result["recorded"])
        self.assertEqual(result["plan"]["plan_id"], plan.plan_id)
        self.assertEqual(result["batches"], [])
        self.assertEqual(result["graphs"], [])
        self.assertEqual(result["queued"], {})
        self.assertIn("RuntimeState persistence failed", result["message"])
        self.assertNotIn("provider", result["message"])
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "proposed")
        self.assertIn("scene_plan_state_persist_failed", runtime.operation_log.events())
        self.assertIn("runtime_message_enqueue_failed", runtime.operation_log.events())
        self.assertNotIn("runtime_message_enqueued", runtime.operation_log.events())

    def test_handle_message_worker_drain_executes_queued_graphs_without_creating_plan(self) -> None:
        runtime = AgentRuntime()

        empty = runtime.handle_message(
            room_id="room-worker-drain",
            text="worker drain",
            sender_id="worker-1",
            action="worker_drain",
            max_graphs=1,
        )

        self.assertTrue(empty["handled"])
        self.assertEqual(empty["drain"]["drained_count"], 0)
        self.assertEqual(runtime.query_state("room-worker-drain")["room"]["scene_plans"], {})
        self.assertIn("runtime_worker_drain_requested", runtime.operation_log.events())

        queued = runtime.handle_message(
            room_id="room-worker-drain",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            sender_id="host-1",
            sender_name="房主",
            owner_agent="山贼",
            action="confirm_and_enqueue",
            external_plan_id="seed-worker-drain",
            max_items_per_batch=2,
        )
        queued_graph_count = len(queued["graphs"])
        self.assertGreaterEqual(queued_graph_count, 2)
        self.assertTrue(all("nodes" not in graph for graph in queued["graphs"]))
        runtime.scene_plans.pop(queued["plan"]["plan_id"], None)

        first = runtime.handle_message(
            room_id="room-worker-drain",
            text="drain first",
            sender_id="worker-1",
            action="worker_drain",
            external_plan_id="seed-worker-drain",
            max_graphs=1,
        )

        self.assertEqual(first["drain"]["drained_count"], 1)
        self.assertTrue(first["drain"]["graphs"])
        self.assertTrue(all("nodes" not in graph for graph in first["drain"]["graphs"]))
        self.assertEqual(
            runtime.status_summary("room-worker-drain", external_plan_id="seed-worker-drain")["tool_graph_summary"]["queue_status_counts"],
            {"completed": 1, "queued": queued_graph_count - 1},
        )
        self.assertIn("runtime_message_drained", runtime.operation_log.events())

        second = runtime.handle_message(
            room_id="room-worker-drain",
            text="drain rest",
            sender_id="worker-1",
            action="worker_drain",
            external_plan_id="seed-worker-drain",
            max_graphs=queued_graph_count,
        )

        self.assertEqual(second["drain"]["drained_count"], queued_graph_count - 1)
        self.assertTrue(all("nodes" not in graph for graph in second["drain"]["graphs"]))
        self.assertEqual(
            runtime.status_summary("room-worker-drain", external_plan_id="seed-worker-drain")["tool_graph_summary"]["queue_status_counts"],
            {"completed": queued_graph_count},
        )
        self.assertGreaterEqual(len(runtime.query_state("room-worker-drain")["room"]["actors"]), 1)

    def test_handle_message_worker_drain_status_summary_failure_does_not_escape_after_successful_drain(self) -> None:
        runtime = AgentRuntime()
        queued = runtime.handle_message(
            room_id="room-worker-drain-status-fail",
            text="生成一个简单森林营地，有草地、天空、帐篷、小木桌。",
            sender_id="host-1",
            sender_name="房主",
            owner_agent="长者",
            action="confirm_and_enqueue",
            external_plan_id="seed-worker-drain-status-fail",
            max_items_per_batch=8,
        )
        self.assertEqual(len(queued["graphs"]), 1)

        original_status_summary = runtime.status_summary

        def fail_status_summary(*args: Any, **kwargs: Any) -> dict[str, Any]:
            raise RuntimeError("provider raw url https://internal.example/status")

        runtime.status_summary = fail_status_summary  # type: ignore[method-assign]

        drained = runtime.handle_message(
            room_id="room-worker-drain-status-fail",
            text="worker drain",
            sender_id="worker-1",
            action="worker_drain",
            external_plan_id="seed-worker-drain-status-fail",
            max_graphs=1,
        )

        self.assertTrue(drained["handled"])
        self.assertEqual(drained["drain"]["drained_count"], 1)
        self.assertEqual(drained["drain"]["graphs"][0]["status"], "completed")
        self.assertIn("已 drain", drained["message"])
        self.assertNotIn("provider", str(drained).lower())
        self.assertNotIn("raw", str(drained).lower())
        self.assertNotIn("https://", str(drained).lower())
        events = runtime.operation_log.events()
        self.assertIn("runtime_message_drained", events)
        self.assertIn("runtime_worker_drain_status_failed", events)
        status_failure_entries = runtime.operation_log.query(
            event="runtime_worker_drain_status_failed",
            room_id="room-worker-drain-status-fail",
        )
        self.assertTrue(status_failure_entries)
        status_payload = status_failure_entries[-1].payload
        self.assertEqual(status_payload["reason"], "RuntimeState persistence failed")
        self.assertNotIn("provider", str(status_payload).lower())
        self.assertNotIn("raw", str(status_payload).lower())
        self.assertNotIn("https://", str(status_payload).lower())

        runtime.status_summary = original_status_summary  # type: ignore[method-assign]
        status = runtime.status_summary("room-worker-drain-status-fail", external_plan_id="seed-worker-drain-status-fail")
        self.assertEqual(status["tool_graph_summary"]["queue_status_counts"], {"completed": 1})
        self.assertGreaterEqual(status["scene_entity_registry"]["actor_count"], 1)

