    def test_sync_external_plan_context_updates_one_runtime_plan_without_execution(self) -> None:
        runtime = AgentRuntime()

        first = runtime.sync_external_plan_context(
            room_id="room-external-context",
            external_plan_id="seed-context",
            text="鍥寸粫寮虹洍钘忓疂瀹ゅ仛涓€涓柟妗堬紝鍖呭惈瀹濈鍜岄噾甯?",
            owner_agent="山贼",
        )
        runtime.scene_plans.pop(first.plan_id, None)
        second = runtime.sync_external_plan_context(
            room_id="room-external-context",
            external_plan_id="seed-context",
            text="鍦ㄩ暱鑰呮柟妗堝熀纭€涓婃敼鎴愬晢浼氫氦鏄撳巺锛屾湁涓績璁环鍖哄拰灞曠ず鍖?",
            owner_agent="商人",
            source_context_agents=["闀胯€?"],
        )
        state = runtime.query_state("room-external-context")["room"]

        self.assertEqual(first.plan_id, second.plan_id)
        self.assertEqual(state["external_plan_links"]["seed-context"], first.plan_id)
        self.assertEqual(state["scene_plans"][first.plan_id]["owner_agent"], "商人")
        self.assertIn("闀胯€?", state["scene_plans"][first.plan_id]["source_context_agents"])
        self.assertEqual(
            state["model_item_lists"][first.plan_id],
            state["scene_plans"][first.plan_id]["concrete_object_items"],
        )
        self.assertIn(first.plan_id, state["plan_extractions"])
        self.assertEqual(self._non_planning_tool_graphs(state), [])
        self.assertEqual(len(state["planning_context_events"]), 2)
        self.assertTrue(state["planning_context_events"][0]["created"])
        self.assertFalse(state["planning_context_events"][1]["created"])
        self.assertTrue(state["planning_context_events"][1]["text_preview"])
        summary = runtime.status_summary("room-external-context", external_plan_id="seed-context")
        self.assertEqual(summary["planning_context_summary"]["context_count"], 2)
        self.assertTrue(summary["planning_context_summary"]["latest_context"][-1]["text_preview"])
        report = runtime.generate_report("room-external-context", plan_id=first.plan_id)
        self.assertEqual(report["planning_context_summary"]["context_count"], 2)
        state_latest_context = state["planning_context_events"][-1]
        self.assertIn("context_id", state_latest_context)
        self.assertEqual(state_latest_context["external_plan_id"], "seed-context")
        status_context_text = str(summary["planning_context_summary"])
        report_context_text = str(report["planning_context_summary"])
        self.assertNotIn("context_id", status_context_text)
        self.assertNotIn("external_plan_id", status_context_text)
        self.assertNotIn("context_id", report_context_text)
        self.assertNotIn("external_plan_id", report_context_text)
        context_events = [
            event for event in runtime.user_visible_events("room-external-context", plan_id=first.plan_id)
            if event["event_type"] == "planning_context_recorded"
        ]
        self.assertEqual(len(context_events), 2)
        self.assertEqual(context_events[-1]["payload"]["status"], "updated")
        event_text = str(context_events[-1])
        self.assertNotIn("context_id", event_text)
        self.assertNotIn("metadata", event_text)
        self.assertNotIn("tool_name", event_text)
        replay = runtime.operation_replay(room_id="room-external-context", plan_id=first.plan_id)
        replay_context = replay["planning_context_summary"]
        self.assertEqual(replay_context["context_count"], 2)
        self.assertEqual(replay_context["context_type_counts"]["plan_context"], 2)
        self.assertEqual(replay_context["speaker_type_counts"]["user"], 2)
        self.assertTrue(replay_context["latest_context"][-1]["message"])
        self.assertNotIn("context_id", str(replay_context))
        self.assertNotIn("external_plan_id", str(replay_context))
        events = runtime.operation_log.events()
        self.assertIn("external_plan_context_synced", events)
        self.assertIn("external_plan_link_state_persisted", events)
        self.assertIn("external_plan_linked", events)
        self.assertLess(events.index("external_plan_link_state_persisted"), events.index("external_plan_linked"))
        self.assertGreaterEqual(events.count("scene_plan_extracted_via_tool_graph"), 2)
        self.assertGreaterEqual(events.count("planning_context_state_persisted"), 2)
        self.assertLess(events.index("planning_context_state_persisted"), events.index("external_plan_context_synced"))

