    def test_record_agent_context_message_does_not_emit_when_context_state_fails(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.sync_external_plan_context(
            room_id="room-agent-context-persist-fail",
            external_plan_id="seed-agent-context-persist-fail",
            text="鍥寸粫寮虹洍钘忓疂瀹ゅ仛涓€涓柟妗堬紝鍖呭惈瀹濈鍜岄噾甯?",
            owner_agent="山贼",
        )
        visible_before = runtime.user_visible_events("room-agent-context-persist-fail", plan_id=plan.plan_id)
        original_apply_patch = runtime.state.apply_patch

        def fail_agent_context_once(patch: StatePatch) -> tuple[bool, str]:
            if "planning_context_events" in (patch.changes or {}):
                return False, "simulated agent context persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = fail_agent_context_once  # type: ignore[method-assign]

        with self.assertRaises(RuntimeError):
            runtime.record_agent_context_message(
                room_id="room-agent-context-persist-fail",
                external_plan_id="seed-agent-context-persist-fail",
                text="鎴戝缓璁鍔犻棰嗗骇妞呭拰鍦板浘妗岋紝寮哄寲寮虹洍鎹偣鎰熴€?",
                agent_id="agent-merchant",
                agent_name="商人",
                reply_to="msg-123",
            )

        state = runtime.query_state("room-agent-context-persist-fail")["room"]
        self.assertEqual(len(state["planning_context_events"]), 1)
        events = runtime.operation_log.events()
        self.assertIn("planning_context_state_persist_failed", events)
        self.assertNotIn("agent_context_message_recorded", events)
        visible_after = runtime.user_visible_events("room-agent-context-persist-fail", plan_id=plan.plan_id)
        self.assertEqual(
            [
                event
                for event in visible_after
                if event["event_type"] == "planning_context_recorded"
                and event["payload"].get("status") == "agent_reply"
            ],
            [],
        )

    def test_record_agent_context_message_can_promote_reply_to_active_plan(self) -> None:
        runtime = AgentRuntime()
