    def test_record_user_context_message_without_plan_does_not_emit_when_state_fails(self) -> None:
        runtime = AgentRuntime()
        original_apply_patch = runtime.state.apply_patch

        def fail_room_chat_context_once(patch: StatePatch) -> tuple[bool, str]:
            if "planning_context_events" in (patch.changes or {}):
                return False, "simulated room chat context persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = fail_room_chat_context_once  # type: ignore[method-assign]

        with self.assertRaises(RuntimeError):
            runtime.record_user_context_message(
                room_id="room-chat-only-persist-fail",
                text="浠婂ぉ鍏堜笉鐢熸垚锛屽ぇ瀹跺厛浠嬬粛涓€涓嬭嚜宸便€?",
                sender_id="host-1",
                sender_name="房主",
                reply_to="msg-chat-only",
            )

        state = runtime.query_state("room-chat-only-persist-fail")["room"]
        self.assertEqual(state["planning_context_events"], [])
        events = runtime.operation_log.events()
        self.assertIn("planning_context_state_persist_failed", events)
        self.assertNotIn("room_chat_message_recorded", events)
        runtime_events = runtime.user_visible_events("room-chat-only-persist-fail")
        self.assertEqual(
            [
                event
                for event in runtime_events
                if event["event_type"] == "room_chat_recorded"
            ],
            [],
        )

