    def test_runtime_pause_resume_cancel_commands_update_state_without_legacy_scheduler(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-runtime-command",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈銆侀噾甯併€佺伀鎶婂拰鏈ㄦ《",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        paused = runtime.handle_message(
            room_id="room-runtime-command",
            text="鍏堟殏鍋滀竴涓?",
            sender_id="host-1",
            sender_name="房主",
            action="pause_generation",
        )
        state = runtime.query_state("room-runtime-command")["room"]
        self.assertTrue(paused["command"]["applied"])
        self.assertTrue(paused["command"]["command_recorded"])
        self.assertEqual(paused["command"]["graph_status"], "completed")
        self.assertEqual(paused["command"]["tool_call_status"], "succeeded")
        self.assertGreaterEqual(paused["command"]["state_version"], 1)
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "paused")
        command_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.command.record"}
        ]
        self.assertEqual(len(command_graphs), 1)
        self.assertEqual(command_graphs[-1]["status"], "completed")
        self.assertEqual(state["runtime_commands"][-1]["command"], "pause")

        resumed = runtime.handle_message(
            room_id="room-runtime-command",
            text="鎭㈠鏂规",
            sender_id="host-1",
            sender_name="房主",
            action="resume_generation",
        )
        state = runtime.query_state("room-runtime-command")["room"]
        self.assertTrue(resumed["command"]["applied"])
        self.assertTrue(resumed["command"]["command_recorded"])
        self.assertEqual(resumed["command"]["graph_status"], "completed")
        self.assertEqual(resumed["command"]["tool_call_status"], "succeeded")
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "confirmed")

        runtime.plan_batches(plan.plan_id, max_items_per_batch=2)
        runtime.registry.register(
            "mock.queued_before_cancel",
            lambda call: ToolResult(True, "should not run"),
            required_args=("room_id",),
        )
        queued_graph = ToolCallGraph(graph_id="graph-command-cancel-queued", plan_id=plan.plan_id)
        queued_graph.add(
            ToolCall(
                tool_call_id="tool-command-cancel-queued",
                tool_name="mock.queued_before_cancel",
                args={"room_id": "room-runtime-command"},
            )
        )
        runtime._enqueue_tool_graph(queued_graph, room_id="room-runtime-command")
        cancelled = runtime.handle_message(
            room_id="room-runtime-command",
            text="鍙栨秷杩欐鐢熸垚",
            sender_id="host-1",
            sender_name="房主",
            action="cancel_generation",
        )
        state = runtime.query_state("room-runtime-command")["room"]
        self.assertTrue(cancelled["command"]["applied"])
        self.assertTrue(cancelled["command"]["command_recorded"])
        self.assertEqual(cancelled["command"]["graph_status"], "completed")
        self.assertEqual(cancelled["command"]["tool_call_status"], "succeeded")
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "cancelled")
        self.assertTrue(state["batch_plans"])
        self.assertTrue(all(batch["status"] == "cancelled" for batch in state["batch_plans"].values()))
        self.assertEqual(state["tool_graph_queue"][queued_graph.graph_id]["status"], "cancelled")
        self.assertEqual(state["tool_graphs"][queued_graph.graph_id]["status"], "cancelled")
        unfinished_node_statuses = {
            str(node.get("status") or "")
            for graph in [state["tool_graphs"][queued_graph.graph_id]]
            for node in dict(graph.get("nodes") or {}).values()
        }
        self.assertFalse(unfinished_node_statuses & {"planned", "ready", "running"})
        self.assertIsNone(runtime.drain_next_tool_graph("room-runtime-command", plan_id=plan.plan_id))
        summary = runtime.status_summary("room-runtime-command")
        self.assertEqual(summary["runtime_command_summary"]["command_count"], 3)
        self.assertEqual(summary["runtime_command_summary"]["latest_commands"][-1]["command"], "cancel")
        self.assertNotIn("command_id", str(summary["runtime_command_summary"]))
        report = runtime.generate_report("room-runtime-command", plan_id=plan.plan_id)
        self.assertEqual(report["runtime_command_summary"]["latest_commands"][-1]["new_status"], "cancelled")
        self.assertNotIn("command_id", str(report["runtime_command_summary"]))
        replay = runtime.operation_replay(room_id="room-runtime-command", plan_id=plan.plan_id)
        replay_command_summary = replay["runtime_command_summary"]
        self.assertEqual(replay_command_summary["command_counts"], {"cancel": 1, "pause": 1, "resume": 1})
        self.assertGreaterEqual(replay_command_summary["cancelled_batch_total"], 1)
        self.assertGreaterEqual(replay_command_summary["cancelled_graph_total"], 1)
        self.assertEqual(replay_command_summary["resumed_graph_total"], 0)
        self.assertEqual(replay_command_summary["latest_command"]["command"], "cancel")
        self.assertEqual(replay_command_summary["latest_command"]["new_status"], "cancelled")
        report_replay_summary = report["operation_replay_summary"]["runtime_command_summary"]
        self.assertEqual(report_replay_summary["cancelled_batch_total"], replay_command_summary["cancelled_batch_total"])
        self.assertEqual(report_replay_summary["cancelled_graph_total"], replay_command_summary["cancelled_graph_total"])
        self.assertNotIn("command_id", str(replay_command_summary))
        self.assertNotIn("command_id", str(report_replay_summary))
        self.assertIn("command_id", state["runtime_commands"][-1])
        events = runtime.operation_log.events()
        self.assertIn("runtime_command_state_persisted", events)
        latest_runtime_event = [
            event
            for event in runtime.user_visible_events("room-runtime-command", plan_id=plan.plan_id, limit=20)
            if event["event_type"] == "runtime_cancel"
        ][-1]
        self.assertTrue(latest_runtime_event["payload"]["command_recorded"])
        self.assertEqual(latest_runtime_event["payload"]["graph_status"], "completed")
        self.assertEqual(latest_runtime_event["payload"]["tool_call_status"], "succeeded")
        self.assertGreaterEqual(latest_runtime_event["payload"]["state_version"], 1)
        self.assertIn("runtime_pause_command_applied", events)
        self.assertIn("runtime_resume_command_applied", events)
        self.assertIn("runtime_cancel_command_applied", events)
        self.assertGreaterEqual(events.count("tool_call_succeeded"), 3)
        runtime_command_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.command.record"}
        ]
        self.assertGreaterEqual(len(runtime_command_graphs), 3)
        self.assertTrue(all(graph["status"] == "completed" for graph in runtime_command_graphs[-3:]))
        command_state_indexes = [
            index for index, event in enumerate(events) if event == "runtime_command_state_persisted"
        ]
        self.assertGreaterEqual(len(command_state_indexes), 3)
        self.assertLess(command_state_indexes[0], events.index("runtime_pause_command_applied"))
        self.assertLess(command_state_indexes[1], events.index("runtime_resume_command_applied"))
        self.assertLess(command_state_indexes[2], events.index("runtime_cancel_command_applied"))

