    def test_retry_generation_command_reopens_failed_plan_without_auto_execution(self) -> None:
        image_provider_state = {"fail": True}

        def failing_image_provider(payload: dict) -> dict:
            if image_provider_state["fail"]:
                raise RuntimeError("provider offline")
            return {
                name: {
                    "name": name,
                    "status": "recovered-image",
                    "batch_id": payload["batch_id"],
                    "image_url": f"runtime://image/{name}",
                }
                for name in payload.get("model_items", [])
            }

        runtime = AgentRuntime(image_resource_provider=failing_image_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-runtime-retry",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岄噾甯?",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")
        runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)
        failed_state = runtime.query_state("room-runtime-retry")["room"]
        failed_graph_count = len(failed_state["tool_graph_queue"])
        failed_graph_id = next(iter(failed_state["tool_graph_queue"]))
        failed_graph = failed_state["tool_graphs"][failed_graph_id]
        self.assertEqual(failed_state["scene_plans"][plan.plan_id]["status"], "failed")
        self.assertEqual(failed_state["tool_graph_queue"][failed_graph_id]["status"], "failed")
        self.assertEqual(failed_graph["status"], "failed")
        self.assertTrue(
            any(
                node["status"] in {"failed", "skipped"}
                for node in failed_graph["nodes"].values()
            )
        )

        retried = runtime.handle_message(
            room_id="room-runtime-retry",
            text="閲嶈瘯杩欐鐢熸垚",
            sender_id="host-1",
            sender_name="房主",
            action="retry_generation",
        )
        state = runtime.query_state("room-runtime-retry")["room"]

        self.assertTrue(retried["command"]["applied"])
        self.assertEqual(retried["command"]["command"], "retry")
        self.assertEqual(retried["command"]["old_status"], "failed")
        self.assertEqual(retried["command"]["new_status"], "confirmed")
        self.assertEqual(retried["command"]["retried_graphs"], 1)
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "confirmed")
        self.assertEqual(len(state["tool_graph_queue"]), failed_graph_count)
        self.assertEqual(state["tool_graph_queue"][failed_graph_id]["status"], "queued")
        self.assertEqual(state["tool_graphs"][failed_graph_id]["status"], "queued")
        self.assertEqual(
            state["tool_graphs"][failed_graph_id]["generation"],
            int(failed_graph.get("generation") or 0) + 1,
        )
        self.assertTrue(
            all(
                node["status"] != "failed"
                for node in state["tool_graphs"][failed_graph_id]["nodes"].values()
            )
        )
        self.assertEqual(state["runtime_commands"][-1]["command"], "retry")
        events = runtime.operation_log.events()
        self.assertIn("runtime_retry_command_applied", events)
        runtime_events = runtime.user_visible_events("room-runtime-retry", plan_id=plan.plan_id)
        retry_events = [event for event in runtime_events if event["event_type"] == "runtime_retry"]
        self.assertEqual(len(retry_events), 1)
        self.assertEqual(retry_events[0]["payload"]["status"], "confirmed")
        self.assertEqual(retry_events[0]["payload"]["command"], "retry")
        self.assertTrue(retry_events[0]["payload"]["command_recorded"])
        self.assertEqual(retry_events[0]["payload"]["graph_status"], "completed")
        self.assertEqual(retry_events[0]["payload"]["tool_call_status"], "succeeded")
        self.assertGreaterEqual(retry_events[0]["payload"]["state_version"], 1)
        status = runtime.status_summary("room-runtime-retry", plan_id=plan.plan_id)
        self.assertEqual(status["runtime_command_summary"]["latest_commands"][-1]["command"], "retry")
        replay = runtime.operation_replay(room_id="room-runtime-retry", plan_id=plan.plan_id)
        self.assertEqual(replay["runtime_command_summary"]["command_counts"]["retry"], 1)
        self.assertEqual(replay["runtime_command_summary"]["latest_command"]["old_status"], "failed")
        self.assertEqual(replay["runtime_command_summary"]["latest_command"]["new_status"], "confirmed")
        self.assertEqual(replay["runtime_command_summary"]["retried_graph_total"], 1)
        self.assertEqual(replay["runtime_command_summary"]["latest_command"]["retried_graphs"], 1)
        report = runtime.generate_report("room-runtime-retry", plan_id=plan.plan_id)
        self.assertEqual(
            report["operation_replay_summary"]["runtime_command_summary"]["latest_command"]["command"],
            "retry",
        )
        self.assertEqual(report["operation_replay_summary"]["runtime_command_summary"]["retried_graph_total"], 1)
        self.assertNotIn("command_id", str(replay["runtime_command_summary"]))
        self.assertNotIn("command_id", str(report["operation_replay_summary"]["runtime_command_summary"]))

        image_provider_state["fail"] = False
        drained = runtime.drain_tool_graph_queue("room-runtime-retry", plan_id=plan.plan_id, max_graphs=1)
        self.assertEqual(drained["drained_count"], 1)
        self.assertEqual(drained["graphs"][0]["graph_id"], failed_graph_id)
        self.assertEqual(drained["graphs"][0]["status"], "completed")
        retried_state = runtime.query_state("room-runtime-retry")["room"]
        self.assertEqual(retried_state["tool_graph_queue"][failed_graph_id]["status"], "completed")
        retried_batches = [
            batch
            for batch in retried_state["batch_plans"].values()
            if batch["plan_id"] == plan.plan_id
        ]
        self.assertEqual(retried_batches[0]["status"], "completed")

    def test_handle_message_runtime_command_persist_failure_returns_safe_failure(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-runtime-command-fail",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈銆侀噾甯併€佺伀鎶婂拰鏈ㄦ《",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        original_apply_patch = runtime.state.apply_patch

        def reject_runtime_command_patch(patch):
            if "runtime_commands" in patch.changes:
                return False, "simulated provider/raw/internal command persistence failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_runtime_command_patch

        result = runtime.handle_message(
            room_id="room-runtime-command-fail",
            text="鍏堟殏鍋滀竴涓?",
            sender_id="host-1",
            sender_name="房主",
            action="pause_generation",
        )
        state = runtime.query_state("room-runtime-command-fail")["room"]
        events = runtime.operation_log.events()
        visible_events = runtime.user_visible_events("room-runtime-command-fail", plan_id=plan.plan_id)

        self.assertTrue(result["handled"])
        self.assertFalse(result["recorded"])
        self.assertFalse(result["command"]["applied"])
        self.assertEqual(result["command"]["reason"], "RuntimeState persistence failed")
        self.assertIn("RuntimeState persistence failed", result["message"])
        self.assertNotIn("provider", result["message"])
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "confirmed")
        self.assertIn("runtime_command_state_persist_failed", events)
        self.assertNotIn("runtime_pause_command_applied", events)
        self.assertFalse(any(event["event_type"] == "runtime_pause" for event in visible_events))

    def test_handle_message_runtime_command_exception_is_operation_logged_safely(self) -> None:
        runtime = AgentRuntime()
        runtime.propose_scene_plan(
            room_id="room-runtime-command-exception-fail",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈銆侀噾甯併€佺伀鎶婂拰鏈ㄦ《",
            owner_agent="商人",
        )

        def fail_apply_runtime_command(
            *,
            room_id: str,
            command: str,
            external_plan_id: str = "",
            plan_id: str = "",
            source_user: str = "",
            reason: str = "",
        ) -> dict[str, Any]:
            raise RuntimeError("provider raw url https://internal.example/command")

        runtime.apply_runtime_command = fail_apply_runtime_command  # type: ignore[method-assign]

        result = runtime.handle_message(
            room_id="room-runtime-command-exception-fail",
            text="鍏堟殏鍋滀竴涓?",
            sender_id="host-1",
            sender_name="房主",
            action="pause_generation",
        )

        self.assertTrue(result["handled"])
        self.assertFalse(result["recorded"])
        self.assertFalse(result["command"]["applied"])
        self.assertEqual(result["command"]["reason"], "RuntimeState persistence failed")
        self.assertIn("RuntimeState persistence failed", result["message"])
        self.assertNotIn("provider", result["message"].lower())
        self.assertNotIn("raw", result["message"].lower())
        events = runtime.operation_log.events()
        self.assertIn("runtime_command_apply_failed", events)
        self.assertNotIn("runtime_pause_command_applied", events)
        failure_entries = runtime.operation_log.query(
            event="runtime_command_apply_failed",
            room_id="room-runtime-command-exception-fail",
        )
        self.assertTrue(failure_entries)
        payload = failure_entries[-1].payload
        self.assertEqual(payload["reason"], "RuntimeState persistence failed")
        self.assertNotIn("provider", str(payload).lower())
        self.assertNotIn("raw", str(payload).lower())
        self.assertNotIn("https://", str(payload).lower())

    def test_runtime_command_event_validator_rejects_internal_fields(self) -> None:
        valid_event = {
            "command_id": "cmd-safe",
            "room_id": "room-command-validator",
            "plan_id": "plan-command-validator",
            "external_plan_id": "",
            "command": "pause",
            "old_status": "confirmed",
            "new_status": "paused",
            "source_user": "房主",
            "reason_preview": "鍏堟殏鍋?",
            "timestamp": 1.0,
        }
        for command, old_status, new_status in (
            ("pause", "confirmed", "paused"),
            ("cancel", "confirmed", "cancelled"),
            ("resume", "paused", "confirmed"),
            ("retry", "failed", "confirmed"),
        ):
            command_event = dict(valid_event)
            command_event["command"] = command
            command_event["old_status"] = old_status
            command_event["new_status"] = new_status
            RuntimeCommandEventValidator.validate(command_event)

        unsafe_event = dict(valid_event)
        unsafe_event["tool_call_id"] = "hidden-tool"
        with self.assertRaisesRegex(ValueError, "runtime command event cannot expose field: tool_call_id"):
            RuntimeCommandEventValidator.validate(unsafe_event)

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-command-invalid",
                changes={"runtime_commands": [unsafe_event]},
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("runtime command event cannot expose field: tool_call_id", reason)

    def test_runtime_command_event_validator_rejects_unsafe_text_values(self) -> None:
        valid_event = {
            "command_id": "cmd-safe-text",
            "room_id": "room-command-safe-text",
            "plan_id": "plan-command-safe-text",
            "external_plan_id": "",
            "command": "pause",
            "old_status": "confirmed",
            "new_status": "paused",
            "source_user": "房主",
            "reason_preview": "鍏堟殏鍋滐紝鎴戝啀鏁寸悊 prompt銆?",
            "timestamp": 1.0,
        }
        RuntimeCommandEventValidator.validate(valid_event)

        unsafe_reason = dict(valid_event)
        unsafe_reason["reason_preview"] = "provider raw C:\\\\secret\\\\command prompt=hidden"
        with self.assertRaisesRegex(ValueError, "runtime command event reason_preview contains unsafe text"):
            RuntimeCommandEventValidator.validate(unsafe_reason)

        runtime = AgentRuntime()
        unsafe_room = dict(valid_event)
        unsafe_room["room_id"] = "https://internal.example/room"
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-command-unsafe-text",
                changes={"runtime_commands": [unsafe_room]},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("runtime command event room_id contains unsafe text", reason)

    def test_paused_or_cancelled_plan_cannot_enter_batch_execution(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-runtime-command-guard",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈銆侀噾甯佸拰鐏妸",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        runtime.apply_runtime_command(
            room_id="room-runtime-command-guard",
            command="pause",
            plan_id=plan.plan_id,
            source_user="房主",
            reason="鍏堟殏鍋?",
        )
        with self.assertRaisesRegex(ValueError, "paused"):
            runtime.execute_planned_batches(plan.plan_id)
        state = runtime.query_state("room-runtime-command-guard")["room"]
        self.assertEqual(self._non_planning_tool_graphs(state), [])

        runtime.apply_runtime_command(
            room_id="room-runtime-command-guard",
            command="resume",
            plan_id=plan.plan_id,
            source_user="房主",
            reason="鎭㈠",
        )
        runtime.apply_runtime_command(
            room_id="room-runtime-command-guard",
            command="cancel",
            plan_id=plan.plan_id,
            source_user="房主",
            reason="取消",
        )
        with self.assertRaisesRegex(ValueError, "cancelled"):
            runtime.execute_scene_plan(plan.plan_id)
        state = runtime.query_state("room-runtime-command-guard")["room"]
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], "cancelled")

