    def test_operation_log_query_and_snapshot_filter_replay_slice(self) -> None:
        log = OperationLog()
        log.append("scene_plan_created", room_id="room-a", plan_id="plan-a")
        log.append("scene_plan_created", room_id="room-b", plan_id="plan-b")
        log.append(
            "tool_call_succeeded",
            room_id="room-a",
            plan_id="plan-a",
            tool_call_id="tool-a",
            message="provider=secret-provider prompt=hidden prompt url=https://example.invalid/private",
            payload={
                "status": "ok",
                "reason": "prompt=hidden prompt asset_path=E:/private/model.glb",
                "external_plan_id": "seed-private",
                "patch_id": "patch-private",
                "asset_path": "E:/private/model.glb",
                "prompt": "hidden prompt",
                "url": "https://example.invalid/private",
                "provider": "secret-provider",
            },
        )

        room_a_entries = log.query(room_id="room-a")
        self.assertEqual([entry.event for entry in room_a_entries], ["scene_plan_created", "tool_call_succeeded"])
        self.assertEqual(room_a_entries[-1].payload["asset_path"], "E:/private/model.glb")
        self.assertEqual(room_a_entries[-1].payload["external_plan_id"], "seed-private")
        self.assertEqual(room_a_entries[-1].payload["patch_id"], "patch-private")
        self.assertEqual(log.query(tool_call_id="tool-a")[-1].tool_call_id, "tool-a")

        snapshot = log.snapshot(room_id="room-a", plan_id="plan-a")
        self.assertEqual(snapshot["entry_count"], 2)
        self.assertEqual(snapshot["event_counts"]["scene_plan_created"], 1)
        self.assertEqual(snapshot["event_counts"]["tool_call_succeeded"], 1)
        self.assertEqual(snapshot["entries"][0]["room_id"], "room-a")
        self.assertEqual(snapshot["entries"][-1]["message"], "[redacted]")
        self.assertEqual(snapshot["entries"][-1]["payload"], {"status": "ok", "reason": "[redacted]"})
        self.assertNotIn("tool_call_id", str(snapshot))
        self.assertNotIn("external_plan_id", str(snapshot))
        self.assertNotIn("patch_id", str(snapshot))
        self.assertNotIn("asset_path", str(snapshot))
        self.assertNotIn("E:/private", str(snapshot))
        self.assertNotIn("https://example.invalid", str(snapshot))
        self.assertNotIn("hidden prompt", str(snapshot))
        self.assertNotIn("secret-provider", str(snapshot))

