    def test_message_delivery_summary_is_derived_from_safe_operation_log(self) -> None:
        runtime = AgentRuntime()
        runtime.operation_log.append(
            "agent_reply_send_requested",
            room_id="room-send-summary",
            plan_id="plan-send-summary",
            payload={
                "message_kind": "agent_reply",
                "channel": "network_send_agent_reply_ex",
                "sent": False,
                "stage": "资源调度",
                "progress": 10,
                "provider": "secret-provider",
                "prompt": "hidden prompt",
            },
        )
        runtime.operation_log.append(
            "agent_reply_send_failed",
            room_id="room-send-summary",
            plan_id="plan-send-summary",
            payload={
                "message_kind": "agent_reply",
                "channel": "network_send_agent_reply_ex",
                "sent": False,
                "stage": "资源调度",
                "progress": 10,
                "url": "https://example.invalid/private",
                "asset_path": "E:/private/model.glb",
            },
        )
        runtime.operation_log.append(
            "runtime_system_event_send_succeeded",
            room_id="room-send-summary",
            plan_id="plan-send-summary",
            payload={
                "message_kind": "runtime_status",
                "channel": "network_send_system_message_ex",
                "sent": True,
                "stage": "导入",
                "progress": 80,
            },
        )

        replay = runtime.operation_replay(room_id="room-send-summary", plan_id="plan-send-summary")
        summary = replay["message_delivery_summary"]
        self.assertEqual(summary["requested_count"], 1)
        self.assertEqual(summary["succeeded_count"], 1)
        self.assertEqual(summary["failed_count"], 1)
        self.assertEqual(summary["message_kind_counts"]["agent_reply"], 2)
        self.assertEqual(summary["message_kind_counts"]["runtime_status"], 1)
        self.assertEqual(summary["channel_counts"]["network_send_agent_reply_ex"], 2)
        self.assertEqual(summary["latest_message_kind"], "runtime_status")
        self.assertEqual(summary["latest_channel"], "network_send_system_message_ex")
        self.assertEqual(summary["latest_stage"], "导入")
        self.assertEqual(summary["latest_progress"], 80)

        status = runtime.status_summary(room_id="room-send-summary", plan_id="plan-send-summary")
        self.assertEqual(status["message_delivery_summary"]["failed_count"], 1)
        report = runtime.generate_report(room_id="room-send-summary", plan_id="plan-send-summary")
        self.assertEqual(report["operation_replay_summary"]["message_delivery_summary"]["succeeded_count"], 1)
        self.assertNotIn("secret-provider", str(replay))
        self.assertNotIn("hidden prompt", str(replay))
        self.assertNotIn("https://example.invalid", str(replay))
        self.assertNotIn("E:/private", str(replay))
        self.assertNotIn("secret-provider", str(status))
        self.assertNotIn("hidden prompt", str(report))

