    def test_handle_message_runtime_events_lists_safe_events_without_creating_plan(self) -> None:
        runtime = AgentRuntime()
        runtime.emit_runtime_event(
            room_id="room-runtime-event-action",
            event_type="resource_progress",
            phase="resource",
            title="鏃т簨浠?",
            message="杈冩棭鐨勪簨浠躲€?",
            payload={"status": "running", "provider": "hidden"},
        )
        older_timestamp = runtime.user_visible_events("room-runtime-event-action")[-1]["timestamp"]
        runtime.emit_runtime_event(
            room_id="room-runtime-event-action",
            event_type="tool_result_message",
            phase="resource",
            title="鏂颁簨浠?",
            message="鍙互鎶湶鐨勬柊浜嬩欢銆?",
            payload={"status": "succeeded", "tool_name": "hidden"},
        )

        result = runtime.handle_message(
            room_id="room-runtime-event-action",
            text="",
            action="runtime_events",
            sync_event={"limit": 8, "after_timestamp": older_timestamp},
        )
        room = runtime.query_state("room-runtime-event-action")["room"]

        self.assertTrue(result["handled"])
        self.assertTrue(result["recorded"])
        self.assertTrue(result["snapshot_recorded"])
        self.assertEqual(result["snapshot_status"], "completed")
        self.assertEqual(result["snapshot_tool_status"], ToolCallStatus.SUCCEEDED.value)
        self.assertGreaterEqual(result["snapshot_state_version"], 1)
        self.assertEqual(result["action"], "runtime_events")
        self.assertEqual(result["event_count"], 1)
        self.assertEqual(result["runtime_events"][0]["title"], "鏂颁簨浠?")
        self.assertEqual(result["runtime_events"][0]["payload"], {"status": "succeeded"})
        events_fact = runtime.query_state("runtime-events-snapshot")["room"]["custom_report_facts"][
            "room-runtime-event-action:room:all:all:8:runtime_events"
        ]
        self.assertEqual(events_fact["source"], "runtime_events_snapshot")
        self.assertEqual(events_fact["runtime_events"], result["runtime_events"])
        self.assertEqual(events_fact["event_count"], 1)
        self.assertNotIn("snapshot_recorded", events_fact)
        self.assertNotIn("snapshot_status", events_fact)
        self.assertNotIn("snapshot_tool_status", events_fact)
        self.assertNotIn("snapshot_state_version", events_fact)
        self.assertEqual(room["scene_plans"], {})
        self.assertTrue(room["tool_graphs"])
        self.assertTrue(
            all(
                str(graph.get("nodes") or "").find("runtime.event.emit") >= 0
                for graph in dict(room["tool_graphs"]).values()
            )
        )
        self.assertIn("runtime_events_queried", runtime.operation_log.events())
        self.assertIn("runtime_events_snapshot_recorded", runtime.operation_log.events())
        routed = runtime.operation_log.snapshot(
            room_id="room-runtime-event-action",
            event="runtime_message_action_routed",
        )
        self.assertEqual(routed["entries"][-1]["payload"]["category"], "read_only")
        self.assertFalse(routed["entries"][-1]["payload"]["may_create_plan"])

    def test_handle_message_runtime_events_snapshot_failure_does_not_return_unrecorded_feed(self) -> None:
        runtime = AgentRuntime()
        runtime.emit_runtime_event(
            room_id="room-runtime-event-snapshot-failure",
            event_type="resource_progress",
            phase="resource",
            title="璧勬簮鍑嗗涓?",
            message="姝ｅ湪鍑嗗銆?",
            payload={"status": "running"},
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_runtime_events_fact(patch):  # type: ignore[no-untyped-def]
            if patch.room_id == "runtime-events-snapshot" and "custom_report_facts" in patch.changes:
                return False, "runtime events snapshot rejected"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_runtime_events_fact  # type: ignore[method-assign]

        result = runtime.handle_message(
            room_id="room-runtime-event-snapshot-failure",
            text="",
            action="runtime_events",
            sync_event={"limit": 8},
        )

        self.assertTrue(result["handled"])
        self.assertFalse(result["recorded"])
        self.assertEqual(result["runtime_events"], [])
        self.assertEqual(result["event_count"], 0)
        self.assertIn("runtime_events_snapshot_failed", runtime.operation_log.events())
        queried = runtime.operation_log.query(
            room_id="room-runtime-event-snapshot-failure",
            event="runtime_events_queried",
            limit=1,
        )
        self.assertTrue(queried)
        self.assertFalse(queried[-1].payload["recorded"])
        self.assertEqual(queried[-1].payload["reason"], "RuntimeState persistence failed")

