    def test_user_visible_events_use_batch_scope_when_plan_id_is_missing(self) -> None:
        runtime = AgentRuntime()
        first = runtime.propose_scene_plan(
            room_id="room-event-batch-only",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            owner_agent="山贼",
        )
        second = runtime.propose_scene_plan(
            room_id="room-event-batch-only",
            text="鍋氫竴涓．鏋楄惀鍦帮紝鏈夊笎绡峰拰鏈ㄦ",
            owner_agent="闀胯€?",
        )
        runtime.confirm_scene_plan(first.plan_id, confirmed_by="房主")
        runtime.confirm_scene_plan(second.plan_id, confirmed_by="房主")
        first_batch = runtime.plan_batches(first.plan_id, max_items_per_batch=2)[0]
        second_batch = runtime.plan_batches(second.plan_id, max_items_per_batch=2)[0]
        ok, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-event-batch-only",
                changes={
                    "runtime_events": [
                        {
                            "event_id": "evt-first-batch-only",
                            "room_id": "room-event-batch-only",
                            "batch_id": first_batch.batch_id,
                            "event_type": "resource_progress",
                            "phase": "resource",
                            "audience": "host",
                            "level": "info",
                            "title": "钘忓疂瀹よ祫婧愬噯澶?",
                            "message": "姝ｅ湪鍑嗗钘忓疂瀹よ祫婧愩€?",
                            "progress": 40,
                            "payload": {"status": "running", "item_count": 2},
                            "timestamp": 10.0,
                        },
                        {
                            "event_id": "evt-second-batch-only",
                            "room_id": "room-event-batch-only",
                            "batch_id": second_batch.batch_id,
                            "event_type": "resource_progress",
                            "phase": "resource",
                            "audience": "host",
                            "level": "info",
                            "title": "妫灄钀ュ湴璧勬簮鍑嗗",
                            "message": "姝ｅ湪鍑嗗妫灄钀ュ湴璧勬簮銆?",
                            "progress": 80,
                            "payload": {"status": "running", "item_count": 2},
                            "timestamp": 20.0,
                        },
                    ]
                },
            )
        )
        self.assertTrue(ok, reason)

        visible = [
            event for event in runtime.user_visible_events("room-event-batch-only", plan_id=first.plan_id)
            if event["event_type"] == "resource_progress"
        ]
        summary = runtime.status_summary("room-event-batch-only", plan_id=first.plan_id)
        summary_resource_events = [
            event for event in summary["latest_runtime_events"]
            if event["event_type"] == "resource_progress"
        ]

        self.assertEqual([event["batch_id"] for event in visible], [first_batch.batch_id])
        self.assertEqual(visible[0]["title"], "钘忓疂瀹よ祫婧愬噯澶?")
