    def test_status_and_report_actor_count_are_plan_scoped(self) -> None:
        runtime = AgentRuntime()
        first = runtime.handle_message(
            room_id="room-actor-count-scope",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-actor-count-a",
            max_items_per_batch=2,
        )
        runtime.record_sync_event(
            room_id="room-actor-count-scope",
            event={
                "event": "actor_created",
                "actor_id": "actor-first",
                "actor_name": "绗竴璁″垝瀹濈",
                "timestamp": 10.0,
            },
            source="unit-test",
        )
        runtime.handle_message(
            room_id="room-actor-count-scope",
            text="鍋氫竴涓．鏋楄惀鍦帮紝鏈夊笎绡峰拰鏈ㄦ",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-actor-count-b",
            max_items_per_batch=2,
        )
        runtime.record_sync_event(
            room_id="room-actor-count-scope",
            event={
                "event": "actor_created",
                "actor_id": "actor-second",
                "actor_name": "绗簩璁″垝甯愮",
                "timestamp": 20.0,
            },
            source="unit-test",
        )

        status = runtime.status_summary(
            "room-actor-count-scope",
            plan_id=first["plan"]["plan_id"],
        )
        report = runtime.generate_report(
            "room-actor-count-scope",
            plan_id=first["plan"]["plan_id"],
        )
        state_actors = runtime.query_state("room-actor-count-scope")["room"]["actors"]
        expected_first_actor_count = sum(
            1
            for actor in state_actors.values()
            if actor.get("plan_id") == first["plan"]["plan_id"]
        )

        self.assertGreater(expected_first_actor_count, 0)
        self.assertEqual(status["actor_count"], expected_first_actor_count)
        self.assertEqual(report["actor_count"], expected_first_actor_count)
        report_events = [
            event
            for event in runtime.user_visible_events(
                "room-actor-count-scope",
                plan_id=first["plan"]["plan_id"],
            )
            if event.get("event_type") == "report_ready"
        ]
        self.assertTrue(report_events)
        self.assertEqual(report_events[-1]["payload"]["actor_count"], expected_first_actor_count)
        self.assertGreater(len(state_actors), expected_first_actor_count)

