    def test_sync_status_snapshot_failure_does_not_return_unrecorded_status(self) -> None:
        runtime = AgentRuntime()
        runtime.record_sync_event(
            room_id="room-sync-status-failure",
            event={
                "event": "actor_created",
                "room_id": "room-sync-status-failure",
                "actor_guid": "actor-001",
                "actor_name": "钘忓疂绠?",
            },
            source="unit-test",
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_sync_status_fact(patch):  # type: ignore[no-untyped-def]
            if patch.room_id == "runtime-sync-status" and "custom_report_facts" in patch.changes:
                return False, "sync status snapshot rejected"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_sync_status_fact  # type: ignore[method-assign]

        result = runtime.handle_message(
            room_id="room-sync-status-failure",
            text="runtime sync status",
            action="sync_status",
        )

        self.assertTrue(result["handled"])
        self.assertEqual(result["sync_status"], {})
        self.assertEqual(result["sync_replay"], {})
        self.assertEqual(result["asset_transfer_replay_summary"], {})
        self.assertEqual(result["peer_sync_replay_summary"], {})
        self.assertEqual(result["message_delivery_summary"], {})
        self.assertIn("runtime_sync_status_snapshot_failed", runtime.operation_log.events())
        self.assertIn("runtime_sync_status_export_failed", runtime.operation_log.events())

    def test_sync_status_action_with_external_plan_id_is_plan_scoped(self) -> None:
        runtime = AgentRuntime()
        first = runtime.handle_message(
            room_id="room-sync-status-scoped",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-sync-status-a",
            max_items_per_batch=2,
        )
        second = runtime.handle_message(
            room_id="room-sync-status-scoped",
            text="鍋氫竴涓．鏋楄惀鍦帮紝鏈夊笎绡峰拰鏈ㄦ",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-sync-status-b",
            max_items_per_batch=2,
        )
        runtime.record_sync_event(
            room_id="room-sync-status-scoped",
            event={
                "event": "actor_created",
                "actor_id": "actor-first-status",
                "actor_name": "绗竴璁″垝瀹濈",
                "plan_id": first["plan"]["plan_id"],
                "timestamp": 10.0,
            },
            source="unit-test",
        )
        runtime.record_sync_event(
            room_id="room-sync-status-scoped",
            event={
                "event": "asset_transfer_failed",
                "asset_id": "asset-second-status",
                "plan_id": second["plan"]["plan_id"],
                "status": "failed",
                "timestamp": 20.0,
            },
            source="unit-test",
        )

        result = runtime.handle_message(
            room_id="room-sync-status-scoped",
            text="runtime sync status",
            action="sync_status",
            external_plan_id="seed-sync-status-a",
        )

        sync_status = result["sync_status"]
        sync_replay = result["sync_replay"]
        self.assertTrue(result["handled"])
        self.assertEqual(sync_status["event_count"], 1)
        self.assertEqual(sync_status["actor_event_count"], 1)
        self.assertEqual(sync_status["asset_event_count"], 0)
        self.assertEqual(sync_status["latest_actors"][0]["actor_id"], "actor-first-status")
        self.assertEqual(sync_replay["recorded_count"], 1)
        self.assertEqual(sync_replay["actor_event_count"], 1)
        self.assertNotIn("asset-second-status", str(result))
        exported = runtime.operation_log.query(
            event="runtime_sync_status_exported",
            room_id="room-sync-status-scoped",
        )[-1]
        self.assertEqual(exported.plan_id, first["plan"]["plan_id"])
        self.assertEqual(exported.payload["external_plan_id"], "seed-sync-status-a")

