    def test_handle_message_intervention_persist_failure_returns_safe_failure(self) -> None:
        runtime = AgentRuntime()
        created = runtime.handle_message(
            room_id="room-intervention-message-fail",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            sender_id="host-1",
            sender_name="房主",
            action="plan",
            external_plan_id="seed-intervention-message-fail",
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_intervention_patch(patch: StatePatch) -> tuple[bool, str]:
            if "pending_interventions" in patch.changes:
                return False, "simulated intervention persist failure with provider/raw/internal details"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_intervention_patch  # type: ignore[method-assign]

        patch_result = runtime.handle_message(
            room_id="room-intervention-message-fail",
            text="鍐嶆坊鍔犱竴涓ぉ浣块洉鍍?",
            sender_id="host-1",
            sender_name="房主",
            action="intervention_add",
            external_plan_id="seed-intervention-message-fail",
        )

        room = runtime.query_state("room-intervention-message-fail")["room"]
        self.assertTrue(patch_result["handled"])
        self.assertFalse(patch_result["recorded"])
        self.assertEqual(patch_result["plan"]["plan_id"], created["plan"]["plan_id"])
        self.assertEqual(patch_result["patch"], {})
        self.assertEqual(room["pending_interventions"], {})
        self.assertIn("RuntimeState persistence failed", patch_result["message"])
        self.assertNotIn("provider", patch_result["message"].lower())
        events = runtime.operation_log.events()
        self.assertIn("plan_patch_state_persist_failed", events)
        self.assertNotIn("plan_patch_recorded", events)
        runtime_events = runtime.user_visible_events("room-intervention-message-fail")
        self.assertFalse(any(event.get("event_type") == "intervention_recorded" for event in runtime_events))

