    def test_handle_message_semantic_intervention_aliases_map_to_plan_patches(self) -> None:
        runtime = AgentRuntime()
        created = runtime.handle_message(
            room_id="room-semantic-intervention-aliases",
            text="强盗藏宝室，要有藏宝箱、金币堆和火把",
            sender_id="host-1",
            sender_name="房主",
            action="plan",
            external_plan_id="seed-semantic-intervention-aliases",
        )

        add = runtime.handle_message(
            room_id="room-semantic-intervention-aliases",
            text="再添加一个天使雕像",
            sender_id="host-1",
            sender_name="房主",
            action="add_object",
            external_plan_id="seed-semantic-intervention-aliases",
        )
        modify = runtime.handle_message(
            room_id="room-semantic-intervention-aliases",
            text="藏宝箱要更大一点",
            sender_id="host-1",
            sender_name="房主",
            action="modify_object",
            external_plan_id="seed-semantic-intervention-aliases",
        )
        delete = runtime.handle_message(
            room_id="room-semantic-intervention-aliases",
            text="删除金币",
            sender_id="host-1",
            sender_name="房主",
            action="delete_object",
            external_plan_id="seed-semantic-intervention-aliases",
        )
        post_add = runtime.handle_message(
            room_id="room-semantic-intervention-aliases",
            text="后面再添加一只小狗",
            sender_id="host-1",
            sender_name="房主",
            action="post_generation_add_object",
            external_plan_id="seed-semantic-intervention-aliases",
        )
        executed = runtime.handle_message(
            room_id="room-semantic-intervention-aliases",
            text="确认生成",
            sender_id="host-1",
            sender_name="房主",
            action="confirm_generation",
            external_plan_id="seed-semantic-intervention-aliases",
            max_items_per_batch=3,
        )

        self.assertEqual(add["plan"]["plan_id"], created["plan"]["plan_id"])
        self.assertEqual(modify["plan"]["plan_id"], created["plan"]["plan_id"])
        self.assertEqual(delete["plan"]["plan_id"], created["plan"]["plan_id"])
        self.assertEqual(post_add["plan"]["plan_id"], created["plan"]["plan_id"])
        self.assertEqual(add["patch"]["patch_type"], "intervention_add")
        self.assertEqual(modify["patch"]["patch_type"], "intervention_modify")
        self.assertEqual(delete["patch"]["patch_type"], "intervention_delete")
        self.assertEqual(post_add["patch"]["patch_type"], "post_generation_add")
        self.assertEqual(delete["patch"]["risk_level"], "medium")
        self.assertEqual(modify["patch"]["risk_level"], "low")
        self.assertIn("天使雕像", executed["plan"]["concrete_object_items"])
        self.assertIn("小狗", executed["plan"]["concrete_object_items"])
        self.assertNotIn("删除金币", executed["batches"][0]["requested_items"])

        state = runtime.query_state("room-semantic-intervention-aliases")["room"]
        self.assertIn(add["patch"]["patch_id"], state["accepted_interventions"])
        self.assertIn(post_add["patch"]["patch_id"], state["accepted_interventions"])
        self.assertEqual(
            state["deferred_interventions"][modify["patch"]["patch_id"]]["deferred_reason"],
            "modify_request_requires_adjustment_proposal",
        )
        self.assertEqual(
            state["deferred_interventions"][delete["patch"]["patch_id"]]["deferred_reason"],
            "delete_request_requires_explicit_adjustment_confirmation",
        )

