    def test_record_final_adjustment_confirmation_is_runtime_fact(self) -> None:
        runtime = AgentRuntime()
        created = runtime.handle_message(
            room_id="room-final-confirm",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            sender_id="host-1",
            sender_name="房主",
            action="plan",
            external_plan_id="seed-final-confirm",
        )
        runtime.scene_plans.pop(created["plan"]["plan_id"], None)

        recorded = runtime.record_final_adjustment_confirmation(
            room_id="room-final-confirm",
            external_plan_id="seed-final-confirm",
            proposal={
                "proposal_id": "final-proposal-1",
                "room_id": "room-final-confirm",
                "plan_id": "seed-final-confirm",
                "target_hint": "钘忓疂绠?",
                "conflict_items": ["鏀惧ぇ钘忓疂绠?", "淇濇寔閫氶亾"],
                "status": "confirmed",
            },
            confirmed_by="房主",
        )

        self.assertTrue(recorded["recorded"])
        self.assertEqual(recorded["confirmation"]["plan_id"], created["plan"]["plan_id"])
        state = runtime.query_state("room-final-confirm")["room"]
        confirmations = state["final_adjustment_confirmations"]
        self.assertEqual(len(confirmations), 1)
        self.assertEqual(confirmations[0]["proposal_id"], "final-proposal-1")
        self.assertEqual(confirmations[0]["decision"], "confirmed")
        confirm_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.final_adjustment.confirm"}
        ]
        self.assertEqual(len(confirm_graphs), 1)
        self.assertEqual(confirm_graphs[0]["status"], "completed")
        confirm_nodes = dict(confirm_graphs[0]["nodes"])
        self.assertTrue(confirm_nodes)
        self.assertEqual(next(iter(confirm_nodes.values()))["status"], "succeeded")
        self.assertIn("final_adjustment_confirmation_recorded", runtime.operation_log.events())
        events = runtime.user_visible_events("room-final-confirm", plan_id=created["plan"]["plan_id"])
        self.assertTrue([event for event in events if event["event_type"] == "final_adjustment_confirmation"])
        status = runtime.status_summary("room-final-confirm", external_plan_id="seed-final-confirm")
        self.assertEqual(status["final_adjustment_confirmation_summary"]["confirmation_count"], 1)
        self.assertEqual(
            status["final_adjustment_confirmation_summary"]["latest_confirmations"][0]["proposal_id"],
            "final-proposal-1",
        )
        report = runtime.generate_report("room-final-confirm", plan_id=created["plan"]["plan_id"])
        self.assertEqual(report["final_adjustment_confirmation_summary"]["confirmation_count"], 1)
        self.assertEqual(
            report["final_adjustment_confirmation_summary"]["latest_confirmations"][0]["decision"],
            "confirmed",
        )
        replay = runtime.operation_replay(room_id="room-final-confirm", plan_id=created["plan"]["plan_id"], limit=80)
        confirmation_entries = [
            entry for entry in replay["entries"]
            if entry["event"] == "final_adjustment_confirmation_recorded"
        ]
        self.assertTrue(confirmation_entries)
        replay_payload = confirmation_entries[-1]["payload"]
        self.assertEqual(replay_payload["proposal_id"], "final-proposal-1")
        self.assertEqual(replay_payload["decision"], "confirmed")
        self.assertEqual(replay_payload["confirmed_by"], "房主")
        self.assertEqual(replay_payload["target_hint"], "钘忓疂绠?")
        self.assertEqual(replay_payload["conflict_item_count"], 2)
        self.assertNotIn("conflict_items", replay_payload)

