    def test_final_adjustment_confirmation_failure_returns_persisted_state_only(self) -> None:
        runtime = AgentRuntime()
        created = runtime.handle_message(
            room_id="room-final-confirm-fail",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            sender_id="host-1",
            sender_name="房主",
            action="plan",
            external_plan_id="seed-final-confirm-fail",
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_confirmation_patch(patch: StatePatch) -> tuple[bool, str]:
            if "final_adjustment_confirmations" in patch.changes:
                return False, "simulated final adjustment confirmation persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_confirmation_patch  # type: ignore[method-assign]

        recorded = runtime.record_final_adjustment_confirmation(
            room_id="room-final-confirm-fail",
            external_plan_id="seed-final-confirm-fail",
            proposal={
                "proposal_id": "final-proposal-fail-1",
                "room_id": "room-final-confirm-fail",
                "plan_id": "seed-final-confirm-fail",
                "target_hint": "钘忓疂绠?",
                "conflict_items": ["鏀惧ぇ钘忓疂绠?", "淇濇寔閫氶亾"],
                "status": "confirmed",
            },
            confirmed_by="房主",
        )

        self.assertFalse(recorded["recorded"])
        self.assertEqual(recorded["confirmation"], {})
        room = runtime.query_state("room-final-confirm-fail")["room"]
        self.assertEqual(room["final_adjustment_confirmations"], [])
        events = runtime.operation_log.events()
        self.assertIn("final_adjustment_confirmation_record_failed", events)
        self.assertNotIn("final_adjustment_confirmation_recorded", events)
        visible_events = runtime.user_visible_events("room-final-confirm-fail", plan_id=created["plan"]["plan_id"])
        self.assertFalse([event for event in visible_events if event["event_type"] == "final_adjustment_confirmation"])

    def test_final_adjustment_confirmation_validator_rejects_internal_fields(self) -> None:
        valid_event = {
            "proposal_id": "final-proposal-safe",
            "room_id": "room-final-validator",
            "plan_id": "plan-final-validator",
            "external_plan_id": "seed-final-validator",
            "decision": "confirmed",
            "confirmed_by": "房主",
            "target_hint": "钘忓疂绠?",
            "conflict_items": ["保持通道"],
            "timestamp": 1.0,
        }
        FinalAdjustmentConfirmationValidator.validate(valid_event)

        unsafe_event = dict(valid_event)
        unsafe_event["message_id"] = "native-message-id"
        with self.assertRaisesRegex(ValueError, "final adjustment confirmation cannot expose field: message_id"):
            FinalAdjustmentConfirmationValidator.validate(unsafe_event)

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-final-invalid",
                changes={"final_adjustment_confirmations": [unsafe_event]},
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("final adjustment confirmation cannot expose field: message_id", reason)

    def test_final_adjustment_confirmation_validator_rejects_unsafe_text_values(self) -> None:
        valid_event = {
            "proposal_id": "final-proposal-safe-text",
            "room_id": "room-final-safe-text",
            "plan_id": "plan-final-safe-text",
            "external_plan_id": "seed-final-safe-text",
            "decision": "confirmed",
            "confirmed_by": "房主",
            "target_hint": "钘忓疂绠?",
            "conflict_items": ["保持入口通道"],
            "timestamp": 1.0,
        }
        FinalAdjustmentConfirmationValidator.validate(valid_event)

        unsafe_target = dict(valid_event)
        unsafe_target["target_hint"] = "provider raw C:\\\\secret\\\\target prompt=hidden"
        with self.assertRaisesRegex(ValueError, "final adjustment confirmation target_hint contains unsafe text"):
            FinalAdjustmentConfirmationValidator.validate(unsafe_target)

        unsafe_conflict = dict(valid_event)
        unsafe_conflict["conflict_items"] = ["https://internal.example/conflict"]
        with self.assertRaisesRegex(ValueError, "final adjustment confirmation conflict_items contains unsafe text"):
            FinalAdjustmentConfirmationValidator.validate(unsafe_conflict)

        runtime = AgentRuntime()
        unsafe_room = dict(valid_event)
        unsafe_room["room_id"] = "C:\\\\secret\\\\room"
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-final-unsafe-text",
                changes={"final_adjustment_confirmations": [unsafe_room]},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("final adjustment confirmation room_id contains unsafe text", reason)

