    def test_intervention_buckets_use_plan_patch_validator(self) -> None:
        patch = PlanPatch(
            patch_id="patch-add-statue",
            room_id="room-intervention-bucket",
            plan_id="plan-intervention-bucket",
            text="鍐嶅姞涓€涓ぉ浣块洉鍍?",
            patch_type="intervention_add",
            items=["天使雕像"],
            source_user="房主",
            target_agent="商人",
        )
        PlanPatchValidator.validate(patch)

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id=patch.room_id,
                changes={"pending_interventions": {patch.patch_id: patch.as_dict()}},
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)

        unsafe_patch = {
            patch.patch_id: {
                **patch.as_dict(),
                "prompt": "hidden intervention prompt",
            }
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id=patch.room_id,
                changes={"accepted_interventions": unsafe_patch},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("plan patch cannot expose field: prompt", reason)

        empty_add_patch = {
            patch.patch_id: {
                **patch.as_dict(),
                "items": [],
            }
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id=patch.room_id,
                changes={"pending_interventions": empty_add_patch},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("plan patch items cannot be empty", reason)

        deferred_patch = {
            patch.patch_id: {
                **patch.as_dict(),
                "status": "deferred",
                "deferred_reason": "",
            }
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id=patch.room_id,
                changes={"deferred_interventions": deferred_patch},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("deferred plan patch requires deferred_reason", reason)

