    def test_status_and_report_include_pending_intervention_summary_before_execution(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-pending-intervention-summary",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        patch = runtime.record_intervention(
            room_id="room-pending-intervention-summary",
            plan_id=plan.plan_id,
            text="鍐嶆坊鍔犱竴涓ぉ浣块洉鍍?",
            source_user="房主",
            target_agent="山贼",
        )
        modify_patch = runtime.record_intervention(
            room_id="room-pending-intervention-summary",
            plan_id=plan.plan_id,
            text="鎶婂叆鍙ｅ竷灞€璋冩暣瀹戒竴鐐?",
            patch_type="intervention_modify",
            source_user="房主",
            target_agent="山贼",
        )

        summary = runtime.status_summary("room-pending-intervention-summary", plan_id=plan.plan_id)
        report = runtime.generate_report("room-pending-intervention-summary", plan_id=plan.plan_id)
        intervention_events = [
            event
            for event in runtime.user_visible_events("room-pending-intervention-summary", plan_id=plan.plan_id)
            if event["event_type"] == "intervention_recorded"
        ]

        self.assertEqual(summary["intervention_summary"]["pending_count"], 2)
        self.assertEqual(summary["intervention_summary"]["accepted_count"], 0)
        self.assertEqual(summary["intervention_summary"]["deferred_count"], 0)
        self.assertEqual(summary["intervention_summary"]["absorbable_pending_count"], 1)
        self.assertEqual(summary["intervention_summary"]["non_absorbable_pending_count"], 1)
        digest = summary["intervention_summary"]["intervention_digest"]
        self.assertEqual(digest["pending_count"], 2)
        self.assertEqual(digest["patch_type_counts"]["intervention_add"], 1)
        self.assertEqual(digest["patch_type_counts"]["intervention_modify"], 1)
        self.assertIn("天使雕像", digest["next_batch_candidate_items"])
        self.assertEqual(digest["absorbable_pending_count"], 1)
        self.assertEqual(digest["non_absorbable_pending_count"], 1)
        self.assertEqual(digest["needs_confirmation"][0]["patch_type"], "intervention_modify")
        self.assertNotIn("patch_id", summary["intervention_summary"]["latest_absorbable_pending"][0])
        self.assertIn("天使雕像", summary["intervention_summary"]["latest_absorbable_pending"][0]["items"])
        self.assertEqual(
            summary["intervention_summary"]["latest_non_absorbable_pending"][0]["patch_type"],
            "intervention_modify",
        )
        self.assertNotIn("patch_id", report["intervention_summary"]["pending"][0])
        self.assertEqual(report["intervention_summary"]["absorbable_pending_count"], 1)
        self.assertEqual(report["intervention_summary"]["non_absorbable_pending_count"], 1)
        self.assertEqual(report["intervention_summary"]["intervention_digest"], digest)
        self.assertEqual(
            report["intervention_summary"]["latest_non_absorbable_pending"][0]["patch_type"],
            "intervention_modify",
        )
        state = runtime.query_state("room-pending-intervention-summary")["room"]
        self.assertEqual(state["pending_interventions"][patch.patch_id]["patch_id"], patch.patch_id)
        self.assertEqual(state["pending_interventions"][modify_patch.patch_id]["patch_id"], modify_patch.patch_id)
        self.assertEqual(report["intervention_summary"]["accepted"], [])
        self.assertEqual(report["intervention_summary"]["deferred"], [])
        self.assertTrue(intervention_events)
        angel_events = [
            event
            for event in intervention_events
            if "天使雕像" in str(event.get("message") or "")
        ]
        self.assertTrue(angel_events)
        self.assertEqual(angel_events[-1]["payload"]["status"], "pending")
        self.assertGreaterEqual(angel_events[-1]["payload"]["item_count"], 1)
        self.assertNotIn("patch_id", angel_events[-1])
        self.assertNotIn("tool_name", str(angel_events[-1]))

