    def test_handle_message_records_delete_intervention_as_medium_risk_deferred_patch(self) -> None:
        runtime = AgentRuntime()
        created = runtime.handle_message(
            room_id="room-delete-intervention",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            sender_id="host-1",
            sender_name="房主",
            action="plan",
            external_plan_id="seed-delete-intervention",
        )

        patch_result = runtime.handle_message(
            room_id="room-delete-intervention",
            text="删除金币",
            sender_id="host-1",
            sender_name="房主",
            action="intervention_delete",
            external_plan_id="seed-delete-intervention",
        )
        executed = runtime.handle_message(
            room_id="room-delete-intervention",
            text="纭鐢熸垚",
            sender_id="host-1",
            sender_name="房主",
            action="confirm_and_execute",
            external_plan_id="seed-delete-intervention",
        )

        patch = patch_result["patch"]
        state = runtime.query_state("room-delete-intervention")["room"]
        self.assertEqual(patch_result["plan"]["plan_id"], created["plan"]["plan_id"])
        self.assertEqual(patch["patch_type"], "intervention_delete")
        self.assertEqual(patch["risk_level"], "medium")
        self.assertTrue(any("金币" in item for item in patch["items"]))
        self.assertEqual(state["pending_interventions"][patch["patch_id"]]["status"], "deferred")
        self.assertIn(patch["patch_id"], state["deferred_interventions"])
        self.assertEqual(
            state["deferred_interventions"][patch["patch_id"]]["deferred_reason"],
            "delete_request_requires_explicit_adjustment_confirmation",
        )
        self.assertNotIn("删除金币", executed["batches"][0]["requested_items"])
        summary = runtime.status_summary("room-delete-intervention", external_plan_id="seed-delete-intervention")
        report = runtime.generate_report("room-delete-intervention", plan_id=created["plan"]["plan_id"])
        self.assertEqual(
            summary["intervention_summary"]["latest_deferred"][0]["deferred_reason"],
            "delete_request_requires_explicit_adjustment_confirmation",
        )
        self.assertEqual(
            report["intervention_summary"]["deferred"][0]["deferred_reason"],
            "delete_request_requires_explicit_adjustment_confirmation",
        )
        self.assertIn("plan_patch_deferred", runtime.operation_log.events())

    def test_runtime_can_plan_multiple_batches_as_state_facts(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-batches",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯併€佺伀鎶娿€佹湪妗屻€佹湪妞呫€佹湪绠便€侀厭妗?",
            owner_agent="山贼",
        )
        patch = runtime.record_intervention(
            room_id="room-batches",
            text="鍐嶆坊鍔犱竴涓ぉ浣块洉鍍?",
            plan_id=plan.plan_id,
            source_user="房主",
        )
        runtime.scene_plans.pop(plan.plan_id, None)
        runtime.plan_patches.clear()

        batches = runtime.plan_batches(plan.plan_id, max_items_per_batch=3)

        self.assertGreaterEqual(len(batches), 2)
        self.assertEqual([batch.batch_index for batch in batches], list(range(1, len(batches) + 1)))
        self.assertTrue(all(batch.total_batches == len(batches) for batch in batches))
        flattened = [item for batch in batches for item in batch.requested_items]
        self.assertIn("天使雕像", flattened)
        self.assertIn(patch.patch_id, batches[0].absorbed_intervention_ids)
        state = runtime.query_state("room-batches")["room"]
        priority_fact = state["custom_batch_facts"][f"{plan.plan_id}:item_priorities"]
        self.assertEqual(flattened, priority_fact["ordered_items"])
        self.assertTrue(priority_fact["priorities"])
        create_fact = state["custom_batch_facts"][f"{plan.plan_id}:created_batches"]
        self.assertEqual(create_fact["batch_count"], len(batches))
        self.assertEqual(
            [batch["requested_items"] for batch in create_fact["batches"]],
            [batch.requested_items for batch in batches],
        )
        self.assertEqual(len(state["batch_plans"]), len(batches))
        summary = runtime.status_summary("room-batches", plan_id=plan.plan_id)
        report = runtime.generate_report("room-batches", plan_id=plan.plan_id)
        self.assertEqual(summary["batch_tooling_summary"]["created_batch_fact_count"], 1)
        self.assertEqual(summary["batch_tooling_summary"]["created_batch_count"], len(batches))
        self.assertEqual(summary["batch_tooling_summary"]["prioritized_item_count"], len(flattened))
        self.assertEqual(report["batch_tooling_summary"], summary["batch_tooling_summary"])
        self.assertNotIn(patch.patch_id, str(summary["batch_tooling_summary"]))
        self.assertNotIn(patch.patch_id, str(report["batch_tooling_summary"]))
        priority_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"batch.prioritize_items"}
        ]
        self.assertEqual(len(priority_graphs), 1)
        self.assertEqual(priority_graphs[0]["status"], "completed")
        create_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"batch.create"}
        ]
        self.assertEqual(len(create_graphs), 1)
        self.assertEqual(create_graphs[0]["status"], "completed")
        batch_plan_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.batch.plan_record"}
        ]
        self.assertEqual(len(batch_plan_graphs), 1)
        self.assertEqual(batch_plan_graphs[0]["status"], "completed")
        batch_plan_nodes = dict(batch_plan_graphs[0]["nodes"])
        self.assertTrue(batch_plan_nodes)
        self.assertEqual(next(iter(batch_plan_nodes.values()))["status"], "succeeded")
        batch_plan_messages = [
            event for event in state["runtime_events"]
            if event.get("event_type") == "tool_result_message"
            and dict(event.get("payload") or {}).get("batch_count") == len(batches)
        ]
        self.assertTrue(batch_plan_messages)
        self.assertEqual(batch_plan_messages[-1]["payload"]["status"], "succeeded")
        self.assertEqual(batch_plan_messages[-1]["payload"]["batch_count"], len(batches))
        serialized_batch_plan_messages = str(batch_plan_messages)
        self.assertNotIn("requested_items", serialized_batch_plan_messages)
        self.assertNotIn("provider raw", serialized_batch_plan_messages)
        self.assertNotIn("prompt=hidden", serialized_batch_plan_messages)
        self.assertNotIn("model_path", serialized_batch_plan_messages)
        runtime.batch_plans.clear()
        restored_batches = runtime._planned_batches_for_plan(plan.plan_id)
        self.assertEqual([batch.batch_id for batch in restored_batches], [batch.batch_id for batch in batches])
        self.assertEqual([batch.requested_items for batch in restored_batches], [batch.requested_items for batch in batches])
        self.assertEqual(state["pending_interventions"][patch.patch_id]["status"], "accepted")
        self.assertIn(patch.patch_id, state["accepted_interventions"])
        self.assertIn("batch_plans_planned", runtime.operation_log.events())
        events = runtime.operation_log.events()
        self.assertLess(events.index("plan_patch_state_persisted"), events.index("plan_patch_absorbed"))
        self.assertLess(events.index("batch_plan_state_persisted"), events.index("batch_plans_planned"))

