    def test_report_is_logged_before_it_is_written_to_runtime_state(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-report-log-order",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )

        report = runtime.generate_report("room-report-log-order")
        state_report = runtime.state.snapshot("room-report-log-order")["room"]["reports"][-1]
        report_events = runtime.operation_log.query(event="user_report_generated", room_id="room-report-log-order")

        self.assertTrue(report_events)
        self.assertEqual(report_events[-1].plan_id, plan.plan_id)
        self.assertEqual(report["plan_id"], plan.plan_id)
        self.assertEqual(report["operation_log_event"], "user_report_generated")
        self.assertEqual(state_report["operation_log_event"], "user_report_generated")
        self.assertEqual(state_report["operation_log_index"], report["operation_log_index"])
        events = runtime.operation_log.events()
        self.assertEqual(events[report["operation_log_index"] - 1], "user_report_generated")
        self.assertLessEqual(report["operation_log_index"], len(events))
        self.assertLess(events.index("user_report_generated"), events.index("user_report_state_persisted"))
        state_events = runtime.state.snapshot("room-report-log-order")["room"]["runtime_events"]
        report_persist_messages = [
            event for event in state_events
            if event.get("event_type") == "tool_result_message"
            and dict(event.get("payload") or {}).get("status") == "succeeded"
        ]
        self.assertTrue(report_persist_messages)
        self.assertEqual(report_persist_messages[-1]["payload"], {"status": "succeeded"})
        self.assertNotIn("operation_log_index", str(report_persist_messages))
        self.assertNotIn("operation_log_event", str(report_persist_messages))
        self.assertNotIn("provider raw", str(report_persist_messages))
        self.assertNotIn("prompt=hidden", str(report_persist_messages))
        report_ready_events = [
            entry
            for entry in runtime.operation_log.query(
                event="runtime_event_emitted",
                room_id="room-report-log-order",
            )
            if str(entry.payload.get("event_type") or "") == "report_pending"
        ]
        self.assertTrue(report_ready_events)
        self.assertLess(
            events.index("user_report_state_persisted"),
            runtime.operation_log.entries().index(report_ready_events[-1]),
        )
        report_persist_graphs = [
            graph
            for graph in runtime.query_state("room-report-log-order")["room"]["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.user_report.persist"}
        ]
        self.assertEqual(len(report_persist_graphs), 1)
        self.assertEqual(report_persist_graphs[0]["status"], "completed")
        self.assertNotIn("_runtime_report_persist_token", str(report_persist_graphs[0]))
        self.assertNotIn("report-persist-token", str(report_persist_graphs[0]))
        ReportRecordValidator.validate(state_report)

    def test_user_report_persist_tool_rejects_external_report_payloads(self) -> None:
        runtime = AgentRuntime()
        graph = ToolCallGraph(graph_id="graph-external-report-persist", plan_id="plan-external-report")
        graph.add(
            ToolCall(
                tool_call_id="tool-external-report-persist",
                tool_name="runtime.user_report.persist",
                args={
                    "room_id": "room-external-report",
                    "plan_id": "plan-external-report",
                    "report": {
                        "room_id": "room-external-report",
                        "plan_id": "plan-external-report",
                        "operation_log_event": "forged",
                        "operation_log_index": 999,
                    },
                },
                risk_level=RiskLevel.LOW,
                requires_write=True,
                confirmed=True,
            )
        )

        executed = ToolCallGraphExecutor(
            registry=runtime.registry,
            guard=runtime.guard,
            state=runtime.state,
            operation_log=runtime.operation_log,
        ).execute(graph, room_id="room-external-report")

        node = executed.nodes["tool-external-report-persist"]
        self.assertEqual(executed.status, "failed")
        self.assertEqual(node.status, ToolCallStatus.FAILED)
        self.assertIn("unauthorized", node.error)
        self.assertEqual(runtime.state.snapshot("room-external-report")["room"]["reports"], [])

    def test_generate_report_sanitizes_runtime_state_text_before_persisting(self) -> None:
        runtime = AgentRuntime()
