    def test_operation_replay_plan_scope_rejects_other_plan_with_same_batch_id(self) -> None:
        runtime = AgentRuntime()
        room_id = "room-replay-plan-scope"
        shared_batch_id = "batch-shared-id"
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id=room_id,
                changes={
                    "batch_plans": {
                        "batch-a": {
                            "batch_id": shared_batch_id,
                            "plan_id": "plan-a",
                            "room_id": room_id,
                            "status": "completed",
                        },
                        "batch-b": {
                            "batch_id": shared_batch_id,
                            "plan_id": "plan-b",
                            "room_id": room_id,
                            "status": "completed",
                        },
                    }
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)
        runtime.operation_log.append(
            "tool_call_succeeded",
            room_id=room_id,
            plan_id="plan-a",
            batch_id=shared_batch_id,
            message="plan a event",
        )
        runtime.operation_log.append(
            "tool_call_succeeded",
            room_id=room_id,
            plan_id="plan-b",
            batch_id=shared_batch_id,
            message="plan b event",
        )
        runtime.operation_log.append(
            "tool_call_succeeded",
            room_id=room_id,
            batch_id=shared_batch_id,
            message="legacy batch-only event",
        )

        replay = runtime.operation_replay(room_id=room_id, plan_id="plan-a")
        messages = [entry["message"] for entry in replay["entries"]]

        self.assertIn("plan a event", messages)
        self.assertIn("legacy batch-only event", messages)
        self.assertNotIn("plan b event", messages)

    def test_user_visible_events_plan_scope_rejects_other_plan_with_same_batch_id(self) -> None:
        runtime = AgentRuntime()
        room_id = "room-visible-event-plan-scope"
        shared_batch_id = "batch-shared-id"
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id=room_id,
                changes={
                    "batch_plans": {
                        "batch-a": {
                            "batch_id": shared_batch_id,
                            "plan_id": "plan-a",
                            "room_id": room_id,
                            "status": "completed",
                        },
                        "batch-b": {
                            "batch_id": shared_batch_id,
                            "plan_id": "plan-b",
                            "room_id": room_id,
                            "status": "completed",
                        },
                    }
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)
        runtime.emit_runtime_event(
            room_id=room_id,
            plan_id="plan-a",
            batch_id=shared_batch_id,
            event_type="batch_progress",
            title="Plan A",
            message="plan a visible event",
        )
        runtime.emit_runtime_event(
            room_id=room_id,
            plan_id="plan-b",
            batch_id=shared_batch_id,
            event_type="batch_progress",
            title="Plan B",
            message="plan b visible event",
        )
        runtime.emit_runtime_event(
            room_id=room_id,
            batch_id=shared_batch_id,
            event_type="batch_progress",
            title="Legacy",
            message="legacy batch-only visible event",
        )

        events = runtime.user_visible_events(room_id, plan_id="plan-a")
        messages = [event["message"] for event in events]

        self.assertIn("plan a visible event", messages)
        self.assertIn("legacy batch-only visible event", messages)
        self.assertNotIn("plan b visible event", messages)

    def test_engine_write_replay_summary_sanitizes_raw_engine_results(self) -> None:
        runtime = AgentRuntime()
        runtime.operation_log.append(
            "tool_call_failed",
            room_id="room-engine-write-sanitize",
            plan_id="plan-engine-write-sanitize",
            payload={
                "import_results": [
                    {
                        "actor_id": "actor-1",
                        "actor_name": "provider=https://secret.invalid",
                        "status": "failed",
                        "reason": "model_path=E:/private/model.glb prompt=hidden",
                        "model_path": "E:/private/model.glb",
                    }
                ],
                "transform_results": [
                    {
                        "actor_id": "actor-2",
                        "actor_name": "钘忓疂绠?",
                        "status": "failed",
                        "reason": "provider raw https://secret.invalid E:/private/transform.json",
                    }
                ],
            },
        )

        replay = runtime.operation_replay(
            room_id="room-engine-write-sanitize",
            plan_id="plan-engine-write-sanitize",
        )
        summary = replay["engine_write_summary"]
        serialized = str(summary)

        self.assertEqual(summary["import_result_count"], 1)
        self.assertEqual(summary["transform_result_count"], 1)
        self.assertEqual(summary["latest_import_results"][0]["actor_id"], "actor-1")
        self.assertNotIn("actor_name", summary["latest_import_results"][0])
        self.assertEqual(summary["latest_import_results"][0]["reason"], "engine write failed")
        self.assertEqual(summary["latest_transform_results"][0]["reason"], "engine write failed")
        self.assertNotIn("https://secret.invalid", serialized)
        self.assertNotIn("prompt=hidden", serialized)
        self.assertNotIn("E:/private", serialized)
        self.assertNotIn("model_path", serialized)

    def test_generate_report_failure_does_not_emit_report_ready_or_write_state_report(self) -> None:
        runtime = AgentRuntime()
        runtime.propose_scene_plan(
            room_id="room-report-persist-failure",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_report_patch(patch: StatePatch) -> tuple[bool, str]:
            if "reports" in patch.changes:
                return False, "state version conflict"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_report_patch  # type: ignore[method-assign]

        with self.assertRaisesRegex(RuntimeError, "failed to persist user report"):
            runtime.generate_report("room-report-persist-failure")

        events = runtime.operation_log.events()
        self.assertIn("runtime_report_operation_replay_summary_recorded", events)
        self.assertIn("user_report_generated", events)
        self.assertIn("user_report_state_persist_failed", events)
        failed_payload = runtime.operation_log.query(
            event="user_report_state_persist_failed",
            room_id="room-report-persist-failure",
        )[-1].payload
        self.assertFalse(failed_payload["applied"])
        self.assertEqual(failed_payload["failure_code"], "user_report_state_persist_failed")
        self.assertIn("RuntimeState persistence failed", failed_payload["reason"])
        self.assertIn("operation_log_event", failed_payload)
        self.assertIn("operation_log_index", failed_payload)
        replay = runtime.operation_log.snapshot(
            room_id="room-report-persist-failure",
            event="user_report_state_persist_failed",
        )
        replay_payload = replay["entries"][-1]["payload"]
        self.assertEqual(replay_payload["operation_log_event"], failed_payload["operation_log_event"])
        self.assertEqual(replay_payload["operation_log_index"], failed_payload["operation_log_index"])
        self.assertEqual(replay_payload["failure_code"], "user_report_state_persist_failed")
        report_ready_events = [
            entry
            for entry in runtime.operation_log.query(
                event="runtime_event_emitted",
                room_id="room-report-persist-failure",
            )
            if str(entry.payload.get("event_type") or "") == "report_ready"
        ]
        self.assertEqual(report_ready_events, [])
        self.assertEqual(runtime.state.snapshot("room-report-persist-failure")["room"]["reports"], [])

