    def test_state_patch_rejects_unsafe_report_records(self) -> None:
        runtime = AgentRuntime()

        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-report-invalid",
                changes={
                    "reports": [
                        {
                            "room_id": "room-report-invalid",
                            "plan_id": "plan-1",
                            "state_version": 1,
                            "plan_summary": {"title": "钘忓疂瀹?"},
                            "provider_summary": {},
                            "operation_replay_summary": {
                                "latest_entries": [
                                    {
                                        "event": "tool_call",
                                        "tool_call_id": "hidden-tool",
                                    }
                                ]
                            },
                        }
                    ]
                },
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("report record cannot expose field: tool_call_id", reason)

        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-report-invalid",
                changes={
                    "reports": [
                        {
                            "room_id": "room-report-invalid",
                            "plan_id": "plan-1",
                            "state_version": 1,
                            "plan_summary": {"title": "钘忓疂瀹?"},
                            "provider_summary": {},
                            "tool_graph_summary": {
                                "graphs": [
                                    {
                                        "graph_id": "graph-secret",
                                        "status": "completed",
                                    }
                                ]
                            },
                        }
                    ]
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("report record cannot expose field: graph_id", reason)

        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-report-invalid",
                changes={
                    "reports": [
                        {
                            "room_id": "room-report-invalid",
                            "plan_id": "plan-1",
                            "state_version": 1,
                            "plan_summary": {"title": "钘忓疂瀹?"},
                            "provider_summary": {},
                            "latest_runtime_events": [],
                            "prompt": "hidden prompt",
                        }
                    ]
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("unsupported field: prompt", reason)

        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-report-invalid",
                changes={
                    "reports": [
                        {
                            "room_id": "room-report-invalid",
                            "plan_id": "plan-1",
                            "state_version": 1,
                            "plan_summary": {
                                "title": "provider raw C:\\\\secret\\\\report prompt=hidden",
                            },
                            "provider_summary": {},
                        }
                    ]
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("report record report.plan_summary.title contains unsafe text", reason)

        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-report-invalid",
                changes={
                    "reports": [
                        {
                            "room_id": "room-report-invalid",
                            "plan_id": "plan-1",
                            "state_version": 1,
                            "plan_summary": {
                                "title": "钘忓疂瀹?",
                            },
                            "provider_summary": {},
                            "operation_replay_summary": {
                                "latest_entries": [
                                    {
                                        "event": "runtime_status",
                                        "message": "https://internal.example/report",
                                    }
                                ]
                            },
                        }
                    ]
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("report record report.operation_replay_summary.latest_entries[0].message contains unsafe text", reason)

