    def test_enqueue_scene_plan_only_queues_single_batch_until_worker_drains(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-single-enqueue",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")
        runtime.scene_plans.pop(plan.plan_id, None)

        queued = runtime.enqueue_scene_plan(plan.plan_id)

        self.assertEqual(queued["plan"]["status"], "executing")
        self.assertEqual(queued["batch"]["status"], "planned")
        self.assertEqual(queued["graph"]["status"], "queued")
        state = runtime.query_state("room-single-enqueue")["room"]
        self.assertEqual(state["actors"], {})
        self.assertEqual(
            runtime.status_summary("room-single-enqueue", plan_id=plan.plan_id)["tool_graph_summary"]["queue_status_counts"],
            {"queued": 1},
        )
        enqueue_state_graphs = [
            graph
            for graph in state["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.scene_plan.enqueue"}
        ]
        self.assertTrue(enqueue_state_graphs)
        self.assertEqual(enqueue_state_graphs[-1]["status"], "completed")
        log_entries = runtime.operation_log.entries()
        events = [entry.event for entry in log_entries]
        status_indices = [
            index
            for index, entry in enumerate(log_entries)
            if entry.event == "scene_plan_status_persisted"
            and entry.plan_id == plan.plan_id
            and entry.payload.get("reason") == "enqueue_scene_plan"
        ]
        self.assertTrue(status_indices)
        self.assertEqual(state["scene_plans"][plan.plan_id]["status"], ScenePlanStatus.EXECUTING.value)
        self.assertLess(status_indices[-1], events.index("batch_plan_created"))
        graph_id = queued["graph"]["graph_id"]
        graph_events = [
            entry.event
            for entry in runtime.operation_log.entries()
            if entry.payload.get("graph_id") == graph_id
        ]
        self.assertIn("tool_graph_queue_state_persisted", graph_events)
        self.assertLess(graph_events.index("tool_graph_queue_state_persisted"), graph_events.index("tool_graph_queued"))
        self.assertIn("tool_graph_queued", graph_events)
        self.assertNotIn("tool_graph_started", graph_events)

        drained = runtime.drain_tool_graph_queue("room-single-enqueue", plan_id=plan.plan_id, max_graphs=1)

        self.assertEqual(drained["drained_count"], 1)
        self.assertEqual(drained["graphs"][0]["status"], "completed")
        self.assertGreaterEqual(len(runtime.query_state("room-single-enqueue")["room"]["actors"]), 1)

