    def test_runtime_resource_providers_can_override_mock_resource_adapters(self) -> None:
        def image_provider(payload: dict) -> dict:
            return {
                name: {"name": name, "status": "provider-image", "batch_id": payload["batch_id"]}
                for name in payload["model_items"]
            }

        def model_provider(payload: dict) -> dict:
            return {
                name: {"name": name, "status": "provider-model", "batch_id": payload["batch_id"]}
                for name in payload["model_items"]
            }

        def import_provider(payload: dict) -> dict:
            return {
                f"provider-actor-{index}": {
                    "actor_id": f"provider-actor-{index}",
                    "name": name,
                    "batch_id": payload["batch_id"],
                    "source": "provider",
                }
                for index, name in enumerate(payload["model_items"], start=1)
            }

        runtime = AgentRuntime(
            image_resource_provider=image_provider,
            model_resource_provider=model_provider,
            actor_import_provider=import_provider,
        )
        plan = runtime.propose_scene_plan(
            room_id="room-provider",
            text="鍋氫竴涓彲鐖卞崸瀹わ紝鏈夊簥鍜屽彴鐏?",
            owner_agent="灏忓コ瀛?",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(
            plan.plan_id,
            max_items_per_batch=2,
            scene_name="Scene/场景1.scene",
        )

        batch_id = result["batches"][0]["batch_id"]
        state = runtime.query_state("room-provider")["room"]
        self.assertTrue(all(item["status"] == "provider-image" for item in state["image_resource_plans"][batch_id].values()))
        self.assertTrue(all(item["status"] == "provider-model" for item in state["model_resource_plans"][batch_id].values()))
        self.assertTrue(all(actor.get("source") == "provider" for actor in state["actors"].values()))
        self.assertEqual(state["scene_plans"][plan.plan_id]["scene_name"], "Scene/场景1.scene")
        self.assertEqual(result["report"]["provider_summary"]["image_resource"]["mode"], "adapter")
        self.assertEqual(result["report"]["provider_summary"]["model_resource"]["mode"], "adapter")
        self.assertEqual(result["report"]["provider_summary"]["actor_import"]["mode"], "adapter")
        self.assertEqual(result["report"]["provider_readiness_summary"]["enabled_count"], 3)
        self.assertIn("image_resource", result["report"]["provider_readiness_summary"]["enabled_channels"])
        self.assertNotIn("provider", str(result["report"]["provider_readiness_summary"]))
        self.assertIn("provider", runtime._provider_summary["image_resource"])  # internal audit detail stays available
        self.assertNotIn("provider", result["report"]["provider_summary"]["image_resource"])
        self.assertNotIn("image_provider", str(result["report"]["provider_summary"]))
        status_summary = runtime.status_summary("room-provider", plan_id=plan.plan_id)
        self.assertNotIn("provider", status_summary["provider_summary"]["image_resource"])
        self.assertNotIn("model_provider", str(status_summary["provider_summary"]))
        events = runtime.user_visible_events("room-provider", plan_id=plan.plan_id)
        event_types = [event["event_type"] for event in events]
        self.assertIn("scene_snapshot_refreshed", event_types)
        self.assertIn("image_resources_ready", event_types)
        self.assertIn("model_resources_ready", event_types)
        self.assertIn("actors_imported", event_types)
        snapshot_events = [event for event in events if event["event_type"] == "scene_snapshot_refreshed"]
        self.assertEqual(snapshot_events[0]["payload"], {"actor_count": 0, "status": "succeeded"})
        for event in events:
            self.assertNotIn("tool_name", event.get("payload", {}))
            self.assertNotIn("provider", event.get("payload", {}))
        self.assertNotIn("prompt", event.get("payload", {}))
        self.assertIn("runtime_provider_modes_configured", runtime.operation_log.events())

    def test_partial_resource_results_report_ready_and_failed_counts(self) -> None:
        def image_provider(payload: dict) -> dict:
            first = payload["model_items"][0]
            return {
                first: {
                    "name": first,
                    "status": "ready",
                    "mode": "partial-test",
                }
            }

        runtime = AgentRuntime(image_resource_provider=image_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-partial-resource",
            text="鍋氫竴涓彲鐖卞崸瀹わ紝鏈夊簥鍜屽彴鐏?",
            owner_agent="灏忓コ瀛?",
        )
        plan.concrete_object_items = ["bed", "lamp", "desk", "chair", "rug", "doll", "bookshelf"]
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        events = runtime.user_visible_events("room-partial-resource", plan_id=plan.plan_id)
        image_events = [event for event in events if event["event_type"] == "image_resources_ready"]
        self.assertTrue(image_events)
        requested_count = sum(int(event["payload"].get("requested_count") or 0) for event in image_events)
        ready_count = sum(int(event["payload"].get("item_count") or 0) for event in image_events)
        failed_count = sum(int(event["payload"].get("failed_count") or 0) for event in image_events)
        item_count = sum(int(event["payload"].get("item_count") or 0) for event in image_events)
        partial_image_events = [
            event for event in image_events
            if int(event["payload"].get("failed_count") or 0) > 0
        ]
        self.assertTrue(partial_image_events)
        self.assertTrue(all(int(event["payload"].get("batch_index") or 0) >= 1 for event in image_events))
        self.assertTrue(all(int(event["payload"].get("total_batches") or 0) >= 1 for event in image_events))
        self.assertTrue(all(event["level"] == "warning" for event in partial_image_events))
        self.assertTrue(all(str(event.get("title") or "") for event in partial_image_events))
        self.assertEqual(requested_count, 7)
        self.assertEqual(ready_count, len(image_events))
        self.assertEqual(failed_count, 7 - len(image_events))
        self.assertEqual(item_count, ready_count)
        image_summary = result["report"]["resource_summary"]["by_phase"]["image"]
        self.assertEqual(image_summary["requested_count"], 7)
        self.assertEqual(image_summary["item_count"], len(image_events))
        self.assertEqual(image_summary["failed_count"], 7 - len(image_events))

    def test_image_adapter_item_failure_persists_failed_fact_and_partial_event(self) -> None:
        failed_objects: list[str] = []

        def image_tool(payload: dict) -> dict:
            object_name = str(payload["object_name"])
            if not failed_objects:
                failed_objects.append(object_name)
                return {
                    "status": "error",
                    "message": "provider raw url https://internal.example/image api_key=hidden",
                    "image_url": "https://should-not-be-used.example/ref.png",
                }
            return {
                "status": "ok",
                "success": True,
                "image_url": f"https://asset.example/{object_name}.png",
                "content_hash": "sha256:" + "a" * 64,
            }

        runtime = AgentRuntime(image_resource_provider=make_image_resource_provider(image_tool=image_tool))
        plan = runtime.propose_scene_plan(
            room_id="room-image-item-failure",
            text="鍋氫竴涓彲鐖卞崸瀹わ紝鏈夊簥鍜屽彴鐏?",
            owner_agent="灏忓コ瀛?",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        batch_id = result["batches"][0]["batch_id"]
        state = runtime.query_state("room-image-item-failure")["room"]
        image_resources = state["image_resource_plans"][batch_id]
        self.assertEqual(len(failed_objects), 1)
        self.assertEqual(image_resources[failed_objects[0]]["status"], "failed")
        statuses = [resource.get("status") for resource in image_resources.values()]
        self.assertEqual(statuses.count("failed"), 1)
        self.assertEqual(statuses.count("ready"), 1)
        self.assertNotIn("should-not-be-used", str(image_resources))
        self.assertNotIn("provider raw", str(image_resources))
        self.assertNotIn("api_key", str(image_resources))
        image_events = [
            event
            for event in runtime.user_visible_events("room-image-item-failure", plan_id=plan.plan_id)
            if event["event_type"] == "image_resources_ready"
        ]
        self.assertTrue(image_events)
        first_batch_event = image_events[0]
        self.assertEqual(first_batch_event["level"], "warning")
        self.assertEqual(first_batch_event["payload"]["requested_count"], 2)
        self.assertEqual(first_batch_event["payload"]["item_count"], 1)
        self.assertEqual(first_batch_event["payload"]["failed_count"], 1)

