    def test_actor_import_fails_when_explicit_model_resources_have_no_ready_items(self) -> None:
        def model_provider(payload: dict) -> dict:
            return {
                name: {
                    "name": name,
                    "status": "failed",
                    "failure_code": "model_resource_tool_failed",
                    "source": "model_resource",
                }
                for name in payload["model_items"]
            }

        runtime = AgentRuntime(model_resource_provider=model_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-missing-model-import",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        batch = result["batches"][0]
        state = runtime.query_state("room-missing-model-import")["room"]
        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertEqual(state["actors"], {})
        import_result = state["custom_import_facts"][f"{batch['batch_id']}:actor_import_result"]
        self.assertEqual(import_result["source"], "runtime_actor_import_result")
        self.assertEqual(import_result["status"], "failed")
        self.assertEqual(import_result["ready_count"], 0)
        self.assertEqual(import_result["imported_count"], 0)
        self.assertEqual(import_result["failed_count"], import_result["actor_count"])
        self.assertEqual(import_result["failure_code_counts"], {"model_resource_tool_failed": 2})
        self.assertEqual(
            import_result["engine_write_boundary"]["bridge_skip_reason_counts"],
            {"model_resource_tool_failed": 2},
        )
        self.assertNotIn("tool_call_failed", runtime.operation_log.events())
        import_log_entries = [
            entry
            for entry in runtime.operation_log.query(event="tool_call_succeeded")
            if "import_results" in entry.payload
        ]
        self.assertTrue(import_log_entries)
        self.assertEqual(
            {item["status"] for item in import_log_entries[0].payload["import_results"]},
            {"failed"},
        )
        events = runtime.user_visible_events("room-missing-model-import", plan_id=plan.plan_id)
        tool_messages = [event for event in events if event["event_type"] == "tool_result_message"]
        self.assertTrue(tool_messages)
        import_events = [
            event
            for event in events
            if event["event_type"] == "actors_import_failed" and event["batch_id"] == batch["batch_id"]
        ]
        self.assertTrue(import_events)
        self.assertEqual(import_events[-1]["level"], "warning")
        self.assertEqual(import_events[-1]["payload"]["status"], "failed")
        self.assertEqual(import_events[-1]["payload"]["requested_count"], 2)
        self.assertEqual(import_events[-1]["payload"]["imported_count"], 0)
        self.assertEqual(import_events[-1]["payload"]["failed_count"], 2)
        report_import_summary = result["report"]["import_summary"]
        self.assertGreaterEqual(report_import_summary["requested_count"], 2)
        self.assertEqual(report_import_summary["imported_count"], 0)
        self.assertGreaterEqual(report_import_summary["failed_count"], 2)
        self.assertEqual(report_import_summary["latest_events"][-1]["status"], "failed")
        report_registry = result["report"]["scene_entity_registry"]
        self.assertTrue(report_registry["available"])
        self.assertEqual(report_registry["actor_count"], 0)
        self.assertGreater(report_registry["environment_count"], 0)
        self.assertEqual(
            report_registry["entity_count"],
            report_registry["environment_count"],
        )
        self.assertGreaterEqual(report_registry["failed_actor_request_count"], import_result["actor_count"])
        self.assertEqual(
            report_registry["failed_actor_requests"][0]["failure_code"],
            "model_resource_tool_failed",
        )
        boundary = import_result["engine_write_boundary"]
        self.assertEqual(boundary["provider_source"], "runtime_actor_import_precheck")
        self.assertEqual(boundary["bridge_call_count"], 0)
        write_sources = runtime.status_summary("room-missing-model-import", plan_id=plan.plan_id)[
            "engine_write_boundary_summary"
        ]["write_source_counts"]
        self.assertGreaterEqual(write_sources.get("runtime_actor_import_precheck", 0), 1)
        self.assertNotIn("runtime_actor_import", write_sources)
        status_import_summary = runtime.status_summary("room-missing-model-import", plan_id=plan.plan_id)["import_summary"]
        self.assertGreaterEqual(status_import_summary["requested_count"], 2)
        self.assertEqual(status_import_summary["imported_count"], 0)
        self.assertGreaterEqual(status_import_summary["failed_count"], 2)

    def test_actor_import_precheck_rejects_ready_resource_without_model_path(self) -> None:
        def model_provider(payload: dict) -> dict:
            return {
                name: {
                    "name": name,
                    "status": "ready",
                }
                for name in payload["model_items"]
            }

        def actor_import_provider(payload: dict) -> dict:
            raise AssertionError("actor_import_provider must not run without an importable model path")

        runtime = AgentRuntime(
            model_resource_provider=model_provider,
            actor_import_provider=actor_import_provider,
        )
        plan = runtime.propose_scene_plan(
            room_id="room-ready-no-path-import",
            text="生成一个简单藏宝室，有藏宝箱和木桌。",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        batch = result["batches"][0]
        state = runtime.query_state("room-ready-no-path-import")["room"]
        model_phase = state["custom_resource_phase_facts"][f"{batch['batch_id']}:model"]
        self.assertEqual(model_phase["ready_count"], 0)
        self.assertEqual(model_phase["status"], "failed")
        import_plan = state["custom_import_facts"][f"{batch['batch_id']}:actor_import_plan"]
        self.assertEqual(import_plan["status"], "failed")
        self.assertEqual(import_plan["ready_count"], 0)
        self.assertEqual(import_plan["failure_code_counts"], {"missing_ready_model_resource": 2})
        import_result = state["custom_import_facts"][f"{batch['batch_id']}:actor_import_result"]
        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertEqual(state["actors"], {})
        self.assertEqual(import_result["status"], "failed")
        self.assertEqual(import_result["failure_code_counts"], {"missing_ready_model_resource": 2})
        boundary = import_result["engine_write_boundary"]
        self.assertEqual(boundary["provider_source"], "runtime_actor_import_precheck")
        self.assertEqual(boundary["bridge_call_count"], 0)
        self.assertEqual(boundary["status_counts"], {"failed": 2})
        report_boundary = result["report"]["engine_write_boundary_summary"]
        model_resource_summary = result["report"]["operation_replay_summary"]["resource_summary"]["by_phase"]["model"]
        self.assertEqual(model_resource_summary["item_count"], 0)
        self.assertGreaterEqual(model_resource_summary["failed_count"], 2)
        self.assertGreaterEqual(
            report_boundary["write_source_counts"].get("runtime_actor_import_precheck", 0),
            1,
        )
        self.assertNotIn("runtime_actor_import", report_boundary["write_source_counts"])
        self.assertEqual(report_boundary["bridge_call_count"], 0)
        self.assertGreaterEqual(report_boundary["status_counts"].get("failed", 0), 2)

    def test_actor_import_precheck_accepts_metadata_model_folder_mesh(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            model_dir = Path(tmp) / "hunyuan_model"
            nested_dir = model_dir / "model"
            nested_dir.mkdir(parents=True)
            mesh_path = nested_dir / "mesh.glb"
            mesh_path.write_text("glb", encoding="utf-8")

            def model_provider(payload: dict) -> dict:
                return {
                    name: {
                        "name": name,
                        "status": "ready",
                        "metadata": {"model_folder": str(model_dir)},
                    }
                    for name in payload["model_items"]
                }

            import_payloads: list[dict] = []

            def actor_import_provider(payload: dict) -> dict:
                import_payloads.append(dict(payload))
                return {
                    f"engine-{index}": {
                        "actor_id": f"engine-{index}",
                        "name": name,
                        "batch_id": payload["batch_id"],
                        "model_path": str(mesh_path),
                        "position": [float(index), 0.0, 0.0],
                        "rotation": [0.0, 0.0, 0.0],
                        "scale": [1.0, 1.0, 1.0],
                        "aabb": {
                            "min": [float(index), 0.0, 0.0],
                            "max": [float(index) + 1.0, 1.0, 1.0],
                        },
                    }
                    for index, name in enumerate(payload["model_items"], start=1)
                }

            runtime = AgentRuntime(
                model_resource_provider=model_provider,
                actor_import_provider=actor_import_provider,
            )
            plan = runtime.propose_scene_plan(
                room_id="room-folder-case",
                text="generate a treasure room with a treasure chest and a wooden table",
                owner_agent="Merchant",
            )
            runtime.confirm_scene_plan(plan.plan_id, confirmed_by="host")

            result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

            batch = result["batches"][0]
            state = runtime.query_state("room-folder-case")["room"]
            model_phase = state["custom_resource_phase_facts"][f"{batch['batch_id']}:model"]
            self.assertGreaterEqual(model_phase["ready_count"], 1)
            self.assertTrue(import_payloads)
            import_plan = state["custom_import_facts"][f"{batch['batch_id']}:actor_import_plan"]
            self.assertGreaterEqual(import_plan["ready_count"], 1)
            import_result = state["custom_import_facts"][f"{batch['batch_id']}:actor_import_result"]
            self.assertEqual(import_result["status"], "imported")
            self.assertGreaterEqual(len(state["actors"]), 1)
            self.assertNotEqual(
                import_result["engine_write_boundary"]["provider_source"],
                "runtime_actor_import_precheck",
            )
            registry_entities = [
                entity
                for entity in result["report"]["scene_entity_registry"]["entities"]
                if entity.get("entity_type") == "actor"
            ]
            self.assertTrue(registry_entities)
            self.assertTrue(all(entity.get("model_ref") == "mesh.glb" for entity in registry_entities))
            self.assertTrue(all(str(entity.get("asset_id") or "").strip() for entity in registry_entities))
            self.assertTrue(all(entity.get("asset_id") != entity.get("actor_name") for entity in registry_entities))
            self.assertNotIn(str(model_dir), str(registry_entities))
            self.assertNotIn(str(mesh_path), str(registry_entities))

