    def test_runtime_resource_adapters_do_not_call_legacy_main_workflows(self) -> None:
        adapters_path = REPO_ROOT / "editor/plugins/AITool/services/agent_runtime/adapters.py"
        module = ast.parse(adapters_path.read_text(encoding="utf-8-sig"))
        target_functions = {
            "make_image_resource_provider",
            "make_model_resource_provider",
            "make_environment_component_provider",
            "make_legacy_model_resource_provider",
            "make_scene_snapshot_provider",
            "make_scene_review_provider",
        }
        forbidden_tokens = {
            "SceneComposer",
            "run_progressive_workflow",
            "GenerationScheduler",
            "SceneComposerJobRunner",
            "legacy.scene_compose",
            "legacy.progressive_compose",
            "legacy.generation_scheduler",
        }
        violations: list[str] = []

        for node in module.body:
            if not isinstance(node, ast.FunctionDef) or node.name not in target_functions:
                continue
            docstring_node = node.body[0] if node.body and isinstance(node.body[0], ast.Expr) else None
            for child in ast.walk(node):
                if child is docstring_node or (
                    isinstance(child, ast.Constant)
                    and docstring_node is not None
                    and isinstance(docstring_node.value, ast.Constant)
                    and child is docstring_node.value
                ):
                    continue
                if isinstance(child, ast.Name) and child.id in forbidden_tokens:
                    violations.append(f"{node.name}: name {child.id}")
                elif isinstance(child, ast.Constant) and isinstance(child.value, str):
                    for token in forbidden_tokens:
                        if token in child.value:
                            violations.append(f"{node.name}: string {token}")
                elif isinstance(child, ast.Attribute) and child.attr in {
                    "compose",
                    "submit",
                    "run_progressive_workflow",
                }:
                    owner = ast.unparse(child.value) if hasattr(ast, "unparse") else ""
                    if owner in {"SceneComposer", "GenerationScheduler", "scheduler", "composer"}:
                        violations.append(f"{node.name}: attribute {owner}.{child.attr}")

        self.assertFalse(
            violations,
            "Runtime resource adapters must stay function-sized and must not call old workflow main controllers: "
            f"{violations}",
        )

