    def test_scene_snapshot_and_observed_actor_facts_reject_private_fields(self) -> None:
        snapshot = {
            "snapshot-id": {
                "snapshot_id": "snapshot-id",
                "room_id": "room-scene-snapshot",
                "scene_name": "Scene/场景1.scene",
                "actor_count": 1,
                "source": "scene_snapshot_provider",
                "actors": [
                    {
                        "actor_id": "actor-box",
                        "name": "钘忓疂绠?",
                        "position": [1.0, 0.0, 0.0],
                        "rotation": [0.0, 0.0, 0.0],
                        "scale": [1.0, 1.0, 1.0],
                        "source": "native_snapshot",
                    }
                ],
            }
        }
        observed = {
            "actor-box": {
                "actor_id": "actor-box",
                "name": "钘忓疂绠?",
                "position": [1.0, 0.0, 0.0],
                "rotation": [0.0, 0.0, 0.0],
                "scale": [1.0, 1.0, 1.0],
                "source": "native_snapshot",
            }
        }
        SceneSnapshotFactValidator.validate_snapshots(snapshot)

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-scene-snapshot",
                changes={
                    "engine_scene_snapshots": snapshot,
                    "observed_actors": observed,
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)

        unsafe_snapshot = {
            "snapshot-id": {
                **snapshot["snapshot-id"],
                "screenshot_path": "C:/temp/hidden.png",
            }
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-scene-snapshot",
                changes={"engine_scene_snapshots": unsafe_snapshot},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("engine scene snapshot cannot expose field: screenshot_path", reason)

        unsafe_observed = {
            "actor-box": {
                **observed["actor-box"],
                "provider": "hidden-native-provider",
            }
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-scene-snapshot",
                changes={"observed_actors": unsafe_observed},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("actor fact cannot expose field: provider", reason)

    def test_provider_status_publishes_safe_readiness_without_creating_plan(self) -> None:
        def image_provider(payload: dict) -> dict:
            return {}

        runtime = AgentRuntime(
            image_resource_provider=image_provider,
            provider_diagnostics={
                "image_resource": {
                    "requested": True,
                    "status": "enabled",
                    "reason": "f5_preflight",
                }
            },
        )
        runtime.operation_log.append(
            "runtime_system_event_send_failed",
            room_id="room-provider-status",
            payload={
                "message_kind": "runtime_status",
                "channel": "network_send_system_message_ex",
                "sent": False,
                "stage": "璧勬簮棰勬",
                "progress": 0,
                "source_user_id": "host-secret",
                "provider": "hidden",
                "prompt": "hidden",
                "url": "https://example.invalid/private",
            },
        )

        result = runtime.provider_status("room-provider-status")

        self.assertTrue(result["snapshot_recorded"])
        self.assertEqual(result["snapshot_status"], "completed")
        self.assertEqual(result["snapshot_tool_status"], ToolCallStatus.SUCCEEDED.value)
        self.assertGreaterEqual(result["snapshot_state_version"], 1)
        provider_summary = result["provider_summary"]
        provider_readiness = result["provider_readiness_summary"]
        delivery = result["message_delivery_summary"]
        self.assertEqual(
            set(provider_summary),
            {
                "scene_snapshot",
                "image_resource",
                "model_resource",
                "environment_component",
                "environment_import",
                "actor_import",
                "actor_delete",
                "review",
                "vlm_review",
                "layout_transform",
            },
        )
        self.assertEqual(provider_summary["image_resource"]["mode"], "adapter")
        self.assertEqual(provider_summary["environment_import"]["mode"], "runtime_state_only")
        self.assertEqual(provider_summary["actor_delete"]["mode"], "runtime_state_only")
        self.assertTrue(provider_summary["image_resource"]["requested"])
        self.assertEqual(provider_summary["image_resource"]["status"], "enabled")
        self.assertEqual(provider_readiness["requested_count"], 1)
        self.assertEqual(provider_readiness["enabled_count"], 1)
        runtime._provider_summary = {}
        restored_status = runtime.provider_status("room-provider-status")
        self.assertEqual(restored_status["provider_readiness_summary"]["channel_count"], 10)
        self.assertEqual(restored_status["engine_write_readiness_summary"]["channel_count"], 4)
        self.assertEqual(
            restored_status["engine_write_readiness_summary"]["runtime_state_only_channels"],
            ["environment_import", "actor_delete", "layout_transform"],
        )
        self.assertEqual(delivery["failed_count"], 1)
        self.assertEqual(delivery["message_kind_counts"]["runtime_status"], 1)
        self.assertNotIn("provider", provider_summary["image_resource"])
        self.assertNotIn("image_provider", str(provider_summary))
        self.assertNotIn("source_user_id", str(delivery))
        self.assertNotIn("host-secret", str(delivery))
        self.assertNotIn("provider", str(delivery))
        self.assertNotIn("https://example.invalid", str(delivery))
        room = runtime.query_state("room-provider-status")["room"]
        self.assertEqual(room["scene_plans"], {})
        self.assertEqual(room["active_plan_id"], "")
        self.assertIn("provider_readiness", room)
        self.assertEqual(room.get("custom_report_facts", {}), {})
        self.assertNotIn("provider", room["provider_readiness"]["image_resource"])
        self.assertNotIn("image_provider", str(room["provider_readiness"]))
        readiness_graphs = [
            graph
            for graph in room["tool_graphs"].values()
            if {
                str(node.get("tool_name") or "")
                for node in dict(graph.get("nodes") or {}).values()
            }
            == {"runtime.provider_readiness.publish"}
        ]
        self.assertEqual(len(readiness_graphs), 1)
        self.assertEqual(readiness_graphs[0]["status"], "completed")
        provider_status_fact = runtime.query_state("runtime-provider-status")["room"]["custom_report_facts"][
            "room-provider-status:room:no-external:runtime_provider_status"
        ]
        self.assertEqual(provider_status_fact["source"], "runtime_provider_status_snapshot")
        provider_status_without_snapshot_evidence = dict(result)
        for key in ("snapshot_recorded", "snapshot_status", "snapshot_tool_status", "snapshot_state_version"):
            provider_status_without_snapshot_evidence.pop(key, None)
        self.assertEqual(provider_status_fact["provider_status"], provider_status_without_snapshot_evidence)
        self.assertIn("runtime_provider_status_snapshot_recorded", runtime.operation_log.events())
        status_summary = runtime.status_summary("room-provider-status")
        readiness_summary = status_summary["provider_readiness_summary"]
        engine_adapter_summary = status_summary["engine_write_adapter_summary"]
        self.assertEqual(readiness_summary["channel_count"], 10)
        self.assertEqual(readiness_summary["requested_count"], 1)
        self.assertEqual(readiness_summary["enabled_count"], 1)
        self.assertIn("image_resource", readiness_summary["enabled_channels"])
        self.assertEqual(engine_adapter_summary["channel_count"], 4)
        self.assertEqual(engine_adapter_summary["write_attempt_count"], 0)
        self.assertEqual(
            engine_adapter_summary["channels"]["environment_import"]["readiness_status"],
            "runtime_state_only",
        )
        self.assertEqual(
            engine_adapter_summary["channels"]["actor_delete"]["readiness_status"],
            "runtime_state_only",
        )
        self.assertNotIn("provider", str(readiness_summary))
        self.assertNotIn("provider", str(engine_adapter_summary))
        self.assertNotIn("image_provider", str(readiness_summary))
        self.assertIn("runtime_provider_status_queried", runtime.operation_log.events())
        self.assertIn("runtime_provider_readiness_published", runtime.operation_log.events())
        visible_events = runtime.user_visible_events("room-provider-status")
        self.assertTrue(any(event["event_type"] == "provider_readiness" for event in visible_events))
        for event in visible_events:
            self.assertNotIn("provider", event.get("payload", {}))
            self.assertNotIn("image_provider", str(event))
            if event["event_type"] == "provider_readiness":
                self.assertNotIn("provider", str(event["title"]).lower())
                self.assertNotIn("provider", str(event["message"]).lower())
                self.assertNotIn("image_resource", str(event))
                self.assertIn("resource channel", str(event["title"]).lower())
        replay = runtime.operation_replay(room_id="room-provider-status")
        readiness_replay = replay["resource_readiness_replay_summary"]
        self.assertEqual(readiness_replay["status_query_count"], 1)
        self.assertEqual(readiness_replay["published_count"], 1)
        self.assertEqual(readiness_replay["publish_failed_count"], 0)
        self.assertEqual(readiness_replay["readiness_event_count"], 1)
        self.assertEqual(readiness_replay["status_counts"], {"enabled": 1})
        self.assertEqual(readiness_replay["latest_readiness_event"]["status"], "enabled")
        self.assertNotIn("image_provider", str(readiness_replay))
        self.assertNotIn("f5_preflight", str(readiness_replay))
        report = runtime.generate_report("room-provider-status")
        report_readiness = report["operation_replay_summary"]["resource_readiness_replay_summary"]
        report_engine_adapter = report["engine_write_adapter_summary"]
        self.assertEqual(report_readiness["status_query_count"], 1)
        self.assertEqual(report_readiness["published_count"], 1)
        self.assertEqual(report_readiness["readiness_event_count"], 1)
        self.assertEqual(report_engine_adapter["channel_count"], 4)
        self.assertEqual(report_engine_adapter["readiness_mismatch_count"], 0)
        self.assertNotIn("provider", str(report_engine_adapter))

    def test_provider_status_external_plan_scopes_engine_write_summary(self) -> None:
        runtime = AgentRuntime()
        first = runtime.handle_message(
            room_id="room-provider-engine-scope",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-provider-engine-a",
            max_items_per_batch=2,
        )
        second = runtime.handle_message(
            room_id="room-provider-engine-scope",
            text="鍋氫竴涓．鏋楄惀鍦帮紝鏈夊笎绡峰拰鏈ㄦ",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-provider-engine-b",
            max_items_per_batch=2,
        )
        runtime.operation_log.append(
            "tool_call_succeeded",
            room_id="room-provider-engine-scope",
            plan_id=first["plan"]["plan_id"],
            payload={
                "import_results": [
                    {
                        "actor_id": "actor-first-provider",
                        "actor_name": "绗竴璁″垝瀹濈",
                        "status": "success",
                    }
                ]
            },
        )
        runtime.operation_log.append(
            "tool_call_succeeded",
            room_id="room-provider-engine-scope",
            plan_id=second["plan"]["plan_id"],
            payload={
                "import_results": [
                    {
                        "actor_id": "actor-second-provider",
                        "actor_name": "绗簩璁″垝甯愮",
                        "status": "success",
                    }
                ]
            },
        )

        status = runtime.provider_status(
            "room-provider-engine-scope",
            external_plan_id="seed-provider-engine-a",
        )

        engine_summary = status["engine_write_summary"]
        self.assertEqual(status["plan_id"], first["plan"]["plan_id"])
        self.assertEqual(engine_summary["import_result_count"], 1)
        self.assertEqual(engine_summary["latest_import_results"][0]["status"], "success")
        self.assertIn("绗竴璁″垝", engine_summary["latest_import_results"][0]["actor_name"])
        self.assertNotIn("actor-second-provider", str(engine_summary))
        exported = runtime.operation_log.query(
            event="runtime_provider_status_queried",
            room_id="room-provider-engine-scope",
        )[-1]
        self.assertEqual(exported.plan_id, first["plan"]["plan_id"])
        self.assertEqual(exported.payload["external_plan_id"], "seed-provider-engine-a")
        provider_status_fact = runtime.query_state("runtime-provider-status")["room"]["custom_report_facts"][
            f"room-provider-engine-scope:{first['plan']['plan_id']}:seed-provider-engine-a:runtime_provider_status"
        ]
        provider_status_without_snapshot_evidence = dict(status)
        for key in ("snapshot_recorded", "snapshot_status", "snapshot_tool_status", "snapshot_state_version"):
            provider_status_without_snapshot_evidence.pop(key, None)
        self.assertEqual(provider_status_fact["provider_status"], provider_status_without_snapshot_evidence)
        self.assertEqual(provider_status_fact["plan_id"], first["plan"]["plan_id"])
        self.assertEqual(provider_status_fact["external_plan_id"], "seed-provider-engine-a")

