    def test_provider_status_unknown_external_plan_does_not_fallback_to_active_plan(self) -> None:
        runtime = AgentRuntime()
        active = runtime.handle_message(
            room_id="room-provider-engine-missing",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            sender_id="host-1",
            sender_name="host",
            action="confirm_and_execute",
            external_plan_id="seed-provider-engine-existing",
            max_items_per_batch=2,
        )
        runtime.operation_log.append(
            "tool_call_succeeded",
            room_id="room-provider-engine-missing",
            plan_id=active["plan"]["plan_id"],
            payload={
                "import_results": [
                    {
                        "actor_id": "actor-active-provider",
                        "actor_name": "娲诲姩璁″垝瀹濈",
                        "status": "success",
                    }
                ]
            },
        )

        status = runtime.provider_status(
            "room-provider-engine-missing",
            external_plan_id="seed-provider-engine-missing",
        )

        self.assertEqual(status["plan_id"], "")
        self.assertFalse(status["readiness_published"])
        self.assertEqual(status["readiness_publish"]["reason"], "no runtime plan")
        self.assertEqual(status["engine_write_summary"]["import_result_count"], 0)
        self.assertNotIn("actor-active-provider", str(status))
        exported = runtime.operation_log.query(
            event="runtime_provider_status_queried",
            room_id="room-provider-engine-missing",
        )[-1]
        self.assertEqual(exported.payload["recorded"], False)
        self.assertEqual(exported.payload["reason"], "no runtime plan")
        provider_status_fact = runtime.query_state("runtime-provider-status")["room"]["custom_report_facts"][
            "room-provider-engine-missing:room:seed-provider-engine-missing:runtime_provider_status"
        ]
        provider_status_without_snapshot_evidence = dict(status)
        for key in ("snapshot_recorded", "snapshot_status", "snapshot_tool_status", "snapshot_state_version"):
            provider_status_without_snapshot_evidence.pop(key, None)
        self.assertEqual(provider_status_fact["provider_status"], provider_status_without_snapshot_evidence)
        self.assertEqual(provider_status_fact["external_plan_id"], "seed-provider-engine-missing")

    def test_provider_status_snapshot_failure_blocks_status_return(self) -> None:
        runtime = AgentRuntime()
        original_apply_patch = runtime.state.apply_patch

        def reject_provider_status_fact_patch(patch: StatePatch) -> tuple[bool, str]:
            if patch.room_id == "runtime-provider-status" and "custom_report_facts" in patch.changes:
                return False, "state version conflict"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_provider_status_fact_patch  # type: ignore[method-assign]

        with self.assertRaisesRegex(RuntimeError, "failed to record runtime provider status"):
            runtime.provider_status("room-provider-status-failure")

        events = runtime.operation_log.events()
        self.assertIn("runtime_provider_status_queried", events)
        self.assertIn("runtime_provider_status_snapshot_failed", events)
        self.assertNotIn("runtime_provider_status_snapshot_recorded", events)

