    def test_provider_readiness_validator_rejects_internal_provider_fields(self) -> None:
        with self.assertRaisesRegex(ValueError, "cannot expose field: provider"):
            ProviderReadinessValidator.validate(
                {
                    "image_resource": {
                        "mode": "adapter",
                        "provider": "plugins.AITool.internal.image_provider",
                    }
                }
            )

        with self.assertRaisesRegex(ValueError, "reason contains unsafe provider detail"):
            ProviderReadinessValidator.validate(
                {
                    "image_resource": {
                        "mode": "adapter",
                        "requested": True,
                        "status": "unavailable",
                        "reason": "provider raw url https://internal.example/image api_key=hidden",
                    }
                }
            )

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-provider-invalid",
                changes={
                    "provider_readiness": {
                        "image_resource": {
                            "mode": "adapter",
                            "provider": "plugins.AITool.internal.image_provider",
                        }
                    }
                },
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("cannot expose field: provider", reason)

        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-provider-invalid",
                changes={
                    "provider_readiness": {
                        "image_resource": {
                            "mode": "adapter",
                            "requested": True,
                            "status": "unavailable",
                            "reason": "provider raw url https://internal.example/image api_key=hidden",
                        }
                    }
                },
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("reason contains unsafe provider detail", reason)

