    def test_provider_readiness_persist_failure_does_not_emit_runtime_event(self) -> None:
        runtime = AgentRuntime(
            provider_diagnostics={
                "image_resource": {
                    "requested": True,
                    "status": "unavailable",
                    "reason": "missing_tool:generate_image",
                }
            }
        )
        original_apply_patch = runtime.state.apply_patch

        def reject_provider_readiness_patch(patch: StatePatch) -> tuple[bool, str]:
            if "provider_readiness" in patch.changes:
                return False, "simulated provider readiness persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_provider_readiness_patch  # type: ignore[method-assign]

        result = runtime.handle_message(
            room_id="room-provider-readiness-fail",
            text="check provider readiness",
            action="provider_status",
        )

        self.assertTrue(result["handled"])
        self.assertFalse(result["recorded"])
        self.assertFalse(result["provider_status"]["readiness_published"])
        self.assertFalse(result["provider_status"]["readiness_publish"]["persisted"])
        self.assertEqual(
            result["provider_status"]["readiness_publish"]["reason"],
            "RuntimeState persistence failed",
        )
        self.assertIn("was not published", result["message"])
        self.assertNotIn("provider", result["message"])
        room = runtime.query_state("room-provider-readiness-fail")["room"]
        self.assertEqual(room["provider_readiness"], {})
        events = runtime.operation_log.events()
        self.assertIn("runtime_provider_readiness_publish_failed", events)
        self.assertNotIn("runtime_provider_readiness_published", events)
        visible_events = runtime.user_visible_events("room-provider-readiness-fail")
        self.assertFalse([event for event in visible_events if event["event_type"] == "provider_readiness"])

