    def test_runtime_report_exposes_safe_provider_diagnostics(self) -> None:
        runtime = AgentRuntime(
            provider_diagnostics={
                "scene_snapshot": {
                    "requested": True,
                    "status": "unavailable",
                    "reason": "missing_engine",
                },
                "ignored": {
                    "requested": True,
                    "status": "bad",
                    "reason": "bad",
                },
            }
        )
        plan = runtime.propose_scene_plan(
            room_id="room-provider-diagnostics",
            text="build a small room with a box",
            owner_agent="merchant",
        )
        room_after_plan = runtime.query_state("room-provider-diagnostics")["room"]
