    def test_runtime_execution_graph_consumes_are_derived_from_tool_definition_contract(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-contract-graph",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_scene_plan(plan.plan_id, include_debug_graph_nodes=True)

        manifest = {
            tool["name"]: dict(tool.get("consumes_state") or {})
            for tool in runtime.tool_manifest()["tools"]
        }
        nodes_by_tool = {
            node["tool_name"]: node
            for node in result["graph"]["nodes"].values()
        }
        tool_call_ids = {
            tool_name: node["tool_call_id"]
            for tool_name, node in nodes_by_tool.items()
        }

        def depends_on_transitively(tool_name: str, upstream_tool_name: str) -> bool:
            upstream_id = tool_call_ids[upstream_tool_name]
            pending = list(nodes_by_tool[tool_name].get("depends_on") or [])
            seen: set[str] = set()
            nodes_by_id = {
                node["tool_call_id"]: node
                for node in result["graph"]["nodes"].values()
            }
            while pending:
                current = pending.pop()
                if current == upstream_id:
                    return True
                if current in seen:
                    continue
                seen.add(current)
                pending.extend(nodes_by_id.get(current, {}).get("depends_on") or [])
            return False

        for tool_name, target_args in {
            "runtime.asset.plan": ("model_items",),
            "runtime.substrate.plan": ("routes",),
            "runtime.substrate.resolve": ("substrate_plan",),
            "runtime.environment.create_components": ("substrate_resolutions", "room_bounds"),
            "runtime.environment.import_components": ("environment_components",),
            "runtime.asset.image.prepare": ("asset_requests", "model_items"),
            "runtime.asset.model.prepare": ("asset_requests", "model_items", "image_resources"),
            "runtime.placement.propose": ("model_items", "observed_actors", "environment_components"),
            "runtime.geometry.review": ("placements", "environment_components"),
            "runtime.actor.plan_import_batch": ("model_items", "model_resources", "placements", "environment_components"),
            "runtime.actor.import_batch": (
                "model_items",
                "model_resources",
                "placements",
                "environment_components",
                "actor_import_plan",
            ),
            "runtime.review.vlm_checkpoint": ("actors", "placements", "environment_components"),
            "runtime.review.summarize_batch": (
                "geometry_review",
                "ground_snap_reviews",
                "vlm_checkpoints",
                "actor_import_plan",
                "actors",
            ),
            "runtime.review.generate_adjustment_proposal": (
                "geometry_review",
                "ground_snap_reviews",
                "batch_review_summary",
                "review_advisories",
            ),
        }.items():
            expected = {
                target: manifest[tool_name][target]
                for target in target_args
            }
            self.assertEqual(nodes_by_tool[tool_name]["consumes"], expected)

        self.assertEqual(
            next(tool for tool in runtime.tool_manifest()["tools"] if tool["name"] == "runtime.asset.image.prepare")["produces_state"],
            ["image_resource_plans", "custom_resource_phase_facts"],
        )
        self.assertIn(
            tool_call_ids["runtime.asset.image.prepare"],
            nodes_by_tool["runtime.asset.model.prepare"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.scene.snapshot"],
            nodes_by_tool["scene.extract_objects"]["depends_on"],
        )
        self.assertTrue(depends_on_transitively("runtime.placement.propose", "runtime.scene.snapshot"))
        self.assertTrue(depends_on_transitively("runtime.geometry.review", "runtime.scene.snapshot"))
        self.assertTrue(depends_on_transitively("runtime.actor.import_batch", "runtime.scene.snapshot"))
        self.assertTrue(depends_on_transitively("runtime.review.vlm_checkpoint", "runtime.scene.snapshot"))
        self.assertIn(
            tool_call_ids["runtime.asset.model.prepare"],
            nodes_by_tool["runtime.placement.propose"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.environment.import_components"],
            nodes_by_tool["runtime.placement.propose"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.placement.propose"],
            nodes_by_tool["runtime.geometry.review"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.environment.import_components"],
            nodes_by_tool["runtime.geometry.review"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.geometry.review"],
            nodes_by_tool["runtime.actor.plan_import_batch"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.actor.plan_import_batch"],
            nodes_by_tool["runtime.actor.import_batch"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.environment.import_components"],
            nodes_by_tool["runtime.actor.plan_import_batch"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.actor.import_batch"],
            nodes_by_tool["runtime.review.vlm_checkpoint"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.review.vlm_checkpoint"],
            nodes_by_tool["runtime.review.summarize_batch"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.geometry.review"],
            nodes_by_tool["runtime.review.summarize_batch"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.actor.import_batch"],
            nodes_by_tool["runtime.review.summarize_batch"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.review.summarize_batch"],
            nodes_by_tool["runtime.review.generate_adjustment_proposal"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.geometry.review"],
            nodes_by_tool["runtime.review.generate_adjustment_proposal"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.review.vlm_checkpoint"],
            nodes_by_tool["runtime.review.generate_adjustment_proposal"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.geometry.review"],
            nodes_by_tool["runtime.review.vlm_checkpoint"]["depends_on"],
        )
        self.assertIn(
            tool_call_ids["runtime.substrate.resolve"],
            nodes_by_tool["runtime.environment.create_components"]["depends_on"],
        )
        self.assertFalse(nodes_by_tool["runtime.environment.create_components"]["requires_write"])
        self.assertFalse(nodes_by_tool["runtime.environment.create_components"]["confirmed"])
        self.assertIn("runtime.environment.import_components", nodes_by_tool)
        self.assertTrue(nodes_by_tool["runtime.environment.import_components"]["requires_write"])
        self.assertTrue(nodes_by_tool["runtime.environment.import_components"]["confirmed"])
        self.assertIn(
            tool_call_ids["runtime.environment.create_components"],
            nodes_by_tool["runtime.environment.import_components"]["depends_on"],
        )
        self.assertTrue(nodes_by_tool["runtime.actor.import_batch"]["requires_write"])
        self.assertTrue(nodes_by_tool["runtime.actor.import_batch"]["confirmed"])
        self.assertTrue(depends_on_transitively("runtime.actor.import_batch", "runtime.substrate.resolve"))
        self.assertTrue(depends_on_transitively("runtime.review.vlm_checkpoint", "runtime.substrate.resolve"))
        self.assertTrue(depends_on_transitively("runtime.review.summarize_batch", "runtime.substrate.resolve"))
        self.assertTrue(depends_on_transitively("runtime.review.generate_adjustment_proposal", "runtime.substrate.resolve"))

    def test_runtime_execution_graph_uses_environment_import_node_when_provider_is_enabled(self) -> None:
        provider_calls: list[dict[str, Any]] = []

        def environment_component_provider(payload: dict[str, Any]) -> dict[str, Any]:
            return {
                "component-room-box": {
                    "component_id": "component-room-box",
                    "name": "__room_box",
                    "component_type": "room_box",
                    "status": "planned",
                    "source": "runtime_environment_component",
                    "scene_name": str(payload.get("scene_name") or ""),
                    "requires_engine_write": False,
                },
            }

        def environment_import_provider(payload: dict[str, Any]) -> dict[str, Any]:
            provider_calls.append(dict(payload))
            components = {}
            for component_id, component in dict(payload.get("environment_components") or {}).items():
                row = dict(component)
                row["component_id"] = str(component_id)
                row["status"] = "imported"
                row["source"] = "engine_environment_import"
                row["scene_name"] = str(payload.get("scene_name") or "")
                row["requires_engine_write"] = False
                row.setdefault("actor_id", f"actor-{component_id}")
                components[str(component_id)] = row
            return {"environment_components": components}

        runtime = AgentRuntime(
            environment_component_provider=environment_component_provider,
            environment_import_provider=environment_import_provider,
        )
        plan = runtime.propose_scene_plan(
            room_id="room-env-import-graph",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, scene_name="Scene/env-import.scene")

        self.assertTrue(result["graphs"])
        graph_row = result["graphs"][0]
        nodes_by_tool = {
            node["tool_name"]: node
            for node in graph_row["nodes"].values()
        }
        tool_call_ids = {
            tool_name: node["tool_call_id"]
            for tool_name, node in nodes_by_tool.items()
        }
        self.assertIn("runtime.environment.import_components", nodes_by_tool)
        self.assertTrue(nodes_by_tool["runtime.environment.import_components"]["requires_write"])
        self.assertTrue(nodes_by_tool["runtime.environment.import_components"]["confirmed"])
        self.assertIn(
            tool_call_ids["runtime.environment.create_components"],
            nodes_by_tool["runtime.environment.import_components"]["depends_on"],
        )
        for downstream in (
            "runtime.placement.propose",
            "runtime.geometry.review",
            "runtime.actor.import_batch",
            "runtime.review.vlm_checkpoint",
        ):
            self.assertIn(tool_call_ids["runtime.environment.import_components"], nodes_by_tool[downstream]["depends_on"])
        self.assertTrue(provider_calls)
        self.assertEqual(provider_calls[0]["scene_name"], "Scene/env-import.scene")
        self.assertTrue(provider_calls[0]["environment_components"])
        room = runtime.query_state("room-env-import-graph")["room"]
        batch_id = next(iter(room["environment_components"].keys()))
        components = room["environment_components"][batch_id]
        self.assertTrue(components)
        self.assertTrue(all(component["status"] == "imported" for component in components.values()))
        self.assertTrue(any(str(component.get("actor_id") or "").startswith("actor-") for component in components.values()))
        events = runtime.user_visible_events("room-env-import-graph", plan_id=plan.plan_id)
        import_events = [
            event
            for event in events
            if event["event_type"] == "environment_components_imported"
        ]
        self.assertTrue(import_events)
        last_event_batch_id = str(import_events[-1]["batch_id"])
        last_event_components = dict(room["environment_components"].get(last_event_batch_id) or {})
        self.assertEqual(import_events[-1]["phase"], "environment_import")
        self.assertTrue(import_events[-1]["title"])
        self.assertEqual(import_events[-1]["payload"]["status"], "succeeded")
        self.assertEqual(import_events[-1]["payload"]["component_count"], len(last_event_components))
        self.assertEqual(import_events[-1]["payload"]["requested_count"], len(provider_calls[-1]["environment_components"]))
        self.assertEqual(import_events[-1]["payload"]["failed_count"], 0)
        self.assertIn("batch_index", import_events[-1]["payload"])
        self.assertNotIn("tool_name", import_events[-1]["payload"])
        self.assertNotIn("provider", import_events[-1]["payload"])
        total_components = sum(
            len(dict(batch_components))
            for batch_components in dict(room["environment_components"]).values()
        )
        total_requested = sum(len(call["environment_components"]) for call in provider_calls)
        environment_summary = runtime.status_summary(
            "room-env-import-graph",
            plan_id=plan.plan_id,
        )["environment_component_summary"]
        registry = runtime.status_summary(
            "room-env-import-graph",
            plan_id=plan.plan_id,
        )["scene_entity_registry"]
        registry_roles = {entity["semantic_role"]: entity for entity in registry["entities"]}
        room_box_entity = registry_roles["indoor_enclosure"]
        self.assertEqual(room_box_entity["entity_type"], "environment")
        self.assertEqual(room_box_entity["component_type"], "room_box")
        self.assertEqual(room_box_entity["environment_component_type"], "room_box")
        self.assertEqual(room_box_entity["component_id"], "component-room-box")
        self.assertTrue(str(room_box_entity["actor_id"]).startswith("actor-"))
        self.assertEqual(environment_summary["import_event_count"], len(provider_calls))
        self.assertEqual(environment_summary["imported_count"], total_components)
        self.assertEqual(environment_summary["import_requested_count"], total_requested)
        self.assertEqual(environment_summary["import_failed_count"], 0)
        self.assertEqual(environment_summary["latest_events"][-1]["event_type"], "environment_components_imported")
        replay_environment_summary = runtime.operation_replay(
            room_id="room-env-import-graph",
            plan_id=plan.plan_id,
        )["environment_component_summary"]
        self.assertEqual(replay_environment_summary["import_event_count"], len(provider_calls))
        self.assertEqual(replay_environment_summary["import_failed_event_count"], 0)
        self.assertEqual(
            replay_environment_summary["event_type_counts"]["environment_components_imported"],
            len(provider_calls),
        )
        self.assertEqual(
            replay_environment_summary["latest_event_type"],
            "environment_components_imported",
        )

    def test_runtime_state_only_environment_import_event_requires_f5_verification(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-env-runtime-state-only-event",
            text="生成一个森林营地，有草地、帐篷、小木桌。",
            owner_agent="长者",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=3)

        self.assertTrue(result["graphs"])
        events = runtime.user_visible_events("room-env-runtime-state-only-event", plan_id=plan.plan_id)
        import_events = [
            event
            for event in events
            if event["event_type"] == "environment_components_imported"
        ]
        self.assertTrue(import_events)
        latest = import_events[-1]
        self.assertEqual(latest["phase"], "environment_import")
        self.assertEqual(latest["level"], "warning")
        self.assertEqual(latest["title"], "环境组件已进入 Runtime 状态")
        self.assertIn("仍待 F5", latest["message"])
        self.assertEqual(latest["payload"]["status"], "runtime_state_only")
        self.assertEqual(latest["payload"]["engine_write_bridge_call_count"], 0)
        self.assertNotIn("已通过引擎写入", latest["message"])
        report_ready_events = [
            event
            for event in events
            if event["event_type"] == "report_ready"
        ]
        self.assertTrue(report_ready_events)
        report_ready = report_ready_events[-1]
        self.assertEqual(report_ready["level"], "warning")
        self.assertIn("待 F5", report_ready["message"])
        self.assertEqual(
            report_ready["payload"]["report_health_status"],
            "needs_attention",
        )
        self.assertGreater(
            report_ready["payload"]["engine_write_runtime_state_only_count"],
            0,
        )
        self.assertIn(
            "environment-import",
            report_ready["payload"]["engine_write_runtime_state_only_channels"],
        )
        self.assertIn(
            "engine_write_runtime_state_only",
            report_ready["payload"]["report_health_reasons"],
        )
        self.assertGreater(
            report_ready["payload"]["scene_entity_engine_write_pending_f5_count"],
            0,
        )
        self.assertIn(
            "pending_f5",
            report_ready["payload"]["scene_entity_engine_write_verification_status_counts"],
        )
        status = runtime.status_summary(
            "room-env-runtime-state-only-event",
            plan_id=plan.plan_id,
        )
        self.assertEqual(status["report_health_summary"]["status"], "needs_attention")
        self.assertGreater(
            status["report_health_summary"]["engine_write_runtime_state_only_count"],
            0,
        )
        self.assertIn(
            "environment-import",
            status["report_health_summary"]["engine_write_runtime_state_only_channels"],
        )
        self.assertGreater(
            status["scene_entity_registry"]["engine_write_pending_f5_count"],
            0,
        )
        self.assertIn(
            "pending_f5",
            status["scene_entity_registry"]["engine_write_verification_status_counts"],
        )
        self.assertGreater(
            status["report_health_summary"]["scene_entity_engine_write_pending_f5_count"],
            0,
        )
        status_logs = [
            entry
            for entry in runtime.operation_log.entries()
            if entry.event == "runtime_status_queried"
            and entry.plan_id == plan.plan_id
        ]
        self.assertTrue(status_logs)
        self.assertGreater(
            status_logs[-1].payload["engine_write_runtime_state_only_count"],
            0,
        )
        self.assertIn(
            "environment-import",
            status_logs[-1].payload["engine_write_runtime_state_only_channels"],
        )
        self.assertIn(
            "engine_write_runtime_state_only",
            status_logs[-1].payload["report_health_reasons"],
        )
        self.assertGreater(
            status_logs[-1].payload["scene_entity_engine_write_pending_f5_count"],
            0,
        )

