    def test_undeclared_state_patch_is_not_logged_when_failed_state_persist_fails(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        registry.register(
            "mock.asset_only",
            lambda call: ToolResult(
                True,
                "attempted undeclared actor write",
                state_patch=StatePatch(
                    room_id="room-undeclared-persist-fail",
                    changes={"actors": {"actor-1": {"name": "不应出现"}}},
                ),
            ),
            produces_state=("assets",),
        )
        graph = ToolCallGraph(graph_id="graph-undeclared-persist-fail", plan_id="plan-patch-scope")
        graph.add(ToolCall(tool_call_id="tool-asset", tool_name="mock.asset_only"))
        original_apply_patch = state.apply_patch

        def fail_invalid_patch_failed_state(patch: StatePatch) -> tuple[bool, str]:
            graph_fact = dict((patch.changes or {}).get("tool_graphs") or {}).get(graph.graph_id)
            nodes = dict(graph_fact.get("nodes") or {}) if isinstance(graph_fact, dict) else {}
            tool_fact = dict(nodes.get("tool-asset") or {}) if isinstance(nodes.get("tool-asset"), dict) else {}
            if tool_fact.get("status") == "failed":
                return False, "simulated invalid state patch failed persist failure"
            return original_apply_patch(patch)

        state.apply_patch = fail_invalid_patch_failed_state  # type: ignore[method-assign]

        executed = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        ).execute(graph, room_id="room-undeclared-persist-fail")

        self.assertEqual(executed.status, "failed")
        self.assertEqual(executed.nodes["tool-asset"].status, ToolCallStatus.FAILED)
        self.assertEqual(executed.nodes["tool-asset"].error, "invalid state patch state was not persisted")
        self.assertEqual(state.snapshot("room-undeclared-persist-fail")["room"]["actors"], {})
        events = [
            entry.event
            for entry in operation_log.entries()
            if entry.payload.get("graph_id") == graph.graph_id or entry.tool_call_id == "tool-asset"
        ]
        self.assertIn("tool_graph_state_record_failed", events)
        self.assertNotIn("tool_call_invalid_state_patch", events)
        runtime_events = state.snapshot("room-undeclared-persist-fail")["room"]["runtime_events"]
        self.assertFalse([event for event in runtime_events if event["event_type"] == "tool_result_message"])

