    def test_message_action_policy_marks_status_aliases_as_no_plan_creation(self) -> None:
        for action in ("status_query", "gm_summary", "runtime_status", "state_query", "query_runtime_state"):
            policy = AgentRuntime.message_action_policy(action)
            self.assertEqual(policy["category"], "read_only", action)
            self.assertTrue(policy["read_only"], action)
            self.assertFalse(policy["may_create_plan"], action)
            self.assertFalse(policy["requires_existing_plan"], action)

        for action in ("provider_status",):
            policy = AgentRuntime.message_action_policy(action)
            self.assertEqual(policy["category"], "state_write", action)
            self.assertFalse(policy["read_only"], action)
            self.assertFalse(policy["may_create_plan"], action)
            self.assertFalse(policy["requires_existing_plan"], action)

        for action in (
            "intervention_add",
            "post_generation_add_object",
            "modify_object",
            "delete_object",
            "confirm_layout_adjustment",
            "enqueue_pending_interventions",
            "pause_generation",
            "retry_generation",
        ):
            policy = AgentRuntime.message_action_policy(action)
            self.assertEqual(policy["category"], "state_write", action)
            self.assertFalse(policy["read_only"], action)
            self.assertFalse(policy["may_create_plan"], action)
            self.assertTrue(policy["requires_existing_plan"], action)

        for action in ("plan", "plan_supplement"):
            policy = AgentRuntime.message_action_policy(action)
            self.assertEqual(policy["category"], "plan_write", action)
            self.assertTrue(policy["may_create_plan"], action)

        unknown_policy = AgentRuntime.message_action_policy("surprise_legacy_action")
        self.assertEqual(unknown_policy["category"], "unknown")
        self.assertFalse(unknown_policy["read_only"])
        self.assertFalse(unknown_policy["may_create_plan"])
        self.assertFalse(unknown_policy["requires_existing_plan"])

