    def test_requires_existing_plan_with_unknown_external_plan_reports_missing_mapping(self) -> None:
        runtime = AgentRuntime()
        existing = runtime.handle_message(
            room_id="room-requires-missing-external",
            text="璁捐涓€涓棌瀹濆",
            sender_name="房主",
            action="plan_drafting",
            external_plan_id="seed-requires-existing",
        )

        result = runtime.handle_message(
            room_id="room-requires-missing-external",
            text="鍐嶅姞涓€涓ぉ浣块洉鍍?",
            action="intervention_add",
            sender_name="房主",
            external_plan_id="seed-requires-missing",
        )

        room = runtime.query_state("room-requires-missing-external")["room"]
        self.assertTrue(result["handled"])
        self.assertFalse(result["recorded"])
        self.assertIn("no mapped Runtime plan", result["message"])
        self.assertEqual(result["plan"], {})
        self.assertEqual(len(room["scene_plans"]), 1)
        self.assertEqual(room["active_plan_id"], existing["plan"]["plan_id"])
        self.assertEqual(room["pending_interventions"], {})
        self.assertNotIn("鍐嶅姞涓€涓ぉ浣块洉鍍?", str(room["scene_plans"][existing["plan"]["plan_id"]]))
        skipped = runtime.operation_log.query(
            room_id="room-requires-missing-external",
            event="runtime_requires_existing_plan_missing",
            limit=1,
        )
        self.assertTrue(skipped)
        self.assertEqual(skipped[-1].payload["reason"], "no runtime plan")
        self.assertTrue(skipped[-1].payload["missing_external_plan"])
        self.assertEqual(skipped[-1].payload["external_plan_id"], "seed-requires-missing")
        self.assertNotIn("plan_patch_recorded", runtime.operation_log.events())

