        self.assertEqual(status["review_advisory_proposal_summary"]["proposal_count"], 1)
        self.assertEqual(status["review_advisory_proposal_summary"]["item_count"], 1)
        self.assertNotIn(second_batch.batch_id, str(status["review_advisory_proposal_summary"]))

