    def test_scene_review_provider_adapter_respects_status_and_success_failure(self) -> None:
        failed_review_provider = make_scene_review_provider(
            review_tool=lambda payload: {
                "status": "failed",
                "success": True,
                "message": "provider raw url https://internal.example/review api_key=hidden",
                "issues": [{"message": "should not persist"}],
                "advisory_items": [{"message": "should not persist"}],
            },
            output_dir_provider=lambda payload: "C:/tmp/review",
        )
        runtime = AgentRuntime(review_provider=failed_review_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-review-failed-status",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=99, scene_name="Scene/review.scene")

        self.assertEqual(result["graphs"][0]["status"], "failed")
        room = runtime.query_state("room-review-failed-status")["room"]
        self.assertEqual(room["geometry_reviews"], {})
        self.assertNotIn("internal.example", str(result))
        self.assertNotIn("should not persist", str(room))
        events = runtime.user_visible_events("room-review-failed-status")
        self.assertTrue(
            any(
                event["event_type"] == "tool_result_message"
                and event["level"] == "warning"
                and dict(event.get("payload") or {}).get("status") == "failed"
                for event in events
            )
        )

        false_success_provider = make_scene_review_provider(
            review_tool=lambda payload: {
                "success": "false",
                "overall": "PASS",
                "issues": [{"message": "should not persist"}],
            },
            output_dir_provider=lambda payload: "C:/tmp/review",
        )
        runtime = AgentRuntime(review_provider=false_success_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-review-false-success",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=99, scene_name="Scene/review.scene")

        self.assertEqual(result["graphs"][0]["status"], "failed")
        room = runtime.query_state("room-review-false-success")["room"]
        self.assertEqual(room["geometry_reviews"], {})
        self.assertNotIn("should not persist", str(room))

    def test_direct_review_provider_sanitizes_unsafe_visible_text_before_state_patch(self) -> None:
        def unsafe_review_provider(payload: dict[str, Any]) -> dict[str, Any]:
            return {
                "plan_id": payload["plan_id"],
                "batch_id": payload["batch_id"],
                "checkpoint_type": payload["checkpoint_type"],
                "reviewed_targets": payload["reviewed_targets"],
                "status": "needs_adjustment",
                "overall": "WARN",
                "source": "provider raw C:/secret/review prompt=hidden",
                "issues": [
                    {
                        "type": "provider raw C:/secret/type prompt=hidden",
                        "message": "provider raw https://internal.example/review prompt=hidden",
                        "actor_name": "provider raw C:/secret/actor.glb prompt=hidden",
                        "severity": "provider raw C:/secret/severity prompt=hidden",
                    }
                ],
                "advisory_items": [
                    {
                        "type": "provider raw C:/secret/advisory prompt=hidden",
                        "summary": "provider raw https://internal.example/advice prompt=hidden",
                    }
                ],
            }

        runtime = AgentRuntime(review_provider=unsafe_review_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-direct-review-sanitize",
            text="强盗藏宝室，要有金币堆和宝箱",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=99)

        state = runtime.query_state("room-direct-review-sanitize")["room"]
        batch_id = result["batches"][0]["batch_id"]
        review = state["geometry_reviews"][batch_id]
        serialized = str(review)
        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertEqual(review["status"], "needs_adjustment")
        self.assertEqual(review["source"], "review_provider")
        self.assertNotIn("provider raw", serialized.lower())
        self.assertNotIn("internal.example", serialized.lower())
        self.assertNotIn("prompt=hidden", serialized.lower())
        self.assertNotIn("C:/secret", serialized)
        self.assertEqual(review["issues"][0]["type"], "advisory")
        self.assertEqual(review["issues"][0]["message"], "内部细节已隐藏")
        self.assertEqual(review["advisory_items"][0]["summary"], "内部细节已隐藏")

