    def test_review_advisory_proposal_failure_returns_persisted_state_only(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-review-proposal-fail",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            owner_agent="山贼",
        )
        original_apply_patch = runtime.state.apply_patch
        applied, reason = original_apply_patch(
            StatePatch(
                room_id="room-review-proposal-fail",
                changes={
                    "geometry_reviews": {
                        plan.plan_id: {
                            "plan_id": plan.plan_id,
                            "status": "needs_adjustment",
                            "issues": [],
                            "checkpoint_type": "structure_review",
                            "advisory_items": [
                                {
                                    "message": "清出入口",
                                    "target_hint": "入口",
                                    "requires_confirmation": True,
                                }
                            ],
                        }
                    }
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)

        def reject_review_advisory_proposal_patch(patch: StatePatch) -> tuple[bool, str]:
            if "review_advisory_proposals" in patch.changes:
                return False, "simulated review advisory proposal persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_review_advisory_proposal_patch  # type: ignore[method-assign]

        proposal_result = runtime.propose_review_advisories(
            room_id="room-review-proposal-fail",
            plan_id=plan.plan_id,
        )

        self.assertFalse(proposal_result["recorded"])
        self.assertEqual(proposal_result["proposal"], {})
        state = runtime.query_state("room-review-proposal-fail")["room"]
        self.assertEqual(state["review_advisory_proposals"], {})
        events = runtime.operation_log.events()
        self.assertIn("review_advisory_proposal_create_failed", events)
        self.assertNotIn("review_advisory_proposal_created", events)
        visible_events = runtime.user_visible_events("room-review-proposal-fail", plan_id=plan.plan_id)
        self.assertFalse([event for event in visible_events if event["event_type"] == "review_advisory_proposal_ready"])

