    def test_review_advisory_confirmation_failure_returns_persisted_state_only(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-review-confirm-fail",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        proposal = {
            "proposal_id": "review-confirm-fail",
            "plan_id": plan.plan_id,
            "room_id": "room-review-confirm-fail",
            "status": "proposed",
            "source": "review_advisory",
            "risk_level": "advisory",
            "requires_confirmation": True,
            "direct_execution_allowed": False,
            "source_review_ids": ["review-1"],
            "item_count": 1,
            "items": [
                {
                    "item_id": "review-confirm-fail:0",
                    "type": "advisory",
                    "message": "鍏ュ彛闇€瑕佹洿娓呮",
                    "target_hint": "入口",
                    "checkpoint_type": "structure_review",
                    "batch_id": "",
                    "confidence": 0.9,
                    "requires_confirmation": True,
                }
            ],
            "created_at": 1.0,
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-review-confirm-fail",
                changes={"review_advisory_proposals": {plan.plan_id: proposal}},
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)
        original_apply_patch = runtime.state.apply_patch

        def fail_review_confirmation_once(patch: StatePatch) -> tuple[bool, str]:
            if "review_advisory_confirmations" in (patch.changes or {}):
                return False, "simulated review confirmation persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = fail_review_confirmation_once  # type: ignore[method-assign]

        result = runtime.record_review_advisory_confirmation(
            room_id="room-review-confirm-fail",
            plan_id=plan.plan_id,
            proposal_id="review-confirm-fail",
            decision="confirmed",
            confirmed_by="房主",
        )

        self.assertFalse(result["recorded"])
        self.assertEqual(result["confirmation"], {})
        self.assertEqual(result["proposal"]["status"], "proposed")
        state = runtime.query_state("room-review-confirm-fail")["room"]
        self.assertEqual(state["review_advisory_proposals"][plan.plan_id]["status"], "proposed")
        self.assertEqual(state["review_advisory_confirmations"], [])
        events = runtime.operation_log.events()
        self.assertIn("review_advisory_confirmation_record_failed", events)
        self.assertNotIn("review_advisory_confirmation_recorded", events)
        self.assertEqual(
            [
                event
                for event in runtime.user_visible_events("room-review-confirm-fail", plan_id=plan.plan_id)
                if event["event_type"] == "review_advisory_confirmation"
            ],
            [],
        )

