    def test_review_advisory_confirmation_validator_rejects_internal_fields(self) -> None:
        valid_event = {
            "proposal_id": "review-proposal-safe",
            "room_id": "room-review-validator",
            "plan_id": "plan-review-validator",
            "external_plan_id": "seed-review-validator",
            "decision": "confirmed",
            "confirmed_by": "房主",
            "item_count": 1,
            "timestamp": 1.0,
        }
        ReviewAdvisoryConfirmationValidator.validate(valid_event)

        unsafe_event = dict(valid_event)
        unsafe_event["tool_call_id"] = "hidden-tool"
        with self.assertRaisesRegex(ValueError, "review advisory confirmation cannot expose field: tool_call_id"):
            ReviewAdvisoryConfirmationValidator.validate(unsafe_event)

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-review-invalid",
                changes={"review_advisory_confirmations": [unsafe_event]},
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("review advisory confirmation cannot expose field: tool_call_id", reason)

    def test_review_advisory_confirmation_validator_rejects_unsafe_text_values(self) -> None:
        valid_event = {
            "proposal_id": "review-proposal-safe-text",
            "room_id": "room-review-safe-text",
            "plan_id": "plan-review-safe-text",
            "external_plan_id": "seed-review-safe-text",
            "decision": "confirmed",
            "confirmed_by": "房主",
            "item_count": 1,
            "timestamp": 1.0,
        }
        ReviewAdvisoryConfirmationValidator.validate(valid_event)

        unsafe_confirmed_by = dict(valid_event)
        unsafe_confirmed_by["confirmed_by"] = "provider raw C:\\\\secret\\\\review prompt=hidden"
        with self.assertRaisesRegex(ValueError, "review advisory confirmation confirmed_by contains unsafe text"):
            ReviewAdvisoryConfirmationValidator.validate(unsafe_confirmed_by)

        runtime = AgentRuntime()
        unsafe_proposal = dict(valid_event)
        unsafe_proposal["proposal_id"] = "https://internal.example/review"
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-review-unsafe-text",
                changes={"review_advisory_confirmations": [unsafe_proposal]},
                expected_version=runtime.state.version,
            )
        )
        self.assertFalse(applied)
        self.assertIn("review advisory confirmation proposal_id contains unsafe text", reason)

    def test_scene_review_provider_skips_when_screenshot_dir_missing(self) -> None:
        class FakeReviewTool:
            def invoke(self, payload: dict) -> dict:
                raise AssertionError("review tool should not be called without screenshots")

        provider = make_scene_review_provider(review_tool=FakeReviewTool())
        review = provider({
            "plan_id": "plan-review",
            "batch_id": "batch-review",
            "checkpoint_type": "high_risk_object_review",
            "reviewed_targets": ["天使雕像"],
            "contract_version": 3,
        })

        self.assertEqual(review["status"], "skipped")
        self.assertEqual(review["overall"], "SKIPPED")
        self.assertEqual(review["batch_id"], "batch-review")
        self.assertEqual(review["checkpoint_type"], "high_risk_object_review")
        self.assertEqual(review["reviewed_targets"], ["天使雕像"])
        self.assertEqual(review["contract_version"], 3)
        self.assertEqual(review["advisory_items"][0]["reason"], "missing screenshot directory")

    def test_environment_component_provider_adapter_normalizes_component_facts(self) -> None:
        class FakeEnvironmentTool:
            def __init__(self) -> None:
                self.calls: list[dict] = []

            def invoke(self, payload: dict) -> dict:
                self.calls.append(dict(payload))
                return {
                    "component_id": f"component-{payload['object_id']}",
                    "name": "provider-name-should-not-win",
                    "component_type": "provider_type_should_not_win",
                    "handler": "provider_handler_should_not_win",
                    "status": "created",
                    "source": "provider=secret-environment-tool",
                    "scene_name": "Scene/provider-should-not-win.scene",
                    "requires_engine_write": False,
                }

        tool = FakeEnvironmentTool()
        runtime = AgentRuntime(
            environment_component_provider=make_environment_component_provider(environment_tool=tool)
        )
        plan = runtime.propose_scene_plan(
            room_id="room-environment-provider",
            text="做一个森林营地，有天空、草地、小木桌和帐篷",
            owner_agent="长者",
        )
        plan.concrete_object_items = ["天空", "草地", "小木桌", "帐篷"]
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(
            plan.plan_id,
            max_items_per_batch=99,
            scene_name="Scene/environment.scene",
        )

        batch_id = result["batches"][0]["batch_id"]
        state = runtime.query_state("room-environment-provider")["room"]
        components = state["environment_components"][batch_id]
        component_names = {item["name"] for item in components.values()}
        environment_summary = result["report"]["environment_component_summary"]
        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertTrue({"天空", "草地", "森林"}.issubset(component_names))
        self.assertEqual(environment_summary["component_count"], 3)
        self.assertEqual(environment_summary["requested_count"], 3)
        self.assertEqual(environment_summary["ready_count"], 3)
        self.assertEqual(environment_summary["failed_count"], 0)
        self.assertEqual(environment_summary["status_counts"], {"runtime_state_only": 1, "succeeded": 1})
        self.assertTrue(all(
            item["status"] in {"created", "imported", "runtime_state_only"}
            for item in environment_summary["latest_components"]
        ))
        self.assertTrue(all(item["batch_id"] == batch_id for item in environment_summary["latest_components"]))
        self.assertTrue(all(item["batch_index"] == 1 for item in environment_summary["latest_components"]))
        self.assertTrue(all(item["total_batches"] == 1 for item in environment_summary["latest_components"]))
        status_environment_summary = runtime.status_summary(
            "room-environment-provider",
            plan_id=plan.plan_id,
        )["environment_component_summary"]
        self.assertEqual(
            status_environment_summary["latest_components"],
            environment_summary["latest_components"],
        )
        environment_replay = result["report"]["operation_replay_summary"]["environment_component_replay_summary"]
        self.assertEqual(environment_replay["ready_event_count"], 1)
        self.assertEqual(environment_replay["failed_event_count"], 0)
        self.assertEqual(environment_replay["latest_event_type"], "environment_components_imported")
        self.assertEqual(tool.calls[0]["scene_name"], "Scene/environment.scene")
        self.assertEqual(tool.calls[0]["component_type"], "skybox")
        self.assertTrue(next(iter(components.values()))["component_id"].startswith("component-"))
        self.assertTrue(all(
            item["source"] in {
                "environment_component",
                "runtime_default_environment_import",
                "runtime_environment_import",
            }
            for item in components.values()
        ))
        self.assertTrue(all(item["scene_name"] == "Scene/environment.scene" for item in components.values()))
        self.assertNotIn("secret-environment-tool", str(components))
        self.assertNotIn("provider-name-should-not-win", str(components))
        self.assertNotIn("provider_type_should_not_win", str(components))
        self.assertNotIn("provider_handler_should_not_win", str(components))
        self.assertNotIn("provider-should-not-win", str(components))
        self.assertEqual(result["report"]["provider_summary"]["environment_component"]["mode"], "adapter")

    def test_configured_environment_provider_cannot_drop_required_framework(self) -> None:
        runtime = AgentRuntime(environment_component_provider=lambda _payload: {})

        def execute_framework_case(
            *,
            room_id: str,
            batch_id: str,
            environment_type: str,
            required: list[str],
        ) -> dict[str, dict[str, Any]]:
            graph = ToolCallGraph(
                graph_id=f"graph-{batch_id}",
                plan_id=f"plan-{batch_id}",
                batch_id=batch_id,
            )
            graph.add(
                ToolCall(
                    tool_call_id=f"tool-{batch_id}",
                    tool_name="runtime.environment.create_components",
                    args={
                        "room_id": room_id,
                        "plan_id": f"plan-{batch_id}",
                        "batch_id": batch_id,
                        "scene_name": f"Scene/{batch_id}.scene",
                        "environment_type": environment_type,
                        "required_environment_components": required,
                        "substrate_resolutions": [],
                    },
                )
            )
            executor = ToolCallGraphExecutor(
                registry=runtime.registry,
                guard=runtime.guard,
                state=runtime.state,
                operation_log=runtime.operation_log,
            )

            executed = executor.execute(graph, room_id=room_id)

            self.assertEqual(executed.status, "completed")
            return dict(runtime.state.room(room_id)["environment_components"][batch_id])

        indoor = execute_framework_case(
            room_id="room-required-indoor",
            batch_id="batch-required-indoor",
            environment_type="indoor",
            required=["room_box", "room_floor"],
        )
        mixed = execute_framework_case(
            room_id="room-required-mixed",
            batch_id="batch-required-mixed",
            environment_type="mixed",
            required=["terrain", "room_box", "room_floor", "transition_zone"],
        )

        self.assertEqual(
            {row["component_type"] for row in indoor.values()},
            {"room_box", "room_floor"},
        )
        self.assertEqual(
            {row["component_type"] for row in mixed.values()},
            {"terrain", "room_box", "room_floor", "transition_zone"},
        )

    def test_environment_component_summary_uses_batch_scope_for_runtime_events(self) -> None:
        runtime = AgentRuntime()
        first = runtime.propose_scene_plan(
            room_id="room-env-event-batch-only",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            owner_agent="山贼",
        )
        second = runtime.propose_scene_plan(
            room_id="room-env-event-batch-only",
            text="鍋氫竴涓．鏋楄惀鍦帮紝鏈夊ぉ绌哄拰鑽夊湴",
            owner_agent="闀胯€?",
        )
        runtime.confirm_scene_plan(first.plan_id, confirmed_by="房主")
        runtime.confirm_scene_plan(second.plan_id, confirmed_by="房主")
        first_batch = runtime.plan_batches(first.plan_id, max_items_per_batch=2)[0]
        second_batch = runtime.plan_batches(second.plan_id, max_items_per_batch=2)[0]
        ok, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-env-event-batch-only",
                changes={
                    "runtime_events": [
                        {
                            "event_id": "evt-env-first-batch-only",
                            "room_id": "room-env-event-batch-only",
                            "batch_id": first_batch.batch_id,
                            "event_type": "environment_components_ready",
                            "phase": "environment",
                            "audience": "host",
                            "level": "success",
                            "title": "鐜缁勪欢瀹屾垚",
                            "message": "钘忓疂瀹ょ幆澧冪粍浠跺凡鍑嗗銆?",
                            "payload": {
                                "status": "succeeded",
                                "requested_count": 2,
                                "component_count": 2,
                                "failed_count": 0,
                                "batch_index": 1,
                                "total_batches": 1,
                            },
                            "timestamp": 10.0,
                        },
                        {
                            "event_id": "evt-env-second-batch-only",
                            "room_id": "room-env-event-batch-only",
                            "batch_id": second_batch.batch_id,
                            "event_type": "environment_components_failed",
                            "phase": "environment",
                            "audience": "host",
                            "level": "warning",
                            "title": "鐜缁勪欢澶辫触",
                            "message": "妫灄钀ュ湴鐜缁勪欢澶辫触銆?",
                            "payload": {
                                "status": "failed",
                                "requested_count": 3,
                                "component_count": 0,
                                "failed_count": 3,
                                "batch_index": 1,
                                "total_batches": 1,
                            },
                            "timestamp": 20.0,
                        },
                    ]
                },
            )
        )
        self.assertTrue(ok, reason)

        summary = runtime.status_summary(
            "room-env-event-batch-only",
            plan_id=first.plan_id,
        )["environment_component_summary"]

        self.assertEqual(summary["event_count"], 1)
        self.assertEqual(summary["requested_count"], 2)
        self.assertEqual(summary["ready_count"], 2)
        self.assertEqual(summary["failed_count"], 0)
        self.assertEqual(summary["status_counts"], {"succeeded": 1})
        self.assertEqual(summary["latest_events"][0]["batch_id"], first_batch.batch_id)
        self.assertNotIn(second_batch.batch_id, str(summary))
        self.assertNotIn("failed", summary["status_counts"])

