    def test_environment_component_provider_sanitizes_tool_result_fields(self) -> None:
        class UnsafeEnvironmentTool:
            def invoke(self, payload: dict) -> dict:
                return {
                    "component_id": "provider raw C:\\secret\\env",
                    "actor_id": "https://internal.example/env",
                    "name": "provider raw https://internal.example/env",
                    "component_type": "terrain/component",
                    "handler": "prompt=hidden",
                    "status": "raw=secret",
                    "scene_name": "provider raw C:\\secret\\scene.scene",
                    "requires_engine_write": False,
                    "metadata": {"hidden": True},
                }

        provider = make_environment_component_provider(environment_tool=UnsafeEnvironmentTool())
        components = provider({
            "room_id": "room-env-safe",
            "plan_id": "plan-env-safe",
            "batch_id": "batch-env-safe",
            "scene_name": "Scene/safe.scene",
            "substrate_resolutions": [
                {
                    "name": "鐭虫澘璺?",
                    "component_type": "terrain",
                    "handler": "terrain_component",
                    "requires_engine_write": False,
                }
            ],
        })

        component = next(iter(components.values()))
        EnvironmentComponentValidator.validate(component)
        self.assertEqual(component["component_id"], "plan-env-safe-env-01")
        self.assertEqual(component["name"], "鐭虫澘璺?")
        self.assertEqual(component["component_type"], "terrain")
        self.assertEqual(component["handler"], "terrain_component")
        self.assertEqual(component["status"], "created")
        self.assertEqual(component["scene_name"], "Scene/safe.scene")
        self.assertFalse(component["requires_engine_write"])
        serialized = str(component).lower()
        self.assertNotIn("provider", serialized)
        self.assertNotIn("raw", serialized)
        self.assertNotIn("secret", serialized)
        self.assertNotIn("internal.example", serialized)

