    def test_environment_component_validator_rejects_control_plane_fields(self) -> None:
        valid_components = {
            "batch-env": {
                "component-1": {
                    "actor_id": "actor-env-1",
                    "component_id": "component-1",
                    "name": "天空",
                    "component_type": "skybox",
                    "handler": "skybox",
                    "status": "planned",
                    "source": "runtime_environment_component",
                    "scene_name": "Scene/environment.scene",
                    "requires_engine_write": False,
                    "render_status_observed": True,
                    "render_ready": True,
                    "render_failed": False,
                    "gpu_build_state": "ready",
                    "grounding_status": "not_applicable",
                    "mesh_count": 2,
                    "renderable_mesh_count": 2,
                    "invalid_mesh_count": 0,
                }
            }
        }
        EnvironmentComponentValidator.validate_component_batches(valid_components)

        invalid_render_components = {
            "batch-env": {
                "component-1": {
                    **valid_components["batch-env"]["component-1"],
                    "render_ready": "yes",
                }
            }
        }
        with self.assertRaisesRegex(ValueError, "render_ready must be a bool"):
            EnvironmentComponentValidator.validate_component_batches(invalid_render_components)

        invalid_mesh_components = {
            "batch-env": {
                "component-1": {
                    **valid_components["batch-env"]["component-1"],
                    "mesh_count": -1,
                }
            }
        }
        with self.assertRaisesRegex(ValueError, "mesh_count must be a non-negative integer"):
            EnvironmentComponentValidator.validate_component_batches(invalid_mesh_components)

        invalid_grounding_components = {
            "batch-env": {
                "component-1": {
                    **valid_components["batch-env"]["component-1"],
                    "grounding_status": "floating_somewhere",
                }
            }
        }
        with self.assertRaisesRegex(ValueError, "grounding_status is invalid"):
            EnvironmentComponentValidator.validate_component_batches(invalid_grounding_components)

        unsafe_components = {
            "batch-env": {
                "component-1": {
                    **valid_components["batch-env"]["component-1"],
                    "provider": "hidden-environment-provider",
                }
            }
        }
        with self.assertRaisesRegex(ValueError, "environment component fact cannot expose field: provider"):
            EnvironmentComponentValidator.validate_component_batches(unsafe_components)

        unsafe_text_components = {
            "batch-env": {
                "component-1": {
                    **valid_components["batch-env"]["component-1"],
                    "name": "provider raw C:\\secret\\env",
                }
            }
        }
        with self.assertRaisesRegex(ValueError, "environment component fact name exposes unsafe internal text"):
            EnvironmentComponentValidator.validate_component_batches(unsafe_text_components)

        unsafe_batch_key_components = {
            "https://internal.example/batch": valid_components["batch-env"],
        }
        with self.assertRaisesRegex(ValueError, "environment component fact batch id exposes unsafe internal text"):
            EnvironmentComponentValidator.validate_component_batches(unsafe_batch_key_components)

        unsafe_component_key_components = {
            "batch-env": {
                "C:\\\\secret\\\\component": valid_components["batch-env"]["component-1"],
            }
        }
        with self.assertRaisesRegex(ValueError, "environment component fact component key exposes unsafe internal text"):
            EnvironmentComponentValidator.validate_component_batches(unsafe_component_key_components)

        unsafe_component_type = {
            "batch-env": {
                "component-1": {
                    **valid_components["batch-env"]["component-1"],
                    "component_type": "provider_raw",
                }
            }
        }
        with self.assertRaisesRegex(ValueError, "environment component fact component_type exposes unsafe internal text"):
            EnvironmentComponentValidator.validate_component_batches(unsafe_component_type)

        runtime = AgentRuntime()
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-environment-invalid",
                changes={"environment_components": unsafe_components},
                expected_version=runtime.state.version,
            )
        )

        self.assertFalse(applied)
        self.assertIn("environment component fact cannot expose field: provider", reason)

    def test_legacy_model_provider_adapter_normalizes_acquire_results(self) -> None:
        class FakeAcquireResult:
            def __init__(self, name: str) -> None:
                self.success = True
                self.local_path = f"E:/models/{name}.glb"
                self.source = "generation"
                self.preview_images = [f"E:/previews/{name}.png"]
                self.metadata = {"provider_job": f"job-{name}"}

        class FakeModelProvider:
            def __init__(self) -> None:
                self.calls: list[dict] = []

            def acquire(self, name: str, image_url: str = "", prompt_text: str = "", object_id: str = "") -> FakeAcquireResult:
                self.calls.append(
                    {
                        "name": name,
                        "image_url": image_url,
                        "prompt_text": prompt_text,
                        "object_id": object_id,
                    }
                )
                return FakeAcquireResult(name)

        fake_provider = FakeModelProvider()
        model_resource_provider = make_legacy_model_resource_provider(lambda: fake_provider)
        direct_resources = model_resource_provider({
            "batch_id": "batch-direct",
            "model_items": ["搴?"],
        })
        self.assertNotIn("provider", direct_resources["搴?"])
        self.assertNotIn("metadata", direct_resources["搴?"])
        self.assertEqual(direct_resources["搴?"]["source"], "generation")

        class UnsafeSourceResult(FakeAcquireResult):
            def __init__(self, name: str) -> None:
                super().__init__(name)
                self.source = "provider=secret-model-source"

        class UnsafeSourceProvider(FakeModelProvider):
            def acquire(self, name: str, image_url: str = "", prompt_text: str = "", object_id: str = "") -> UnsafeSourceResult:
                return UnsafeSourceResult(name)

        unsafe_model_resource_provider = make_legacy_model_resource_provider(lambda: UnsafeSourceProvider())
        unsafe_resources = unsafe_model_resource_provider({
            "batch_id": "batch-unsafe-source",
            "model_items": ["搴?"],
        })
        self.assertEqual(unsafe_resources["搴?"]["source"], "legacy_model")
        self.assertNotIn("secret-model-source", str(unsafe_resources))
        runtime = AgentRuntime(model_resource_provider=model_resource_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-legacy-provider",
            text="鍋氫竴涓彲鐖卞崸瀹わ紝鏈夊簥鍜屽彴鐏?",
            owner_agent="灏忓コ瀛?",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        batch_id = result["batches"][0]["batch_id"]
        state = runtime.query_state("room-legacy-provider")["room"]
        model_resources = state["model_resource_plans"][batch_id]
        self.assertEqual(result["graphs"][0]["status"], "completed")
        first_model_name = next(iter(model_resources))
        self.assertEqual(model_resources[first_model_name]["status"], "ready")
        self.assertEqual(model_resources[first_model_name]["local_path"], f"E:/models/{first_model_name}.glb")
        self.assertEqual(model_resources[first_model_name]["source"], "generation")
        self.assertNotIn("provider", model_resources[first_model_name])
        self.assertNotIn("metadata", model_resources[first_model_name])
        priority_fact = state["custom_batch_facts"][f"{plan.plan_id}:item_priorities"]
        self.assertEqual(
            [call["name"] for call in fake_provider.calls[-len(priority_fact["ordered_items"]):]],
            priority_fact["ordered_items"],
        )

    def test_legacy_model_provider_adapter_coerces_success_flag(self) -> None:
        class StringFalseAcquireResult:
            success = "false"
            local_path = "E:/models/should-not-be-ready.glb"
            source = "generation"

        class StringFalseProvider:
            def acquire(self, *args, **kwargs):  # noqa: ANN002, ANN003, ANN201
                return StringFalseAcquireResult()

        string_false_provider = make_legacy_model_resource_provider(lambda: StringFalseProvider())
        string_false_resources = string_false_provider({"batch_id": "batch-model-bool", "model_items": ["钘忓疂绠?"]})
        self.assertEqual(string_false_resources["钘忓疂绠?"]["status"], "failed")
        self.assertNotIn("should-not-be-ready", str(string_false_resources))

        class NumericZeroAcquireResult:
            success = 0
            local_path = "E:/models/should-not-be-ready.glb"
            source = "generation"

        class NumericZeroProvider:
            def acquire(self, *args, **kwargs):  # noqa: ANN002, ANN003, ANN201
                return NumericZeroAcquireResult()

        numeric_zero_provider = make_legacy_model_resource_provider(lambda: NumericZeroProvider())
        numeric_zero_resources = numeric_zero_provider({"batch_id": "batch-model-bool", "model_items": ["閲戝竵鍫?"]})
        self.assertEqual(numeric_zero_resources["閲戝竵鍫?"]["status"], "failed")
        self.assertNotIn("should-not-be-ready", str(numeric_zero_resources))

        class StringTrueAcquireResult:
            success = "true"
            local_path = "E:/models/chest.glb"
            source = "generation"
