    def test_legacy_model_provider_item_failure_persists_failed_fact_and_imports_ready_items(self) -> None:
        failed_objects: list[str] = []

        class AcquireResult:
            def __init__(self, *, name: str, success: bool) -> None:
                self.success = success
                self.local_path = f"E:/models/{name}.glb" if success else ""
                self.source = "legacy_model_provider"
                self.preview_images: list[str] = []
                self.error = "provider raw url https://internal.example/model api_key=hidden"
                self.metadata: dict = {}

        class PartialModelProvider:
            def acquire(self, name: str, image_url: str = "", prompt_text: str = "", object_id: str = "") -> AcquireResult:
                if not failed_objects:
                    failed_objects.append(name)
                    return AcquireResult(name=name, success=False)
                return AcquireResult(name=name, success=True)

        runtime = AgentRuntime(
            model_resource_provider=make_legacy_model_resource_provider(lambda: PartialModelProvider())
        )
        plan = runtime.propose_scene_plan(
            room_id="room-legacy-provider-partial",
            text="鍋氫竴涓彲鐖卞崸瀹わ紝鏈夊簥鍜屽彴鐏?",
            owner_agent="灏忓コ瀛?",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        batch_id = result["batches"][0]["batch_id"]
        state = runtime.query_state("room-legacy-provider-partial")["room"]
        model_resources = state["model_resource_plans"][batch_id]
        self.assertEqual(len(failed_objects), 1)
        self.assertEqual(model_resources[failed_objects[0]]["status"], "failed")
        statuses = [resource.get("status") for resource in model_resources.values()]
        self.assertEqual(statuses.count("failed"), 1)
        self.assertEqual(statuses.count("ready"), 1)
        self.assertNotIn("provider raw", str(model_resources))
        self.assertNotIn("https://internal.example", str(model_resources))
        self.assertNotIn("api_key", str(model_resources))
        batch_actors = [
            actor
            for actor in state["actors"].values()
            if actor.get("batch_id") == batch_id
        ]
        self.assertEqual(len(batch_actors), 1)
        events = runtime.user_visible_events("room-legacy-provider-partial", plan_id=plan.plan_id)
        model_events = [event for event in events if event["event_type"] == "model_resources_ready"]
        self.assertTrue(model_events)
        self.assertEqual(model_events[0]["level"], "warning")
        self.assertEqual(model_events[0]["payload"]["requested_count"], 2)
        self.assertEqual(model_events[0]["payload"]["item_count"], 1)
        self.assertEqual(model_events[0]["payload"]["failed_count"], 1)

