    def test_engine_actor_import_provider_uses_gate_and_returns_actor_facts(self) -> None:
        class FakeGate:
            def __init__(self) -> None:
                self.calls: list[dict] = []

            def invoke_tool(self, tool, payload: dict) -> dict:
                self.calls.append(dict(payload))
                return tool.invoke(payload)

        class FakeImportTool:
            def invoke(self, payload: dict) -> dict:
                return {
                    "status": "success",
                    "asset_id": "temporary-object-id",
                    "model_ref": "temporary-model-ref",
                    "actor_name": "native-safe-but-wrong-name",
                    "model_path": payload["model_path"],
                    "scene": "Scene/native-old.scene",
                    "actor": {
                        "name": "native-safe-but-wrong-name",
                        "actor_guid": f"guid-{payload['actor_name']}",
                        "version": 9,
                        "scene_name": "Scene/native-old.scene",
                        "geometry": {
                            "position": payload["position"],
                            "rotation": payload["rotation"],
                            "scale": payload["scale"],
                            "aabb": [-0.5, 0.0, -0.5, 0.5, 1.0, 0.5],
                        },
                    },
                }

        gate = FakeGate()
        provider = make_engine_actor_import_provider(import_tool=FakeImportTool(), engine_gate=gate, scene_name="Scene/场景1.scene")
        result = provider(
            {
                "batch_id": "batch-1",
                "plan_id": "plan-1",
                "scene_version": 7,
                "model_items": ["钘忓疂绠?"],
                "model_resources": {
                    "钘忓疂绠?": {
                        "status": "ready",
                        "local_path": "E:/models/chest.glb",
                        "model_request_id": "model-request-chest",
                    }
                },
                "placements": {"钘忓疂绠?": {"position": [1, 0, 2], "rotation": [0, 90, 0], "scale": [1.2, 1.2, 1.2]}},
            }
        )
        actors = result["actors"]

        self.assertEqual(len(gate.calls), 1)
        self.assertEqual(gate.calls[0]["model_path"], "E:/models/chest.glb")
        self.assertEqual(gate.calls[0]["scene_name"], "Scene/场景1.scene")
        self.assertEqual(gate.calls[0]["plan_id"], "plan-1")
        self.assertEqual(gate.calls[0]["batch_id"], "batch-1")
        self.assertEqual(gate.calls[0]["source_scene_version"], 7)
        self.assertEqual(gate.calls[0]["asset_id"], "model-request-chest")
        self.assertEqual(gate.calls[0]["model_ref"], "model-request-chest")
        self.assertEqual(gate.calls[0]["object_id"], "batch-1-01")
        self.assertTrue(str(gate.calls[0]["actor_guid"]).startswith("runtime-actor-"))
        self.assertTrue(gate.calls[0]["skip_if_exists"])
        self.assertFalse(gate.calls[0]["update_if_exists"])
        replay_result = provider(
            {
                "batch_id": "batch-1",
                "plan_id": "plan-1",
                "model_items": ["钘忓疂绠?"],
                "model_resources": {
                    "钘忓疂绠?": {
                        "status": "ready",
                        "local_path": "E:/models/chest.glb",
                        "model_request_id": "model-request-chest",
                    }
                },
                "placements": {"钘忓疂绠?": {"position": [1, 0, 2]}},
            }
        )
        self.assertEqual(gate.calls[1]["actor_guid"], gate.calls[0]["actor_guid"])
        self.assertEqual(set(replay_result["actors"]), set(actors))
        actor_fact = next(iter(actors.values()))
        self.assertEqual(actor_fact["actor_version"], 9)
        self.assertTrue(actor_fact["entity_id"].startswith("entity-"))
        self.assertEqual(actor_fact["entity_id"], next(iter(replay_result["actors"].values()))["entity_id"])
        self.assertEqual(actor_fact["actor_request_id"], "batch-1-01")
        self.assertIn("guid-钘忓疂绠?", actors)
        self.assertEqual(actors["guid-钘忓疂绠?"]["source"], "engine_import")
        self.assertEqual(actors["guid-钘忓疂绠?"]["name"], "native-safe-but-wrong-name")
        self.assertEqual(actors["guid-钘忓疂绠?"]["asset_id"], "model-request-chest")
        self.assertEqual(actors["guid-钘忓疂绠?"]["model_ref"], "model-request-chest")
        self.assertEqual(actors["guid-钘忓疂绠?"]["scene_name"], "Scene/场景1.scene")
        self.assertEqual(actors["guid-钘忓疂绠?"]["position"], [1, 0, 2])
        self.assertEqual(actors["guid-钘忓疂绠?"]["aabb"]["min"], [-0.5, 0.0, -0.5])
        self.assertEqual(actors["guid-钘忓疂绠?"]["aabb"]["max"], [0.5, 1.0, 0.5])
        import_result = result["import_results"][0]
        self.assertEqual(import_result["actor_id"], next(iter(actors)))
        self.assertEqual(import_result["actor_name"], "native-safe-but-wrong-name")
        self.assertEqual(import_result["native_name"], "native-safe-but-wrong-name")
        self.assertIn(import_result["requested_name"], import_result["aliases"])
        self.assertIn("native-safe-but-wrong-name", import_result["aliases"])
        self.assertNotIn("native-old.scene", str(actors))
        self.assertNotIn("engine_result", actors["guid-钘忓疂绠?"])
        self.assertNotEqual(actors["guid-钘忓疂绠?"]["model_ref"], "E:/models/chest.glb")
        ActorFactValidator.validate_actor_map(actors)

