    def test_engine_actor_import_provider_unwraps_quasar_tool_envelope(self) -> None:
        import json

        class FakeGate:
            def invoke_tool(self, tool, payload: dict) -> str:
                return tool.invoke(payload)

        class EnvelopeImportTool:
            def invoke(self, payload: dict) -> str:
                result = {
                    "status": "success",
                    "actor_name": payload["actor_name"],
                    "model_path": payload["model_path"],
                    "scene": payload.get("scene_name", ""),
                    "actor": {
                        "name": payload["actor_name"],
                        "actor_guid": "guid-envelope",
                        "geometry": {"position": payload["position"]},
                    },
                }
                envelope = {
                    "error_code": 0,
                    "status_info": "success",
                    "llm_content": [
                        {
                            "role": "tools",
                            "interface_type": "scene",
                            "part": [{"content_type": "text", "content_text": json.dumps(result, ensure_ascii=False)}],
                        }
                    ],
                }
                return json.dumps(envelope, ensure_ascii=False)

