    def test_engine_layout_transform_provider_keeps_partial_success_when_one_actor_fails(self) -> None:
        class FakeGate:
            def set_transform(self, tool, payload: dict) -> dict:
                return tool.invoke(payload)

        class PartiallyFailingTransformTool:
            def invoke(self, payload: dict) -> dict:
                if payload["actor_name"] == "bad-box":
                    return {
                        "status": "error",
                        "message": "provider raw path C:/secret/native-transform",
                    }
                return {
                    "status": "success",
                    "actor": payload["actor_name"],
                    "position": list(payload["position"]),
                }

        provider = make_engine_layout_transform_provider(
            transform_tool=PartiallyFailingTransformTool(),
            engine_gate=FakeGate(),
            scene_name="Scene/test.scene",
        )
        result = provider(
            {
                "applied_deltas": [
                    {
                        "actor_id": "actor-good",
                        "actor_name": "good-box",
                        "position": [1.0, 0.0, 2.0],
                    },
                    {
                        "actor_id": "actor-bad",
                        "actor_name": "bad-box",
                        "position": [3.0, 0.0, 4.0],
                    },
                ],
                "actors": {
                    "actor-good": {
                        "actor_id": "actor-good",
                        "name": "good-box",
                        "position": [1.0, 0.0, 2.0],
                    },
                    "actor-bad": {
                        "actor_id": "actor-bad",
                        "name": "bad-box",
                        "position": [3.0, 0.0, 4.0],
                    },
                },
            }
        )

        self.assertEqual(set(result["actor_updates"]), {"actor-good"})
        self.assertEqual(result["actor_updates"]["actor-good"]["position"], [1.0, 0.0, 2.0])
        statuses = {item["actor_id"]: item["status"] for item in result["transform_results"]}
        self.assertEqual(statuses["actor-good"], "success")
        self.assertEqual(statuses["actor-bad"], "failed")
        serialized = str(result)
        self.assertNotIn("provider raw", serialized)
        self.assertNotIn("native-transform", serialized)

    def test_runtime_layout_adjustment_can_call_engine_transform_provider(self) -> None:
        provider_calls: list[dict] = []

        def transform_provider(payload: dict) -> dict:
            provider_calls.append(dict(payload))
            actor_id = payload["applied_deltas"][0]["actor_id"]
            return {
                "actor_updates": {
                    actor_id: {
                        "source": "engine_transform",
                        "position": [2.0, 0.0, 3.0],
                    }
                },
                "transform_results": [{"actor_id": actor_id, "status": "success"}],
            }

        runtime = AgentRuntime(layout_transform_provider=transform_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-transform-runtime",
            text="build a room with a box",
            owner_agent="merchant",
        )
        plan.scene_name = "Scene/transform.scene"
        plan_state = plan.as_dict()
        plan_state["scene_name"] = "Scene/transform.scene"
        runtime.state.apply_patch(
            StatePatch(
                room_id="room-transform-runtime",
                changes={
                    "scene_plans": {plan.plan_id: plan_state},
                    "actors": {
                        "actor-box": {
                            "actor_id": "actor-box",
                            "name": "box",
                            "position": [5.0, 0.3, 3.0],
                            "plan_id": plan.plan_id,
                        }
                    },
                    "layout_adjustment_proposals": {
                        plan.plan_id: {
                            "proposal_id": f"layout-{plan.plan_id}",
                            "plan_id": plan.plan_id,
                            "status": "proposed",
                            "risk_level": "low",
                            "deltas": [
                                {
                                    "op": "move",
                                    "actor_name": "box",
                                    "position_patch": {"x": 2.0, "y": 0.0, "z": 3.0},
                                    "risk_level": "low",
                                }
                            ],
                        }
                    },
                },
                expected_version=runtime.state.version,
            )
        )

        runtime.confirm_layout_adjustment(room_id="room-transform-runtime", plan_id=plan.plan_id)

        self.assertEqual(len(provider_calls), 1)
        self.assertEqual(provider_calls[0]["scene_name"], "Scene/transform.scene")
        room = runtime.query_state("room-transform-runtime")["room"]
        self.assertEqual(room["actors"]["actor-box"]["source"], "engine_transform")
        self.assertEqual(room["actors"]["actor-box"]["position"], [2.0, 0.0, 3.0])
        self.assertEqual(room["actors"]["actor-box"]["scene_name"], "Scene/transform.scene")
        proposal = room["layout_adjustment_proposals"][plan.plan_id]
        self.assertEqual(proposal["engine_transform_results"][0]["status"], "success")

