    def test_runtime_actor_import_persists_partial_success_from_engine_provider(self) -> None:
        class FakeGate:
            def invoke_tool(self, tool, payload: dict) -> dict:
                return tool.invoke(payload)

        class PartiallyFailingImportTool:
            def invoke(self, payload: dict) -> dict:
                if payload["actor_name"] == "閲戝竵鍫?":
                    return {
                        "status": "error",
                        "message": "provider raw path C:/secret/import",
                    }
                return {
                    "status": "success",
                    "actor_name": payload["actor_name"],
                    "actor": {
                        "actor_guid": "guid-chest",
                        "name": payload["actor_name"],
                        "geometry": {"position": payload["position"]},
                    },
                }

        def ready_model_provider(payload: dict) -> dict:
            return {
                name: {
                    "name": name,
                    "status": "ready",
                    "local_path": f"E:/models/{name}.glb",
                }
                for name in payload["model_items"]
            }

        runtime = AgentRuntime(
            model_resource_provider=ready_model_provider,
            actor_import_provider=make_engine_actor_import_provider(
                import_tool=PartiallyFailingImportTool(),
                engine_gate=FakeGate(),
            ),
        )
        plan = runtime.propose_scene_plan(
            room_id="room-import-partial",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        plan.concrete_object_items = ["钘忓疂绠?", "閲戝竵鍫?"]
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        state = runtime.query_state("room-import-partial")["room"]
        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertIn("guid-chest", state["actors"])
        actor_names = {actor["name"] for actor in state["actors"].values()}
        self.assertEqual(actor_names, {"钘忓疂绠?"})
        import_nodes = [
            node
            for node in result["graphs"][0]["nodes"].values()
            if node["tool_name"] == "runtime.actor.import_batch"
        ]
        self.assertTrue(import_nodes)
        self.assertEqual(import_nodes[0]["status"], "succeeded")
        import_log_entries = [
            entry
            for entry in runtime.operation_log.query(event="tool_call_succeeded")
            if "import_results" in entry.payload
        ]
        self.assertTrue(import_log_entries)
        payload = import_log_entries[-1].payload
        failed_import_name = next(
            item["actor_name"]
            for item in payload["import_results"]
            if item["status"] == "failed"
        )
        self.assertEqual(
            {item["actor_name"]: item["status"] for item in payload["import_results"]},
            {"钘忓疂绠?": "success", "閲戝竵鍫?": "failed"},
        )
        self.assertNotIn("provider raw", str(payload))
        self.assertNotIn("secret", str(payload))
        replay = runtime.operation_replay(room_id="room-import-partial", plan_id=plan.plan_id)
        engine_summary = replay["engine_write_summary"]
        self.assertEqual(engine_summary["import_result_count"], 2)
        self.assertEqual(engine_summary["import_status_counts"], {"failed": 1, "success": 1})
        self.assertEqual(engine_summary["transform_result_count"], 0)
        self.assertEqual(
            {item["actor_name"]: item["status"] for item in engine_summary["latest_import_results"]},
            {"钘忓疂绠?": "success", "閲戝竵鍫?": "failed"},
        )
        self.assertNotIn("provider raw", str(engine_summary))
        self.assertNotIn("secret", str(engine_summary))
        events = runtime.user_visible_events("room-import-partial", plan_id=plan.plan_id)
        import_events = [event for event in events if event["event_type"] == "actors_imported"]
        self.assertTrue(import_events)
        self.assertEqual(
            import_events[0]["payload"],
            {
                "actor_count": 1,
                "batch_index": 1,
                "failed_count": 1,
                "imported_count": 1,
                "import_failure_code_counts": {"cpp_actor_import_failed": 1},
                "requested_count": 2,
                "status": "partial",
                "total_batches": 1,
            },
        )
        import_messages = [
            event
            for event in events
            if event["event_type"] == "tool_result_message"
            and str(event.get("message") or "").startswith("场景导入部分完成")
        ]
        self.assertTrue(import_messages)
        self.assertTrue(str(import_messages[-1].get("message") or ""))
        self.assertEqual(import_messages[-1]["level"], "warning")
        self.assertEqual(import_messages[-1]["title"], "执行步骤需要处理")
        self.assertEqual(
            import_messages[-1]["payload"],
            {
                "failed_count": 1,
                "imported_count": 1,
                "requested_count": 2,
                "status": "partial",
            },
        )
        self.assertNotIn("model_path", str(import_messages[-1]))
        self.assertNotIn("provider raw", str(import_messages[-1]))
        self.assertNotIn("secret", str(import_messages[-1]))
        expected_import_summary = {
            "event_count": 1,
            "failed_count": 1,
            "imported_count": 1,
            "import_failure_code_counts": {"cpp_actor_import_failed": 1},
            "latest_events": [
                {
                    "actor_count": 1,
                    "batch_id": result["batches"][0]["batch_id"],
                    "batch_index": 1,
                    "failed_count": 1,
                    "requested_count": 2,
                    "status": "partial",
                    "total_batches": 1,
                }
            ],
            "requested_count": 2,
            "status_counts": {"partial": 1},
        }
        self.assertEqual(result["report"]["import_summary"], expected_import_summary)
        status_summary = runtime.status_summary("room-import-partial", plan_id=plan.plan_id)
        self.assertEqual(
            status_summary["import_summary"],
            expected_import_summary,
        )
        self.assertEqual(status_summary["engine_write_summary"]["import_result_count"], 2)
        self.assertEqual(status_summary["engine_write_summary"]["import_status_counts"], {"failed": 1, "success": 1})
        report_registry = result["report"]["scene_entity_registry"]
        self.assertEqual(report_registry["actor_count"], 1)
        self.assertEqual(report_registry["readiness_status"], "partial")
        self.assertEqual(report_registry["failed_actor_request_count"], 1)
        self.assertEqual(report_registry["failed_actor_requests"][0]["status"], "failed")
        self.assertEqual(report_registry["failed_actor_requests"][0]["actor_name"], failed_import_name)
        self.assertEqual(report_registry["failed_actor_requests"][0]["failure_code"], "cpp_actor_import_failed")
        self.assertNotIn("actor_id", report_registry["failed_actor_requests"][0])
        self.assertNotIn("provider raw", str(report_registry))
        self.assertNotIn("secret", str(report_registry))
        status_registry = status_summary["scene_entity_registry"]
        self.assertEqual(status_registry["failed_actor_request_count"], 1)
        self.assertEqual(status_registry["failed_actor_requests"], report_registry["failed_actor_requests"])
        self.assertEqual(result["report"]["report_health_summary"]["actor_registry_failed_request_count"], 1)
        self.assertIn(
            "actor_registry_failed_request",
            result["report"]["report_health_summary"]["reasons"],
        )
        report_pending_events = [event for event in events if event["event_type"] == "report_pending"]
        self.assertTrue(report_pending_events)
        self.assertEqual(report_pending_events[-1]["payload"]["requested_count"], 2)
        self.assertEqual(report_pending_events[-1]["payload"]["imported_count"], 1)
        self.assertEqual(report_pending_events[-1]["payload"]["failed_count"], 1)
        self.assertEqual(report_pending_events[-1]["payload"]["actor_registry_failed_request_count"], 1)

