    def test_resource_and_import_summaries_use_batch_scope_when_plan_id_is_missing(self) -> None:
        runtime = AgentRuntime()
        first_plan = runtime.propose_scene_plan(
            room_id="room-resource-import-batch-only",
            text="鍋氫竴涓棌瀹濆锛屾湁瀹濈鍜岀伀鎶?",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(first_plan.plan_id, confirmed_by="房主")
        runtime.plan_batches(first_plan.plan_id, max_items_per_batch=2)
        second_plan = runtime.propose_scene_plan(
            room_id="room-resource-import-batch-only",
            text="鍋氫竴涓．鏋楄惀鍦帮紝鏈夊笎绡峰拰鏈ㄦ",
            owner_agent="闀胯€?",
        )
        runtime.confirm_scene_plan(second_plan.plan_id, confirmed_by="房主")
        runtime.plan_batches(second_plan.plan_id, max_items_per_batch=2)
        room = runtime.query_state("room-resource-import-batch-only")["room"]
        first_batch_id = next(
            str(batch.get("batch_id") or "")
            for batch in room["batch_plans"].values()
            if batch.get("plan_id") == first_plan.plan_id
        )
        second_batch_id = next(
            str(batch.get("batch_id") or "")
            for batch in room["batch_plans"].values()
            if batch.get("plan_id") == second_plan.plan_id
        )

        ok, reason = runtime.state.apply_patch(StatePatch(
            room_id="room-resource-import-batch-only",
            changes={
                "runtime_events": [
                    {
                        "event_id": "evt-resource-first-image",
                        "room_id": "room-resource-import-batch-only",
                        "batch_id": first_batch_id,
                        "event_type": "image_resources_ready",
                        "title": "鍥剧墖璧勬簮宸插噯澶?",
                        "message": "鍥剧墖璧勬簮宸插噯澶?",
                        "audience": "host",
                        "level": "info",
                        "timestamp": 1.0,
                        "payload": {
                            "status": "succeeded",
                            "item_count": 2,
                            "requested_count": 2,
                            "failed_count": 0,
                            "batch_index": 1,
                            "total_batches": 1,
                        },
                    },
                    {
                        "event_id": "evt-resource-first-import",
                        "room_id": "room-resource-import-batch-only",
                        "batch_id": first_batch_id,
                        "event_type": "actors_imported",
                        "title": "导入完成",
                        "message": "导入完成",
                        "audience": "host",
                        "level": "info",
                        "timestamp": 2.0,
                        "payload": {
                            "status": "succeeded",
                            "actor_count": 2,
                            "requested_count": 2,
                            "failed_count": 0,
                            "batch_index": 1,
                            "total_batches": 1,
                        },
                    },
                    {
                        "event_id": "evt-resource-second-model",
                        "room_id": "room-resource-import-batch-only",
                        "batch_id": second_batch_id,
                        "event_type": "model_resources_failed",
                        "title": "妯″瀷璧勬簮鍑嗗澶辫触",
                        "message": "妯″瀷璧勬簮鍑嗗澶辫触",
                        "audience": "host",
                        "level": "warning",
                        "timestamp": 3.0,
                        "payload": {
                            "status": "failed",
                            "item_count": 0,
                            "requested_count": 3,
                            "failed_count": 3,
                            "batch_index": 1,
                            "total_batches": 1,
                        },
                    },
                    {
                        "event_id": "evt-resource-second-import",
                        "room_id": "room-resource-import-batch-only",
                        "batch_id": second_batch_id,
                        "event_type": "actors_import_failed",
                        "title": "导入失败",
                        "message": "导入失败",
                        "audience": "host",
                        "level": "warning",
                        "timestamp": 4.0,
                        "payload": {
                            "status": "failed",
                            "actor_count": 0,
                            "requested_count": 3,
                            "failed_count": 3,
                            "batch_index": 1,
                            "total_batches": 1,
                        },
                    },
                ]
            },
        ))
        self.assertTrue(ok, reason)

        status = runtime.status_summary(
            "room-resource-import-batch-only",
            plan_id=first_plan.plan_id,
        )
        report = runtime.generate_report(
            room_id="room-resource-import-batch-only",
            plan_id=first_plan.plan_id,
        )

        self.assertEqual(status["resource_summary"]["event_count"], 1)
        self.assertEqual(status["resource_summary"]["by_phase"]["image"]["item_count"], 2)
        self.assertNotIn("model", status["resource_summary"]["by_phase"])
        self.assertEqual(status["import_summary"]["event_count"], 1)
        self.assertEqual(status["import_summary"]["requested_count"], 2)
        self.assertEqual(status["import_summary"]["imported_count"], 2)
        self.assertEqual(status["import_summary"]["failed_count"], 0)
        self.assertEqual(report["resource_summary"], status["resource_summary"])
        self.assertEqual(report["import_summary"], status["import_summary"])
        self.assertNotIn(second_batch_id, str(status["resource_summary"]))
        self.assertNotIn(second_batch_id, str(status["import_summary"]))
        self.assertNotIn(second_batch_id, str(report["resource_summary"]))
        self.assertNotIn(second_batch_id, str(report["import_summary"]))

    def test_model_resource_provider_failure_emits_safe_runtime_event(self) -> None:
        def failing_model_provider(payload: dict) -> dict:
            raise RuntimeError("provider=secret-hunyuan prompt=internal")

        runtime = AgentRuntime(model_resource_provider=failing_model_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-model-provider-fail",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        state = runtime.query_state("room-model-provider-fail")["room"]
        self.assertEqual(result["graphs"][0]["status"], "failed")
        self.assertEqual(result["batches"][0]["status"], "failed")
        failed = runtime.operation_log.query(event="tool_call_failed")
        self.assertEqual(failed[-1].payload["error_code"], "model_resource_provider_failed")
        self.assertTrue(failed[-1].payload["user_visible_message"])
        self.assertNotIn("secret-hunyuan", str(failed[-1].payload))
        self.assertNotIn("internal", str(failed[-1].payload))
        runtime_events = [event for event in state["runtime_events"] if event["event_type"] == "tool_result_message"]
        self.assertTrue(runtime_events)
        model_failure_events = [
            event
            for event in runtime_events
            if event.get("payload", {}).get("status") == "failed"
        ]
        self.assertTrue(model_failure_events)
        serialized = str(model_failure_events[-1])
        self.assertNotIn("secret-hunyuan", serialized)
        self.assertNotIn("internal", serialized)
        for resource_summary in (
            result["report"]["resource_summary"],
            runtime.status_summary("room-model-provider-fail", plan_id=plan.plan_id)["resource_summary"],
        ):
            self.assertEqual(resource_summary["event_count"], 2)
            self.assertEqual(resource_summary["by_phase"]["image"]["status_counts"], {"succeeded": 1})
            self.assertEqual(resource_summary["by_phase"]["model"]["status_counts"], {"failed": 1})
            self.assertEqual(resource_summary["by_phase"]["model"]["failed_count"], 2)
            self.assertEqual(resource_summary["latest_events"][-1]["phase"], "model")
            self.assertEqual(resource_summary["latest_events"][-1]["status"], "failed")


    def test_actor_import_provider_failure_emits_safe_runtime_event(self) -> None:
        def ready_model_provider(payload: dict) -> dict:
            return {
                name: {
                    "name": name,
                    "status": "ready",
                    "local_path": f"E:/models/{name}.glb",
                }
                for name in payload["model_items"]
            }

        def failing_import_provider(payload: dict) -> dict:
            raise RuntimeError("raw import failure scene=secret")

        runtime = AgentRuntime(
            model_resource_provider=ready_model_provider,
            actor_import_provider=failing_import_provider,
        )
        plan = runtime.propose_scene_plan(
            room_id="room-import-provider-fail",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=2)

        state = runtime.query_state("room-import-provider-fail")["room"]
        self.assertEqual(result["graphs"][0]["status"], "failed")
        self.assertEqual(result["batches"][0]["status"], "failed")
        self.assertEqual(state["actors"], {})
        failed = runtime.operation_log.query(event="tool_call_failed")
        self.assertEqual(failed[-1].payload["error_code"], "actor_import_provider_failed")
        self.assertEqual(failed[-1].payload["user_visible_message"], "场景导入失败，系统会稍后重试或等待进一步处理。")
        self.assertNotIn("secret", str(failed[-1].payload))
        runtime_events = [event for event in state["runtime_events"] if event["event_type"] == "tool_result_message"]
        self.assertTrue(runtime_events)
        import_failure_messages = [
            event for event in runtime_events
            if event["message"] == "场景导入失败，系统会稍后重试或等待进一步处理。"
        ]
        self.assertTrue(import_failure_messages)
        self.assertNotIn("secret", str(import_failure_messages[-1]))
        events = runtime.user_visible_events("room-import-provider-fail", plan_id=plan.plan_id)
        import_events = [event for event in events if event["event_type"] == "actors_import_failed"]
        self.assertTrue(import_events)
        self.assertEqual(
            import_events[0]["payload"],
            {
                "actor_count": 0,
                "batch_index": 1,
                "failed_count": 2,
                "import_failure_code_counts": {"actor_import_adapter_failed": 2},
                "imported_count": 0,
                "requested_count": 2,
                "status": "failed",
                "total_batches": 5,
            },
        )
        expected_import_summary = {
            "event_count": 1,
            "failed_count": 2,
            "import_failure_code_counts": {"actor_import_provider_failed": 2},
            "imported_count": 0,
            "latest_events": [
                {
                    "actor_count": 0,
                    "batch_id": result["batches"][0]["batch_id"],
                    "batch_index": 1,
                    "failed_count": 2,
                    "requested_count": 2,
                    "status": "failed",
                    "total_batches": 5,
                }
            ],
            "requested_count": 2,
            "status_counts": {"failed": 1},
        }
        self.assertEqual(result["report"]["import_summary"], expected_import_summary)
        self.assertEqual(
            runtime.status_summary("room-import-provider-fail", plan_id=plan.plan_id)["import_summary"],
            expected_import_summary,
        )
        report_pending_events = [event for event in events if event["event_type"] == "report_pending"]
        self.assertTrue(report_pending_events)
        terminal_event = report_pending_events[-1]
        self.assertEqual(terminal_event["payload"]["requested_count"], 2)
        self.assertEqual(terminal_event["payload"]["imported_count"], 0)
        self.assertEqual(terminal_event["payload"]["failed_count"], 2)

    def test_runtime_injects_model_resources_into_engine_actor_import_provider(self) -> None:
        class FakeGate:
            def __init__(self) -> None:
                self.calls: list[dict] = []

            def invoke_tool(self, tool, payload: dict) -> dict:
                self.calls.append(dict(payload))
                return tool.invoke(payload)

        class FakeImportTool:
            def invoke(self, payload: dict) -> dict:
                return {
                    "status": "success",
                    "actor_name": payload["actor_name"],
                    "model_path": payload["model_path"],
                    "actor_data": {
                        "name": payload["actor_name"],
                        "actor_id": f"guid-{payload['actor_name']}",
                        "position": payload["position"],
                        "rotation": payload["rotation"],
                        "scale": payload["scale"],
                        "bounds": [-0.25, 0.0, -0.25, 0.25, 1.0, 0.25],
                        "sync_status": "created",
                        "sync_lifecycle_status": "created",
                        "last_sync_event": "actor_created",
                    },
                }

        def model_resource_provider(payload: dict) -> dict:
            return {
                name: {
                    "name": name,
                    "status": "ready",
                    "local_path": f"E:/models/{name}.glb",
                }
                for name in payload["model_items"]
            }

        gate = FakeGate()
        runtime = AgentRuntime(
            model_resource_provider=model_resource_provider,
            actor_import_provider=make_engine_actor_import_provider(
                import_tool=FakeImportTool(),
                engine_gate=gate,
            ),
        )
        plan = runtime.propose_scene_plan(
            room_id="room-import-bridge",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠卞拰閲戝竵",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(
            plan.plan_id,
            max_items_per_batch=2,
            scene_name="Scene/场景1.scene",
        )

        state = runtime.query_state("room-import-bridge")["room"]
        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertGreaterEqual(len(gate.calls), 1)
        self.assertEqual(gate.calls[0]["model_path"], f"E:/models/{result['batches'][0]['requested_items'][0]}.glb")
        self.assertEqual(gate.calls[0]["scene_name"], "Scene/场景1.scene")
        self.assertIn("tool_call_runtime_facts_injected", runtime.operation_log.events())
        import_nodes = [
            node
            for graph_snapshot in state["tool_graphs"].values()
            for node in graph_snapshot["nodes"].values()
            if node["tool_name"] == "runtime.actor.import_batch"
        ]
        self.assertTrue(import_nodes)
        self.assertIn("model_resources", import_nodes[0]["args"])
        self.assertTrue(all(actor.get("source") == "engine_import" for actor in state["actors"].values()))
        self.assertTrue(all(actor.get("sync_status") == "created" for actor in state["actors"].values()))
        self.assertTrue(all(actor.get("aabb") for actor in state["actors"].values()))
        status = runtime.status_summary("room-import-bridge", plan_id=plan.plan_id)
        self.assertEqual(status["scene_entity_registry"]["missing_transform_count"], 0)
        self.assertEqual(status["scene_entity_registry"]["missing_aabb_count"], 0)
        self.assertGreaterEqual(status["scene_entity_registry"]["sync_status_counts"].get("created", 0), 1)
        self.assertEqual(result["report"]["scene_entity_registry"]["missing_transform_count"], 0)
        self.assertEqual(result["report"]["scene_entity_registry"]["missing_aabb_count"], 0)

    def test_runtime_actor_import_estimates_aabb_when_engine_omits_bounds(self) -> None:
        class FakeGate:
            def invoke_tool(self, tool, payload: dict) -> dict:
                return tool.invoke(payload)

        class AsyncGeometryImportTool:
            def invoke(self, payload: dict) -> dict:
                return {
                    "status": "success",
                    "actor_name": payload["actor_name"],
                    "actor_data": {
                        "actor_id": f"guid-{payload['actor_name']}",
                        "name": payload["actor_name"],
                        "position": payload["position"],
                        "rotation": payload["rotation"],
                        "scale": payload["scale"],
                        "sync_status": "created",
                        "sync_lifecycle_status": "created",
                    },
                }

        def model_resource_provider(payload: dict) -> dict:
            return {
                name: {
                    "name": name,
                    "status": "ready",
                    "local_path": f"E:/models/{name}.glb",
                }
                for name in payload["model_items"]
            }

        runtime = AgentRuntime(
            model_resource_provider=model_resource_provider,
            actor_import_provider=make_engine_actor_import_provider(
                import_tool=AsyncGeometryImportTool(),
                engine_gate=FakeGate(),
                scene_name="Scene/场景1.scene",
            ),
        )
        plan = runtime.propose_scene_plan(
            room_id="room-import-async-aabb",
            text="生成一个简单藏宝室，有藏宝箱和木桌。",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(
            plan.plan_id,
            max_items_per_batch=2,
            scene_name="Scene/场景1.scene",
        )
        status = runtime.status_summary("room-import-async-aabb", plan_id=plan.plan_id)
        report = runtime.generate_report("room-import-async-aabb", plan_id=plan.plan_id)
        imported_count = int(result["report"]["import_summary"]["imported_count"])

        self.assertEqual(result["graphs"][0]["status"], "completed")
        self.assertGreaterEqual(imported_count, 1)
        actors = runtime.query_state("room-import-async-aabb")["room"]["actors"]
        self.assertEqual(len(actors), imported_count)
        for actor in actors.values():
            self.assertEqual(actor["source"], "engine_import_runtime_estimated_bounds")
            self.assertEqual(actor["review_status"], "needs_geometry_review")
            self.assertEqual(actor["grounding_status"], "needs_review")
            self.assertIn("aabb", actor)
        self.assertEqual(status["scene_entity_registry"]["actor_count"], imported_count)
        self.assertEqual(status["scene_entity_registry"]["readiness_status"], "ready")
        self.assertEqual(status["scene_entity_registry"]["missing_transform_count"], 0)
        self.assertEqual(status["scene_entity_registry"]["missing_aabb_count"], 0)
        self.assertEqual(
            status["scene_entity_registry"]["estimated_actor_bounds_count"],
            imported_count,
        )
        self.assertEqual(
            status["scene_entity_registry"]["geometry_source_counts"],
            {"runtime_estimated_bounds": imported_count},
        )
        self.assertEqual(report["scene_entity_registry"]["actor_count"], imported_count)
        self.assertEqual(report["scene_entity_registry"]["readiness_status"], "ready")
        self.assertEqual(report["scene_entity_registry"]["missing_aabb_count"], 0)
        self.assertEqual(
            report["scene_entity_registry"]["estimated_actor_bounds_count"],
            imported_count,
        )
        self.assertEqual(
            report["report_health_summary"]["actor_registry_estimated_aabb_count"],
            imported_count,
        )
        for entity in report["scene_entity_registry"]["entities"]:
            if entity["entity_type"] == "actor":
                self.assertEqual(entity["geometry_source"], "runtime_estimated_bounds")
        self.assertEqual(
            report["report_health_summary"]["actor_registry_readiness_status"],
            "ready",
        )
        self.assertEqual(
            report["report_health_summary"]["actor_registry_missing_aabb_count"],
            0,
        )

