    def test_indoor_runtime_environment_components_include_room_framework(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-runtime-indoor-framework",
            text="强盗藏宝室，要有藏宝箱、金币堆和火把",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")

        result = runtime.execute_planned_batches(plan.plan_id, max_items_per_batch=99)

        batch_id = result["batches"][0]["batch_id"]
        state = runtime.query_state("room-runtime-indoor-framework")["room"]
        environment_components = state["environment_components"][batch_id]
        component_types = {item["component_type"] for item in environment_components.values()}
        component_names = {item["name"] for item in environment_components.values()}
        self.assertIn("room_box", component_types)
        self.assertIn("room_floor", component_types)
        self.assertIn("room_box", component_names)
        self.assertIn("room_floor", component_names)
        self.assertTrue(all(not item["requires_engine_write"] for item in environment_components.values()))
        environment_nodes = [
            node
            for node in result["graphs"][0]["nodes"].values()
            if node["tool_name"] == "runtime.environment.create_components"
        ]
        self.assertEqual(len(environment_nodes), 1)
