    def test_runtime_guard_blocks_unconfirmed_high_risk_tool(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        ran_downstream = False

        def downstream_tool(call: ToolCall) -> ToolResult:
            nonlocal ran_downstream
            ran_downstream = True
            return ToolResult(
                True,
                state_patch=StatePatch(
                    room_id="room-1",
                    changes={"actors": {"actor-2": {"name": "should-not-run"}}},
                ),
            )

        registry.register(
            "mock.delete_actor",
            lambda call: ToolResult(True, state_patch=StatePatch(room_id="room-1", changes={})),
            requires_write=True,
        )
        registry.register("mock.downstream", downstream_tool)
        graph = ToolCallGraph(graph_id="graph-1", plan_id="plan-1", batch_id="batch-1")
        graph.add(ToolCall(tool_call_id="tool-2", tool_name="mock.downstream", depends_on=["tool-1"]))
        graph.add(
            ToolCall(
                tool_call_id="tool-1",
                tool_name="mock.delete_actor",
                args={"room_id": "room-1", "actor_name": "钘忓疂绠?"},
                risk_level=RiskLevel.HIGH,
                requires_write=True,
                confirmed=False,
            )
        )

        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        )
        executed = executor.execute(graph, room_id="room-1")

        self.assertEqual(executed.status, "blocked")
        self.assertEqual(executed.nodes["tool-2"].status, ToolCallStatus.SKIPPED)
        self.assertFalse(ran_downstream)
        self.assertIn("tool_call_blocked", operation_log.events())
        self.assertIn("tool_call_skipped", operation_log.events())

    def test_runtime_guard_blocks_unconfirmed_low_risk_write_tool(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        registry.register(
            "mock.import_actor",
            lambda call: ToolResult(
                True,
                state_patch=StatePatch(room_id="room-1", changes={"actors": {"actor-1": {"name": "钘忓疂绠?"}}}),
            ),
            category=ToolCategory.IMPORT,
            requires_write=True,
            required_args=("room_id", "actor_name"),
        )
        graph = ToolCallGraph(graph_id="graph-1", plan_id="plan-1", batch_id="batch-1")
        graph.add(
            ToolCall(
                tool_call_id="tool-1",
                tool_name="mock.import_actor",
                args={"room_id": "room-1", "actor_name": "钘忓疂绠?"},
                risk_level=RiskLevel.LOW,
                requires_write=True,
                confirmed=False,
            )
        )
        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        )
        executed = executor.execute(graph, room_id="room-1")

        self.assertEqual(executed.status, "blocked")
        self.assertEqual(state.snapshot("room-1")["room"]["actors"], {})
        self.assertIn("tool_call_blocked", operation_log.events())
        runtime_events = state.snapshot("room-1")["room"]["runtime_events"]
        blocked_events = [event for event in runtime_events if event["event_type"] == "tool_call_blocked"]
        self.assertEqual(len(blocked_events), 1)
        self.assertEqual(blocked_events[0]["phase"], "runtime_guard")
        expected_guard_payload = {
            "status": "blocked",
            "guard_reason": "write tool call requires confirmed plan or explicit confirmation",
            "risk_level": "low",
            "requires_write": True,
            "confirmed": False,
        }
        self.assertEqual(blocked_events[0]["payload"], expected_guard_payload)
        blocked_log = operation_log.query(event="tool_call_blocked", room_id="room-1", plan_id="plan-1")[-1]
        self.assertEqual(
            blocked_log.payload["guard_reason"],
            "write tool call requires confirmed plan or explicit confirmation",
        )
        self.assertEqual(blocked_log.payload["risk_level"], "low")
        self.assertTrue(blocked_log.payload["requires_write"])
        self.assertFalse(blocked_log.payload["confirmed"])
        emitted = [
            entry
            for entry in operation_log.query(event="runtime_event_emitted", room_id="room-1", plan_id="plan-1")
            if entry.payload.get("event_type") == "tool_call_blocked"
        ]
        self.assertTrue(emitted)
        self.assertEqual(
            emitted[-1].payload["guard_reason"],
            "write tool call requires confirmed plan or explicit confirmation",
        )
        self.assertEqual(emitted[-1].payload["risk_level"], "low")
        self.assertTrue(emitted[-1].payload["requires_write"])
        self.assertFalse(emitted[-1].payload["confirmed"])
        self.assertTrue(str(blocked_events[0].get("title") or "").strip())
        serialized = str(blocked_events[0])
        self.assertNotIn("mock.import_actor", serialized)
        self.assertNotIn("钘忓疂绠?", serialized)
        runtime = AgentRuntime(
            state=state,
            operation_log=operation_log,
            registry=registry,
            guard=RuntimeGuard(),
        )
        replay = runtime.operation_replay(room_id="room-1", plan_id="plan-1")
        guard_summary = replay["runtime_guard_replay_summary"]
        self.assertEqual(guard_summary["blocked_count"], 1)
        self.assertEqual(guard_summary["write_confirmation_required_count"], 1)
        self.assertEqual(guard_summary["high_risk_confirmation_required_count"], 0)
        self.assertEqual(guard_summary["system_actor_write_blocked_count"], 0)
        self.assertEqual(guard_summary["user_visible_blocked_event_count"], 1)
        self.assertEqual(guard_summary["reason_counts"], {"write_confirmation_required": 1})
        self.assertNotIn("mock.import_actor", str(guard_summary))
        self.assertNotIn("钘忓疂绠?", str(guard_summary))

