    def test_tool_graph_executor_stops_before_next_tool_when_plan_is_paused(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()

        state.apply_patch(StatePatch(
            room_id="room-executor-stop",
            changes={
                "scene_plans": {
                    "plan-stop": {
                        "plan_id": "plan-stop",
                        "room_id": "room-executor-stop",
                        "title": "钘忓疂瀹?",
                        "design_brief": "钘忓疂瀹?",
                        "status": "executing",
                    }
                },
                "active_plan_id": "plan-stop",
            },
        ))

        def pause_plan(call: ToolCall) -> ToolResult:
            return ToolResult(
                True,
                message="paused",
                state_patch=StatePatch(
                    room_id="room-executor-stop",
                    changes={
                        "scene_plans": {
                            "plan-stop": {
                                "plan_id": "plan-stop",
                                "room_id": "room-executor-stop",
                                "title": "钘忓疂瀹?",
                                "design_brief": "钘忓疂瀹?",
                                "status": "paused",
                            }
                        }
                    },
                ),
            )

        registry.register("mock.pause_plan", pause_plan)
        registry.register("mock.never_run", lambda call: ToolResult(True, message="should not run"))
        graph = ToolCallGraph(graph_id="graph-stop", plan_id="plan-stop", batch_id="batch-stop")
        graph.add(ToolCall(tool_call_id="tool-1", tool_name="mock.pause_plan", args={}))
        graph.add(ToolCall(tool_call_id="tool-2", tool_name="mock.never_run", args={}, depends_on=["tool-1"]))

        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        )
        executed = executor.execute(graph, room_id="room-executor-stop")

        self.assertEqual(executed.status, "paused")
        self.assertEqual(executed.nodes["tool-1"].status, ToolCallStatus.SUCCEEDED)
        self.assertEqual(executed.nodes["tool-2"].status, ToolCallStatus.SKIPPED)
        self.assertIn("tool_graph_stopped_by_runtime_command", operation_log.events())
        runtime_events = state.snapshot("room-executor-stop")["room"]["runtime_events"]
        stopped_events = [
            event
            for event in runtime_events
            if event["event_type"] == "tool_graph_stopped_by_runtime_command"
        ]
        self.assertEqual(len(stopped_events), 1)
        stopped_log = operation_log.query(
            event="tool_graph_stopped_by_runtime_command",
            room_id="room-executor-stop",
            plan_id="plan-stop",
        )[-1]
        self.assertEqual(stopped_log.payload["skipped_count"], 1)
        emitted_logs = [
            entry
            for entry in operation_log.query(
                event="runtime_event_emitted",
                room_id="room-executor-stop",
                plan_id="plan-stop",
            )
            if entry.payload.get("event_type") == "tool_graph_stopped_by_runtime_command"
        ]
        self.assertTrue(emitted_logs)
        self.assertEqual(emitted_logs[-1].payload["skipped_count"], 1)
        self.assertEqual(stopped_events[0]["payload"], {"status": "paused", "skipped_count": 1})
        self.assertTrue(str(stopped_events[0].get("title") or "").strip())
        self.assertNotIn("tool_name", str(stopped_events[0]))
        self.assertNotIn("mock.never_run", str(stopped_events[0]))

    def test_tool_graph_stopped_is_not_logged_when_stopped_state_persist_fails(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        calls = {"pause": 0, "downstream": 0}
        ok, reason = state.apply_patch(StatePatch(
            room_id="room-executor-stop-persist-fail",
            changes={
                "scene_plans": {
                    "plan-stop": {
                        "plan_id": "plan-stop",
                        "room_id": "room-executor-stop-persist-fail",
                        "title": "钘忓疂瀹?",
                        "design_brief": "钘忓疂瀹?",
                        "status": "executing",
                    }
                },
                "active_plan_id": "plan-stop",
            },
        ))
        self.assertTrue(ok, reason)

        def pause_plan(call: ToolCall) -> ToolResult:
            calls["pause"] += 1
            return ToolResult(
                True,
                message="paused",
                state_patch=StatePatch(
                    room_id="room-executor-stop-persist-fail",
                    changes={
                        "scene_plans": {
                            "plan-stop": {
                                "plan_id": "plan-stop",
                                "room_id": "room-executor-stop-persist-fail",
                                "title": "钘忓疂瀹?",
                                "design_brief": "钘忓疂瀹?",
                                "status": "paused",
                            }
                        }
                    },
                ),
            )

        def downstream_tool(call: ToolCall) -> ToolResult:
            calls["downstream"] += 1
            return ToolResult(True, message="should not run")

        registry.register("mock.pause_plan", pause_plan)
        registry.register("mock.never_run", downstream_tool)
        graph = ToolCallGraph(graph_id="graph-stop-persist-fail", plan_id="plan-stop", batch_id="batch-stop")
        graph.add(ToolCall(tool_call_id="tool-1", tool_name="mock.pause_plan", args={}))
        graph.add(ToolCall(tool_call_id="tool-2", tool_name="mock.never_run", args={}, depends_on=["tool-1"]))
        original_apply_patch = state.apply_patch

        def fail_stopped_graph_patch(patch: StatePatch) -> tuple[bool, str]:
            graph_fact = dict((patch.changes or {}).get("tool_graphs") or {}).get(graph.graph_id)
            if isinstance(graph_fact, dict) and graph_fact.get("status") == "paused":
                return False, "simulated stopped graph persist failure"
            return original_apply_patch(patch)

        state.apply_patch = fail_stopped_graph_patch  # type: ignore[method-assign]

        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        )
        executed = executor.execute(graph, room_id="room-executor-stop-persist-fail")

        self.assertEqual(executed.status, "failed")
        self.assertEqual(calls, {"pause": 1, "downstream": 0})
        self.assertEqual(executed.nodes["tool-1"].status, ToolCallStatus.SUCCEEDED)
        self.assertEqual(executed.nodes["tool-2"].status, ToolCallStatus.SKIPPED)
        events = [
            entry.event
            for entry in operation_log.entries()
            if entry.payload.get("graph_id") == graph.graph_id or entry.tool_call_id in {"tool-1", "tool-2"}
        ]
        self.assertIn("tool_graph_state_record_failed", events)
        self.assertNotIn("tool_graph_stopped_by_runtime_command", events)
        runtime_events = state.snapshot("room-executor-stop-persist-fail")["room"]["runtime_events"]
        stopped_events = [
            event
            for event in runtime_events
            if event["event_type"] == "tool_graph_stopped_by_runtime_command"
        ]
        self.assertFalse(stopped_events)

    def test_state_patch_version_conflict_is_recorded_not_silently_overwritten(self) -> None:
        state = RuntimeState()
        ok, reason = state.apply_patch(StatePatch(room_id="room-1", changes={"actors": {"a": {"name": "箱子"}}}))
        self.assertTrue(ok, reason)

        ok, reason = state.apply_patch(
            StatePatch(room_id="room-1", changes={"actors": {"b": {"name": "妗?"}}}, expected_version=0)
        )

        self.assertFalse(ok)
        self.assertEqual(reason, "state version conflict")
        self.assertEqual(len(state.conflicts), 1)
        self.assertNotIn("b", state.snapshot("room-1")["room"]["actors"])
        room = state.snapshot("room-1")["room"]
        conflict_facts = room["state_patch_conflicts"]
        self.assertEqual(len(conflict_facts), 1)
        conflict = next(iter(conflict_facts.values()))
        self.assertEqual(conflict["status"], "needs_reconcile")
        self.assertEqual(conflict["source"], "state_patch_version_conflict")
        self.assertEqual(conflict["expected_version"], 0)
        self.assertEqual(conflict["actual_version"], 1)
        self.assertEqual(conflict["change_keys"], ["actors"])
        self.assertNotIn("patch_id", conflict)
        self.assertNotIn("source_tool_call_id", conflict)

