    def test_state_patch_conflict_reconcile_action_records_decision_without_replaying_patch(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        runtime = AgentRuntime(state=state, operation_log=operation_log, registry=registry)
        ok, reason = state.apply_patch(
            StatePatch(room_id="room-conflict-action", changes={"actors": {"existing": {"name": "鏃х瀛?"}}})
        )
        self.assertTrue(ok, reason)
        stale_patch = StatePatch(
            room_id="room-conflict-action",
            changes={"actors": {"actor-stale": {"name": "过期箱子"}}},
            expected_version=0,
        )
        registry.register(
            "mock.stale_patch_for_action",
            lambda call: ToolResult(True, "stale", state_patch=stale_patch),
            requires_write=True,
            produces_state=("actors",),
        )
        graph = ToolCallGraph(graph_id="graph-conflict-action", plan_id="plan-conflict-action")
        graph.add(
            ToolCall(
                tool_call_id="tool-stale-action",
                tool_name="mock.stale_patch_for_action",
                confirmed=True,
                requires_write=True,
            )
        )
        ToolCallGraphExecutor(
            registry=registry,
            guard=runtime.guard,
            state=state,
            operation_log=operation_log,
        ).execute(graph, room_id="room-conflict-action")
        status = runtime.status_summary("room-conflict-action", plan_id="plan-conflict-action")
        conflict = status["state_patch_summary"]["latest_conflicts"][-1]

        result = runtime.handle_message(
            room_id="room-conflict-action",
            text="鎺ュ彈褰撳墠 Runtime 鐘舵€侊紝涓嶈嚜鍔ㄩ噸鏀炬棫 patch",
            action="reconcile_state_patch_conflict",
            sync_event={
                "conflict_id": conflict["conflict_id"],
                "decision": "accept_current_state",
            },
        )

        self.assertTrue(result["handled"])
        self.assertTrue(result["recorded"])
        self.assertEqual(result["reconcile"]["decision"], "reconciled")
        room = state.snapshot("room-conflict-action")["room"]
        self.assertNotIn("actor-stale", room["actors"])
        updated_conflict = room["state_patch_conflicts"][conflict["conflict_id"]]
        self.assertEqual(updated_conflict["status"], "reconciled")
        self.assertEqual(updated_conflict["decision"], "reconciled")
        self.assertIn("state_patch_conflict_reconciled", operation_log.events())
        self.assertTrue(operation_log.query(event="tool_graph_started", plan_id="runtime-state-patch-reconcile"))
        self.assertTrue(operation_log.query(event="tool_call_succeeded"))
        tool_graphs = state.snapshot("room-conflict-action")["room"]["tool_graphs"]
        reconcile_graphs = [
            graph
            for graph in tool_graphs.values()
            if graph.get("plan_id") == "runtime-state-patch-reconcile"
        ]
        self.assertTrue(reconcile_graphs)
        self.assertEqual(reconcile_graphs[-1]["status"], "completed")
        self.assertNotIn(stale_patch.patch_id, str(result))
        self.assertNotIn("tool-stale-action", str(result))
        post_status = runtime.status_summary("room-conflict-action", plan_id="plan-conflict-action")
        self.assertEqual(post_status["state_patch_summary"]["reconcile_pending_count"], 0)
        self.assertEqual(post_status["state_patch_summary"]["reconciled"], 1)
        self.assertEqual(post_status["state_patch_summary"]["decision_counts"], {"reconciled": 1})
        self.assertEqual(
            post_status["state_patch_summary"]["latest_reconcile_event"]["decision"],
            "reconciled",
        )
        replay = runtime.operation_replay(room_id="room-conflict-action", plan_id="plan-conflict-action")
        replay_patch_summary = replay["state_patch_summary"]
        self.assertEqual(replay_patch_summary["conflict"], 1)
        self.assertEqual(replay_patch_summary["reconciled"], 1)
        self.assertEqual(replay_patch_summary["decision_counts"], {"reconciled": 1})
        self.assertNotIn(stale_patch.patch_id, str(replay_patch_summary))
        self.assertNotIn("tool-stale-action", str(replay_patch_summary))
        report = runtime.generate_report("room-conflict-action", plan_id="plan-conflict-action")
        report_patch_summary = report["operation_replay_summary"]["state_patch_summary"]
        self.assertEqual(report_patch_summary["reconciled"], 1)
        self.assertEqual(report_patch_summary["decision_counts"], {"reconciled": 1})

    def test_state_patch_conflict_does_not_emit_result_when_failed_state_persist_fails(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        ok, reason = state.apply_patch(StatePatch(room_id="room-1", changes={"actors": {"existing": {"name": "鏃х瀛?"}}}))
        self.assertTrue(ok, reason)
        stale_patch = StatePatch(
            room_id="room-1",
            changes={"actors": {"actor-stale": {"name": "过期箱子"}}},
            expected_version=0,
        )
        registry.register(
            "mock.stale_patch",
            lambda call: ToolResult(
                True,
                "stale",
                state_patch=stale_patch,
            ),
        )
        graph = ToolCallGraph(graph_id="graph-stale-persist-fail", plan_id="plan-stale")
        graph.add(ToolCall(tool_call_id="tool-stale", tool_name="mock.stale_patch"))
        original_apply_patch = state.apply_patch

        def fail_patch_conflict_failed_state(patch: StatePatch) -> tuple[bool, str]:
            graph_fact = dict((patch.changes or {}).get("tool_graphs") or {}).get(graph.graph_id)
            nodes = dict(graph_fact.get("nodes") or {}) if isinstance(graph_fact, dict) else {}
            tool_fact = dict(nodes.get("tool-stale") or {}) if isinstance(nodes.get("tool-stale"), dict) else {}
            if tool_fact.get("status") == "failed":
                return False, "simulated state patch conflict failed persist failure"
            return original_apply_patch(patch)

        state.apply_patch = fail_patch_conflict_failed_state  # type: ignore[method-assign]

        executed = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        ).execute(graph, room_id="room-1")

        self.assertEqual(executed.status, "failed")
        self.assertEqual(executed.nodes["tool-stale"].status, ToolCallStatus.FAILED)
        self.assertEqual(executed.nodes["tool-stale"].error, "state patch failure state was not persisted")
        self.assertNotIn("actor-stale", state.snapshot("room-1")["room"]["actors"])
        events = [
            entry.event
            for entry in operation_log.entries()
            if entry.payload.get("graph_id") == graph.graph_id or entry.tool_call_id == "tool-stale"
        ]
        self.assertIn("runtime_state_patch_conflict", events)
        self.assertIn("tool_graph_state_record_failed", events)
        self.assertNotIn("tool_call_succeeded", events)
        runtime_events = state.snapshot("room-1")["room"]["runtime_events"]
        self.assertFalse([event for event in runtime_events if event["event_type"] == "tool_result_message"])

