    def test_state_patch_validator_protects_runtime_owned_control_slots(self) -> None:
        state = RuntimeState()

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-1",
                changes={"legacy_workflow_state": {"provider": "hidden"}},
            )
        )
        self.assertFalse(ok)
        self.assertIn("unsupported", reason)

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-1",
                changes={"custom_runtime_facts": {"item": {"provider": "hidden"}}},
            )
        )
        self.assertFalse(ok)
        self.assertIn("provider", reason)

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-1",
                changes={"state_patch_history": [{"patch_id": "forged", "provider": "hidden"}]},
            )
        )
        self.assertFalse(ok)
        self.assertIn("RuntimeState-owned", reason)
        self.assertFalse(state.snapshot("room-1")["room"]["state_patch_history"])

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-1",
                changes={"active_plan_id": {"bad": "shape"}},
            )
        )
        self.assertFalse(ok)
        self.assertIn("active_plan_id must be a string", reason)

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-1",
                changes={"external_plan_links": {"seed-1": {"plan_id": "plan-1"}}},
            )
        )
        self.assertFalse(ok)
        self.assertIn("external_plan_links entries", reason)

        ok, reason = state.apply_patch(
            StatePatch(
                room_id="room-1",
                changes={
                    "active_plan_id": "plan-1",
                    "external_plan_links": {"seed-1": "plan-1"},
                    "scene_plans": {
                        "plan-1": {
                            "plan_id": "plan-1",
                            "room_id": "room-1",
                            "status": ScenePlanStatus.PROPOSED.value,
                            "design_brief": "钘忓疂瀹?",
                        }
                    },
                },
            )
        )
        self.assertTrue(ok, reason)
        room = state.snapshot("room-1")["room"]
        self.assertEqual(room["active_plan_id"], "plan-1")
        self.assertEqual(room["external_plan_links"]["seed-1"], "plan-1")
        self.assertEqual(room["state_patch_history"][-1]["change_keys"], ["active_plan_id", "external_plan_links", "scene_plans"])

