    def test_failed_dependency_skips_downstream_calls_without_touching_state(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        registry.register("mock.prepare_asset", lambda call: ToolResult(False, "asset failed", retryable=False))
        registry.register(
            "mock.import_actor",
            lambda call: ToolResult(
                True,
                state_patch=StatePatch(room_id="room-1", changes={"actors": {"actor-1": {"name": "箱子"}}}),
            ),
            requires_write=True,
        )
        graph = ToolCallGraph(graph_id="graph-1", plan_id="plan-1", batch_id="batch-1")
        graph.add(ToolCall(tool_call_id="tool-prepare", tool_name="mock.prepare_asset"))
        graph.add(
            ToolCall(
                tool_call_id="tool-import",
                tool_name="mock.import_actor",
                depends_on=["tool-prepare"],
                requires_write=True,
            )
        )
        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
            policy=GraphExecutionPolicy(fail_fast=False, skip_dependents_on_failure=True),
        )

        executed = executor.execute(graph, room_id="room-1")

        self.assertEqual(executed.status, "failed")
        self.assertEqual(executed.nodes["tool-import"].status.value, "skipped")
        self.assertEqual(state.snapshot("room-1")["room"]["actors"], {})
        self.assertIn("tool_call_skipped", operation_log.events())
        skipped_events = [
            event
            for event in state.snapshot("room-1")["room"]["runtime_events"]
            if event["event_type"] == "tool_result_message"
            and event.get("payload", {}).get("status") == "skipped"
        ]
        self.assertTrue(skipped_events)
