    def test_recursive_skip_stops_when_grandchild_skip_state_persist_fails(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()

        registry.register("mock.prepare_asset", lambda call: ToolResult(False, "asset failed", retryable=False))
        registry.register("mock.import_actor", lambda call: ToolResult(True, "should not run"), requires_write=True)
        registry.register("mock.review_scene", lambda call: ToolResult(True, "should not run"))
        registry.register("mock.side_effect", lambda call: ToolResult(True, "should not run"))
        graph = ToolCallGraph(graph_id="graph-recursive-skip-persist-fail", plan_id="plan-1", batch_id="batch-1")
        graph.add(ToolCall(tool_call_id="tool-prepare", tool_name="mock.prepare_asset"))
        graph.add(
            ToolCall(
                tool_call_id="tool-import",
                tool_name="mock.import_actor",
                depends_on=["tool-prepare"],
                requires_write=True,
            )
        )
        graph.add(
            ToolCall(
                tool_call_id="tool-review",
                tool_name="mock.review_scene",
                depends_on=["tool-import"],
            )
        )
        graph.add(
            ToolCall(
                tool_call_id="tool-side",
                tool_name="mock.side_effect",
                depends_on=["tool-prepare"],
            )
        )
        original_apply_patch = state.apply_patch

        def fail_grandchild_skip_patch(patch: StatePatch) -> tuple[bool, str]:
            graph_fact = dict((patch.changes or {}).get("tool_graphs") or {}).get(graph.graph_id)
            nodes = dict(graph_fact.get("nodes") or {}) if isinstance(graph_fact, dict) else {}
            review_fact = dict(nodes.get("tool-review") or {}) if isinstance(nodes.get("tool-review"), dict) else {}
            if review_fact.get("status") == "skipped":
                return False, "simulated grandchild skip persist failure"
            return original_apply_patch(patch)

        state.apply_patch = fail_grandchild_skip_patch  # type: ignore[method-assign]
        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
            policy=GraphExecutionPolicy(fail_fast=False, skip_dependents_on_failure=True),
        )

        executed = executor.execute(graph, room_id="room-recursive-skip-persist-fail")

        self.assertEqual(executed.status, "failed")
        self.assertEqual(executed.nodes["tool-import"].status, ToolCallStatus.SKIPPED)
        self.assertEqual(executed.nodes["tool-review"].status, ToolCallStatus.FAILED)
        self.assertEqual(executed.nodes["tool-review"].error, "dependent skip state was not persisted")
        self.assertEqual(executed.nodes["tool-side"].status, ToolCallStatus.PLANNED)
        skipped_ids = {
            entry.tool_call_id
            for entry in operation_log.query(event="tool_call_skipped")
        }
        self.assertIn("tool-import", skipped_ids)
        self.assertNotIn("tool-review", skipped_ids)
        self.assertNotIn("tool-side", skipped_ids)
        events = [
            entry.event
            for entry in operation_log.entries()
            if entry.payload.get("graph_id") == graph.graph_id
            or entry.tool_call_id in {"tool-prepare", "tool-import", "tool-review", "tool-side"}
        ]
        self.assertIn("tool_graph_state_record_failed", events)

