        self.assertIn("tool_call_failed", events)
        self.assertIn("tool_call_skipped", events)
        self.assertNotIn("tool_call_succeeded", events)
        failure_summary = AgentRuntime._tool_failure_strategy_replay_summary(operation_log.query(room_id="room-retry-exhausted"))
        self.assertEqual(failure_summary["retry_scheduled_count"], 1)
        self.assertEqual(failure_summary["dependency_skipped_count"], 1)
        self.assertEqual(failure_summary["strategy_counts"]["retry_scheduled"], 1)
        self.assertEqual(failure_summary["strategy_counts"]["dependency_skipped"], 1)
        self.assertEqual(failure_summary["latest_strategy_event"]["strategy"], "dependency_skipped")
        tool_summary = AgentRuntime._tool_execution_replay_summary(
            [OperationLog._safe_entry(entry) for entry in operation_log.query(room_id="room-retry-exhausted")]
        )
        self.assertEqual(tool_summary["skipped_count"], 1)
        runtime_events = state.snapshot("room-retry-exhausted")["room"]["runtime_events"]
        serialized = str(runtime_events)
        self.assertIn("retry_scheduled", serialized)
        self.assertIn("failed", serialized)
        self.assertIn("skipped", serialized)
        self.assertNotIn("https://", serialized)
        self.assertNotIn("provider raw", serialized.lower())

