    def test_long_running_tool_start_emits_safe_runtime_event(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()

        def asset_tool(call: ToolCall) -> ToolResult:
            graph_snapshot = state.snapshot("room-1")["room"]["tool_graphs"]["graph-1"]
            self.assertEqual(graph_snapshot["nodes"]["tool-1"]["status"], "running")
            runtime_events = state.snapshot("room-1")["room"]["runtime_events"]
            started = [event for event in runtime_events if event["event_type"] == "tool_call_started"]
            self.assertTrue(started)
            return ToolResult(
                True,
                "asset ready",
                payload={"provider": "secret-provider", "prompt": "internal prompt"},
            )

        registry.register(
            "mock.prepare_asset",
            asset_tool,
            category=ToolCategory.ASSET,
        )
        graph = ToolCallGraph(graph_id="graph-1", plan_id="plan-1", batch_id="batch-1")
        graph.add(
            ToolCall(
                tool_call_id="tool-1",
                tool_name="mock.prepare_asset",
                args={"prompt": "internal prompt"},
            )
        )

        executed = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        ).execute(graph, room_id="room-1")

        self.assertEqual(executed.status, "completed")
        runtime_events = state.snapshot("room-1")["room"]["runtime_events"]
        started = [event for event in runtime_events if event["event_type"] == "tool_call_started"]
        self.assertTrue(started)
        self.assertNotIn("tool_call_id", started[-1])
        self.assertTrue(started[-1]["title"])
        self.assertEqual(started[-1]["payload"], {"status": "running"})
        visible_started = [
            event
            for event in AgentRuntime(state=state).user_visible_events("room-1")
            if event["event_type"] == "tool_call_started"
        ]
        self.assertTrue(visible_started)
        self.assertNotIn("tool_call_id", visible_started[-1])
        self.assertNotIn("event_id", visible_started[-1])
        serialized = str(started[-1])
        self.assertNotIn("mock.prepare_asset", serialized)
        self.assertNotIn("secret-provider", serialized)
        self.assertNotIn("internal prompt", serialized)

