        self.assertIn("tool_call_id mismatch", executed.nodes["tool-1"].error)
        self.assertEqual(state.snapshot("room-1")["room"]["assets"], {})
        invalid = operation_log.query(event="tool_call_invalid_result", tool_call_id="tool-1")
