    def test_failed_tool_result_is_not_logged_when_failed_state_persist_fails(self) -> None:
        state = RuntimeState()
        operation_log = OperationLog()
        registry = ToolRegistry()
        calls = {"prepare": 0, "downstream": 0}

        def failed_prepare(call: ToolCall) -> ToolResult:
            calls["prepare"] += 1
            return ToolResult(
                False,
                "provider unavailable",
                error_code="provider_unavailable",
                user_visible_message="妯″瀷鐢熸垚鏈嶅姟鏆傛椂涓嶅彲鐢?",
            )

        def downstream_tool(call: ToolCall) -> ToolResult:
            calls["downstream"] += 1
            return ToolResult(True, "should not run")

        registry.register("runtime.asset.prepare", failed_prepare, category=ToolCategory.ASSET)
        registry.register("mock.downstream", downstream_tool)
        graph = ToolCallGraph(graph_id="graph-failed-result-persist-fail", plan_id="plan-1", batch_id="batch-1")
        graph.add(ToolCall(tool_call_id="tool-prepare", tool_name="runtime.asset.prepare"))
        graph.add(ToolCall(tool_call_id="tool-downstream", tool_name="mock.downstream", depends_on=["tool-prepare"]))
        original_apply_patch = state.apply_patch

        def fail_failed_result_patch(patch: StatePatch) -> tuple[bool, str]:
            graph_fact = dict((patch.changes or {}).get("tool_graphs") or {}).get(graph.graph_id)
            nodes = dict(graph_fact.get("nodes") or {}) if isinstance(graph_fact, dict) else {}
            tool_fact = dict(nodes.get("tool-prepare") or {}) if isinstance(nodes.get("tool-prepare"), dict) else {}
            if tool_fact.get("status") == "failed":
                return False, "simulated failed result persist failure"
            return original_apply_patch(patch)

        state.apply_patch = fail_failed_result_patch  # type: ignore[method-assign]

        executed = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
            policy=GraphExecutionPolicy(fail_fast=False, skip_dependents_on_failure=True),
        ).execute(graph, room_id="room-failed-result-persist-fail")

        self.assertEqual(executed.status, "failed")
        self.assertEqual(executed.nodes["tool-prepare"].status, ToolCallStatus.FAILED)
        self.assertEqual(executed.nodes["tool-prepare"].error, "failed tool result state was not persisted")
        self.assertEqual(executed.nodes["tool-downstream"].status, ToolCallStatus.PLANNED)
        self.assertEqual(calls, {"prepare": 1, "downstream": 0})
        events = [
            entry.event
            for entry in operation_log.entries()
            if entry.payload.get("graph_id") == graph.graph_id or entry.tool_call_id in {"tool-prepare", "tool-downstream"}
        ]
        self.assertIn("tool_graph_state_record_failed", events)
        self.assertNotIn("tool_call_failed", events)
        self.assertNotIn("tool_call_skipped", events)
        runtime_events = state.snapshot("room-failed-result-persist-fail")["room"]["runtime_events"]
        self.assertFalse([event for event in runtime_events if event["event_type"] == "tool_result_message"])

