    def test_tool_call_required_arg_missing_from_runtime_state_does_not_run_handler(self) -> None:
        registry = ToolRegistry()
        captured_args: list[dict] = []

        def consume_tool(call: ToolCall) -> ToolResult:
            captured_args.append(dict(call.args))
            return ToolResult(True)

        registry.register(
            "mock.consume_required",
            consume_tool,
            required_args=("room_id", "payload"),
        )
        state = RuntimeState()
        operation_log = OperationLog()
        graph = ToolCallGraph(graph_id="graph-missing-runtime-facts", plan_id="plan-1")
        graph.add(
            ToolCall(
                tool_call_id="tool-1",
                tool_name="mock.consume_required",
                args={"room_id": "room-consume-missing"},
                consumes={"payload": {"state_key": "custom_facts", "scope": "room"}},
            )
        )
        executor = ToolCallGraphExecutor(
            registry=registry,
            guard=RuntimeGuard(),
            state=state,
            operation_log=operation_log,
        )

        result = executor.execute(graph, room_id="room-consume-missing")

        self.assertEqual(result.status, "failed")
        self.assertEqual(result.nodes["tool-1"].status, ToolCallStatus.FAILED)
        self.assertEqual(result.nodes["tool-1"].error, "required runtime facts missing")
        self.assertEqual(captured_args, [])
        self.assertIn("tool_call_runtime_facts_missing", operation_log.events())
        self.assertNotIn("tool_call_started", operation_log.events())
        events = state.snapshot("room-consume-missing")["room"]["runtime_events"]
        self.assertEqual(events[-1]["event_type"], "tool_result_message")
        self.assertEqual(events[-1]["payload"], {"status": "failed"})

