        self.assertEqual(state["pending_interventions"][modify_patch.patch_id]["status"], "pending")
        self.assertEqual(state["pending_interventions"][delete_patch.patch_id]["status"], "pending")
        self.assertNotIn("鐏妸", str(proposal["deltas"]))
        self.assertIn("pending_intervention_adjustment_requested", runtime.operation_log.events())

