    def test_confirmed_pending_delete_advisory_skips_system_actor(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-pending-delete-system-skip",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠便€侀噾甯佸拰鐏妸",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")
        runtime.state.apply_patch(
            StatePatch(
                room_id="room-pending-delete-system-skip",
                changes={
                    "actors": {
                        "__room_box": {
                            "actor_id": "__room_box",
                            "name": "__room_box",
                            "position": [0.0, 0.0, 0.0],
                        },
                    },
                },
                expected_version=runtime.state.version,
            )
        )
        runtime.record_intervention(
            room_id="room-pending-delete-system-skip",
            plan_id=plan.plan_id,
            text="删除 __room_box",
            patch_type="intervention_delete",
            source_user="房主",
            items=["__room_box"],
            risk_level=RiskLevel.HIGH,
        )
        advisory = runtime.propose_delete_advisories_for_pending_interventions(
            room_id="room-pending-delete-system-skip",
            plan_id=plan.plan_id,
        )
        proposal_id = advisory["proposal"]["proposal_id"]
        runtime.record_review_advisory_confirmation(
            room_id="room-pending-delete-system-skip",
            plan_id=plan.plan_id,
            proposal_id=proposal_id,
            confirmed_by="房主",
        )

        result = runtime.execute_confirmed_delete_advisory(
            room_id="room-pending-delete-system-skip",
            plan_id=plan.plan_id,
            proposal_id=proposal_id,
        )

        self.assertFalse(result["executed"])
        state = runtime.query_state("room-pending-delete-system-skip")["room"]
        self.assertNotIn("deleted", state["actors"]["__room_box"])
        proposal_key = f"{plan.plan_id}:pending_delete"
        self.assertEqual(state["review_advisory_proposals"][proposal_key]["execution_status"], "skipped")
        self.assertEqual(
            state["review_advisory_proposals"][proposal_key]["skipped_targets"][0]["reason"],
            "system actor skipped",
        )
        self.assertEqual(result["graph"]["status"], "completed")
        self.assertEqual(
            {node["tool_name"] for node in result["graph"]["nodes"].values()},
            {"runtime.review_advisory.mark_skipped"},
        )
        mark_skipped_started = [
            entry
            for entry in runtime.operation_log.query(event="tool_call_started")
            if entry.payload.get("tool_name") == "runtime.review_advisory.mark_skipped"
        ]
        self.assertTrue(mark_skipped_started)
        mark_skipped_succeeded = [
            entry
            for entry in runtime.operation_log.query(event="tool_call_succeeded")
            if entry.tool_call_id in {node["tool_call_id"] for node in result["graph"]["nodes"].values()}
        ]
        self.assertTrue(mark_skipped_succeeded)
        self.assertIn("runtime_state_patch_applied", runtime.operation_log.events())

