    def test_confirmed_delete_advisory_with_engine_provider_only_marks_successful_delete(self) -> None:
        def delete_provider(payload: dict[str, Any]) -> dict[str, Any]:
            return {
                "actor_updates": {
                    "actor-torch": {
                        **payload["actors"]["actor-torch"],
                        "deleted": True,
                        "sync_lifecycle_status": "deleted",
                        "last_sync_event": "runtime_engine_delete",
                    },
                },
                "delete_results": [
                    {"actor_id": "actor-torch", "actor_name": "鐏妸", "status": "success", "observed_deleted": True},
                    {"actor_id": "actor-barrel", "actor_name": "木桶", "status": "failed", "reason": "actor delete failed"},
                ],
            }

        runtime = AgentRuntime(actor_delete_provider=delete_provider)
        readiness = runtime.provider_status("room-pending-delete-provider")
        self.assertIn("actor_delete", readiness["provider_summary"])
        self.assertEqual(readiness["provider_summary"]["actor_delete"]["mode"], "adapter")
        plan = runtime.propose_scene_plan(
            room_id="room-pending-delete-provider",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚湪妗跺拰鐏妸",
            owner_agent="商人",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")
        runtime.state.apply_patch(
            StatePatch(
                room_id="room-pending-delete-provider",
                changes={
                    "actors": {
                        "actor-torch": {"actor_id": "actor-torch", "name": "鐏妸", "position": [0.0, 1.0, 0.0]},
                        "actor-barrel": {"actor_id": "actor-barrel", "name": "木桶", "position": [1.0, 0.0, 0.0]},
                    },
                },
                expected_version=runtime.state.version,
            )
        )
        runtime.record_intervention(
            room_id="room-pending-delete-provider",
            plan_id=plan.plan_id,
            text="鍒犻櫎鐏妸銆佹湪妗?",
            patch_type="intervention_delete",
            source_user="房主",
            items=["鐏妸", "鏈ㄦ《"],
            risk_level=RiskLevel.HIGH,
        )
        advisory = runtime.propose_delete_advisories_for_pending_interventions(
            room_id="room-pending-delete-provider",
            plan_id=plan.plan_id,
        )
        proposal_id = advisory["proposal"]["proposal_id"]
        runtime.record_review_advisory_confirmation(
            room_id="room-pending-delete-provider",
            plan_id=plan.plan_id,
            proposal_id=proposal_id,
            confirmed_by="房主",
        )

        result = runtime.execute_confirmed_delete_advisory(
            room_id="room-pending-delete-provider",
            plan_id=plan.plan_id,
            proposal_id=proposal_id,
        )

        self.assertTrue(result["executed"])
        state = runtime.query_state("room-pending-delete-provider")["room"]
        self.assertTrue(state["actors"]["actor-torch"]["deleted"])
        self.assertNotIn("deleted", state["actors"]["actor-barrel"])
        self.assertEqual(state["sync_events"][-1]["event_type"], "actor_deleted")
        self.assertEqual(state["sync_events"][-1]["actor_id"], "actor-torch")
        self.assertNotIn("actor-barrel", state["sync_state"]["actor_events"])
        proposal_key = f"{plan.plan_id}:pending_delete"
        proposal = state["review_advisory_proposals"][proposal_key]
        self.assertEqual(proposal["execution_reason"], "engine actor delete observed")
        self.assertEqual(len(proposal["engine_delete_results"]), 2)
        self.assertEqual(proposal["skipped_targets"][-1]["reason"], "actor delete failed")
        replay = runtime.operation_replay(room_id="room-pending-delete-provider", plan_id=plan.plan_id)
        self.assertEqual(replay["engine_write_summary"]["delete_result_count"], 2)
        self.assertEqual(replay["engine_write_summary"]["delete_status_counts"]["success"], 1)
        self.assertEqual(replay["engine_write_summary"]["delete_status_counts"]["failed"], 1)
        self.assertEqual(
            replay["engine_write_summary"]["latest_delete_results"][0]["observed_deleted"],
            True,
        )
        report = runtime.generate_report("room-pending-delete-provider", plan_id=plan.plan_id)
        delete_channel = report["engine_write_adapter_summary"]["channels"]["actor_delete"]
        self.assertTrue(delete_channel["write_attempted"])
        self.assertEqual(delete_channel["result_count"], 2)
        self.assertEqual(delete_channel["status_counts"], {"failed": 1, "success": 1})
        engine_status = runtime.handle_message(
            room_id="room-pending-delete-provider",
            text="鏌ヨ鍐欏紩鎿庣姸鎬?",
            action="engine_write_status",
        )
        self.assertIn("actor_delete", engine_status["engine_write_status"])

