    def test_layout_adjustment_proposal_failure_returns_persisted_state_only(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-adjust-proposal-fail",
            text="鍋氫竴涓己鐩楄棌瀹濆锛屽寘鍚疂绠?",
            owner_agent="商人",
        )
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-adjust-proposal-fail",
                changes={
                    "geometry_reviews": {
                        plan.plan_id: {
                            "status": "needs_adjustment",
                            "issues": [
                                {
                                    "name": "actor-box",
                                    "type": "floating_or_sunken",
                                    "severity": "low",
                                    "current_y": 0.45,
                                    "suggested_y": 0.0,
                                }
                            ],
                        }
                    }
                },
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)
        original_apply_patch = runtime.state.apply_patch

        def reject_layout_adjustment_proposal_patch(patch: StatePatch) -> tuple[bool, str]:
            if "layout_adjustment_proposals" in patch.changes:
                return False, "simulated layout adjustment proposal persist failure"
            return original_apply_patch(patch)

        runtime.state.apply_patch = reject_layout_adjustment_proposal_patch  # type: ignore[method-assign]

        result = runtime.propose_layout_adjustment(room_id="room-adjust-proposal-fail", plan_id=plan.plan_id)

        self.assertEqual(result["graph"]["status"], "failed")
        self.assertEqual(result["proposal"], {})
        room = runtime.query_state("room-adjust-proposal-fail")["room"]
