    def test_confirm_layout_adjustment_applies_low_risk_deltas_through_runtime_tool(self) -> None:
        def fake_layout_transform_provider(payload: dict) -> dict:
            return {
                "actor_updates": {
                    "actor-box": {
                        "actor_id": "actor-box",
                        "name": "box",
                        "position": [4.0, 0.0, 0.0],
                        "plan_id": payload.get("plan_id", ""),
                    }
                },
                "transform_results": [
                    {
                        "actor_id": "actor-box",
                        "status": "success",
                        "ground_snapped": True,
                        "overlap_resolved": False,
                    },
                    {
                        "actor_id": "actor-missing",
                        "status": "failed",
                        "reason": "actor not found",
                    },
                ],
            }

        runtime = AgentRuntime(layout_transform_provider=fake_layout_transform_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-adjust-confirm",
            text="build a treasure room with a chest",
            owner_agent="merchant",
        )
        runtime.state.apply_patch(
            StatePatch(
                room_id="room-adjust-confirm",
                changes={
                    "actors": {
                        "actor-box": {
                            "actor_id": "actor-box",
                            "name": "box",
                            "position": [8.0, 0.45, 0.0],
                            "plan_id": plan.plan_id,
                        }
                    },
                    "geometry_reviews": {
                        plan.plan_id: {
                            "status": "needs_adjustment",
                            "issues": [
                                {
                                    "name": "box",
                                    "type": "floating_or_sunken",
                                    "suggested_y": 0.0,
                                },
                                {
                                    "name": "box",
                                    "type": "out_of_bounds",
                                    "current_position": [8.0, 0.45, 0.0],
                                    "bounds": [-4.0, 4.0, -4.0, 4.0],
                                },
                            ],
                        }
                    },
                },
                expected_version=runtime.state.version,
            )
        )

        runtime.propose_layout_adjustment(room_id="room-adjust-confirm", plan_id=plan.plan_id)
        pending_replay = runtime.operation_replay(room_id="room-adjust-confirm", plan_id=plan.plan_id)
        pending_layout = pending_replay["layout_adjustment_summary"]
        self.assertEqual(pending_layout["request_count"], 1)
        self.assertEqual(pending_layout["pending_proposal_count"], 1)
        self.assertEqual(pending_layout["confirmed_proposal_count"], 0)
        self.assertGreaterEqual(pending_layout["delta_count"], 1)
        result = runtime.confirm_layout_adjustment(room_id="room-adjust-confirm", plan_id=plan.plan_id)

        self.assertEqual(result["graph"]["status"], "completed")
        room = runtime.query_state("room-adjust-confirm")["room"]
        self.assertEqual(room["actors"]["actor-box"]["position"], [4.0, 0.0, 0.0])
        proposal = room["layout_adjustment_proposals"][plan.plan_id]
        self.assertEqual(proposal["status"], "applied")
        self.assertEqual(len(proposal["applied_deltas"]), 2)
        self.assertEqual(proposal["engine_transform_results"][0]["status"], "success")
        self.assertIn("layout_adjustment_confirmed", runtime.operation_log.events())
        apply_nodes = [
            node
            for node in result["graph"]["nodes"].values()
            if node["tool_name"] == "runtime.layout.apply_delta"
        ]
        self.assertTrue(apply_nodes)
        self.assertTrue(apply_nodes[0]["requires_write"])
        self.assertTrue(apply_nodes[0]["confirmed"])
        self.assertEqual(
            apply_nodes[0]["consumes"]["actors"],
            {"state_key": "actors", "scope": "room"},
        )
        self.assertNotIn("proposal", apply_nodes[0]["consumes"])
        report = runtime.generate_report("room-adjust-confirm", plan_id=plan.plan_id)
        status = runtime.status_summary("room-adjust-confirm", plan_id=plan.plan_id)
        for summary in (
            report["layout_adjustment_summary"],
            status["layout_adjustment_summary"],
        ):
            self.assertEqual(summary["proposal_count"], 1)
            self.assertEqual(summary["transform_result_count"], 2)
            self.assertEqual(summary["transform_status_counts"], {"failed": 1, "success": 1})
            self.assertEqual(summary["ground_snapped_count"], 1)
            self.assertEqual(summary["proposals"][0]["transform_result_count"], 2)
        for summary in (
            report["engine_write_adapter_summary"],
            status["engine_write_adapter_summary"],
        ):
            transform_channel = summary["channels"]["layout_transform"]
            self.assertTrue(transform_channel["write_attempted"])
            self.assertEqual(transform_channel["result_count"], 2)
            self.assertEqual(transform_channel["status_counts"], {"failed": 1, "success": 1})
        replay = runtime.operation_replay(room_id="room-adjust-confirm", plan_id=plan.plan_id)
        replay_summary = replay["layout_adjustment_summary"]
        self.assertEqual(replay_summary["confirmation_count"], 1)
        self.assertEqual(replay_summary["transform_result_count"], 2)
        self.assertEqual(replay_summary["transform_success_count"], 1)
        self.assertEqual(replay_summary["transform_failed_count"], 1)
        self.assertEqual(replay_summary["ground_snapped_count"], 1)
        self.assertEqual(replay_summary["proposal_status_counts"]["confirmed"], 1)
        self.assertEqual(replay_summary["pending_proposal_count"], 0)
        self.assertEqual(replay_summary["confirmed_proposal_count"], 1)
        self.assertEqual(replay_summary["failed_proposal_count"], 0)
        self.assertGreaterEqual(replay_summary["delta_count"], 1)
        self.assertEqual(replay_summary["latest_graph_status"], "completed")
        layout_events = [
            event
            for event in runtime.user_visible_events("room-adjust-confirm", plan_id=plan.plan_id)
            if event["event_type"] == "layout_adjustment_confirmed"
        ]
        self.assertTrue(layout_events)
        self.assertEqual(layout_events[-1]["payload"]["status"], "partial")
        self.assertEqual(layout_events[-1]["payload"]["applied_count"], 2)
        self.assertEqual(layout_events[-1]["payload"]["transform_success_count"], 1)
        self.assertEqual(layout_events[-1]["payload"]["transform_failed_count"], 1)
        self.assertEqual(layout_events[-1]["payload"]["ground_snapped_count"], 1)
        self.assertNotIn("actor-box", str(layout_events[-1]))
        self.assertNotIn("actor-missing", str(layout_events[-1]))
        report_after_replay = runtime.generate_report("room-adjust-confirm", plan_id=plan.plan_id)
        self.assertEqual(
            report_after_replay["operation_replay_summary"]["layout_adjustment_replay_summary"]["transform_result_count"],
            2,
        )

    def test_confirm_layout_adjustment_snaps_floor_supported_aabb_without_provider(self) -> None:
        runtime = AgentRuntime()
        plan = runtime.propose_scene_plan(
            room_id="room-adjust-ground-runtime",
            text="build a treasure room with a chest and torch",
            owner_agent="merchant",
        )
        runtime.state.apply_patch(
            StatePatch(
                room_id="room-adjust-ground-runtime",
                changes={
                    "actors": {
                        "actor-chest": {
                            "actor_id": "actor-chest",
                            "name": "藏宝箱",
                            "position": [2.0, 0.5, 0.0],
                            "aabb": {"min": [1.5, 0.2, -0.5], "max": [2.5, 1.2, 0.5]},
                            "plan_id": plan.plan_id,
                        },
                        "actor-torch": {
                            "actor_id": "actor-torch",
                            "name": "火把",
                            "position": [-2.0, 1.4, 0.0],
                            "aabb": {"min": [-2.1, 1.0, -0.1], "max": [-1.9, 1.8, 0.1]},
                            "plan_id": plan.plan_id,
                        },
                    },
                    "layout_adjustment_proposals": {
                        plan.plan_id: {
                            "proposal_id": f"layout-{plan.plan_id}",
                            "plan_id": plan.plan_id,
                            "status": "proposed",
                            "risk_level": "low",
                            "reason": "布局调整，模型浮空，需要贴地",
                            "deltas": [
                                {
                                    "op": "move",
                                    "actor_name": "藏宝箱",
                                    "position_patch": {"x": 1.0, "z": 1.0},
                                    "risk_level": "low",
                                },
                                {
                                    "op": "move",
                                    "actor_name": "火把",
                                    "position_patch": {"x": -1.2},
                                    "risk_level": "low",
                                },
                            ],
                        }
                    },
                },
                expected_version=runtime.state.version,
            )
        )

        result = runtime.confirm_layout_adjustment(
            room_id="room-adjust-ground-runtime",
            plan_id=plan.plan_id,
        )

        self.assertEqual(result["graph"]["status"], "completed")
        room = runtime.query_state("room-adjust-ground-runtime")["room"]
        chest = room["actors"]["actor-chest"]
        torch = room["actors"]["actor-torch"]
        self.assertEqual(chest["position"], [1.0, 0.3, 1.0])
        self.assertEqual(chest["aabb"]["min"], [0.5, 0.0, 0.5])
        self.assertEqual(chest["aabb"]["max"], [1.5, 1.0, 1.5])
        self.assertEqual(chest["support_type"], "floor_supported")
        self.assertEqual(chest["grounding_status"], "grounded")
        self.assertEqual(torch["position"], [-1.2, 1.4, 0.0])
        self.assertEqual(torch["aabb"]["min"][1], 1.0)
        self.assertEqual(torch["support_type"], "wall_mounted")
        self.assertEqual(torch["grounding_status"], "not_applicable")
        proposal = room["layout_adjustment_proposals"][plan.plan_id]
        applied_by_actor = {item["actor_id"]: item for item in proposal["applied_deltas"]}
        self.assertTrue(applied_by_actor["actor-chest"]["ground_snapped"])
        self.assertEqual(applied_by_actor["actor-chest"]["support_type"], "floor_supported")
        self.assertFalse(applied_by_actor["actor-torch"]["ground_snapped"])
        self.assertEqual(applied_by_actor["actor-torch"]["support_type"], "wall_mounted")
        self.assertEqual(
            applied_by_actor["actor-torch"]["ground_snap_reason"],
            "wall_mounted actor skipped",
        )
        status = runtime.status_summary("room-adjust-ground-runtime", plan_id=plan.plan_id)
        status_roles = {
            entity["actor_id"]: entity
            for entity in status["scene_entity_registry"]["entities"]
            if entity["entity_type"] == "actor"
        }
        self.assertEqual(status_roles["actor-chest"]["grounding_status"], "grounded")
        self.assertEqual(status_roles["actor-torch"]["grounding_status"], "not_applicable")
        self.assertEqual(status["layout_adjustment_summary"]["ground_snapped_count"], 1)
        report = runtime.generate_report("room-adjust-ground-runtime", plan_id=plan.plan_id)
        report_roles = {
            entity["actor_id"]: entity
            for entity in report["scene_entity_registry"]["entities"]
            if entity["entity_type"] == "actor"
        }
        self.assertEqual(report_roles["actor-chest"]["grounding_status"], "grounded")
        self.assertEqual(report["layout_adjustment_summary"]["ground_snapped_count"], 1)

    def test_confirm_layout_adjustment_records_batch_scope_for_single_batch_proposal(self) -> None:
        def fake_layout_transform_provider(payload: dict) -> dict:
            return {
                "actor_updates": {
                    "actor-batch-one": {
                        "actor_id": "actor-batch-one",
                        "name": "绗竴鎵圭瀛?",
                        "position": [1.0, 0.0, 0.0],
                        "plan_id": payload.get("plan_id", ""),
                        "batch_id": first_batch_id,
                    }
                },
                "transform_results": [
                    {
                        "actor_id": "actor-batch-one",
                        "status": "success",
                        "batch_id": first_batch_id,
                        "ground_snapped": True,
                    }
                ],
            }

        runtime = AgentRuntime(layout_transform_provider=fake_layout_transform_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-layout-confirm-batch",
            text="鍋氫竴涓棌瀹濆锛屾湁鏈ㄧ銆佸疂绠便€侀噾甯佸爢",
            owner_agent="山贼",
        )
        runtime.confirm_scene_plan(plan.plan_id, confirmed_by="房主")
        batches = runtime.plan_batches(plan.plan_id, max_items_per_batch=1)
        self.assertGreater(len(batches), 1)
        first_batch_id = batches[0].batch_id
        second_batch_id = batches[1].batch_id
        proposal = {
            "proposal_id": "layout-confirm-first-batch",
            "plan_id": plan.plan_id,
            "room_id": "room-layout-confirm-batch",
            "status": "proposed",
            "risk_level": "low",
            "reason": "绗竴鎵圭瀛愰渶瑕佽创鍦?",
            "layout_strategy": "浣庨闄╄创鍦?",
            "batch_id": first_batch_id,
            "deltas": [
                {
                    "op": "move",
                    "actor_id": "actor-batch-one",
                    "actor_name": "绗竴鎵圭瀛?",
                    "batch_id": first_batch_id,
                    "risk_level": "low",
                    "position_patch": {"y": 0.0},
                }
            ],
        }
        ok, reason = runtime.state.apply_patch(StatePatch(
            room_id="room-layout-confirm-batch",
            changes={
                "actors": {
                    "actor-batch-one": {
                        "actor_id": "actor-batch-one",
                        "name": "绗竴鎵圭瀛?",
                        "plan_id": plan.plan_id,
                        "batch_id": first_batch_id,
                        "position": [1.0, 0.5, 0.0],
                    }
                },
                "layout_adjustment_proposals": {plan.plan_id: proposal},
            },
            expected_version=runtime.state.version,
        ))
        self.assertTrue(ok, reason)

        result = runtime.confirm_layout_adjustment(
            room_id="room-layout-confirm-batch",
            plan_id=plan.plan_id,
            proposal_id="layout-confirm-first-batch",
        )

        self.assertEqual(result["graph"]["status"], "completed")
        confirmed_entries = runtime.operation_log.query(
            event="layout_adjustment_confirmed",
            room_id="room-layout-confirm-batch",
        )
        self.assertTrue(confirmed_entries)
        self.assertEqual(confirmed_entries[-1].batch_id, first_batch_id)
        self.assertEqual(confirmed_entries[-1].payload["batch_id"], first_batch_id)
        replay_first = runtime.operation_replay(
            room_id="room-layout-confirm-batch",
            plan_id=plan.plan_id,
            batch_id=first_batch_id,
        )
        replay_second = runtime.operation_replay(
            room_id="room-layout-confirm-batch",
            plan_id=plan.plan_id,
            batch_id=second_batch_id,
        )
        self.assertEqual(replay_first["layout_adjustment_summary"]["confirmation_count"], 1)
        self.assertEqual(replay_first["layout_adjustment_summary"]["ground_snapped_count"], 1)
        self.assertEqual(replay_second["layout_adjustment_summary"]["confirmation_count"], 0)

