    def test_confirm_layout_adjustment_rejects_orphan_proposal_without_runtime_plan(self) -> None:
        def fail_if_called(payload: dict) -> dict:
            raise AssertionError("layout transform provider should not run for orphan proposal")

        runtime = AgentRuntime(layout_transform_provider=fail_if_called)
        orphan_proposal = {
            "proposal_id": "layout-proposal-orphan",
            "plan_id": "plan-layout-orphan",
            "room_id": "room-adjust-orphan",
            "status": "proposed",
            "risk_level": "low",
            "reason": "用户要求清出通道",
            "layout_strategy": "娓呭嚭涓婚€氶亾",
            "deltas": [
                {
                    "op": "move",
                    "actor_name": "钘忓疂绠?",
                    "position": [1.0, 0.0, 2.0],
                    "risk_level": "low",
                    "reason": "清出通道",
                }
            ],
        }
        applied, reason = runtime.state.apply_patch(
            StatePatch(
                room_id="room-adjust-orphan",
                changes={"layout_adjustment_proposals": {"plan-layout-orphan": orphan_proposal}},
                expected_version=runtime.state.version,
            )
        )
        self.assertTrue(applied, reason)

        result = runtime.confirm_layout_adjustment(
            room_id="room-adjust-orphan",
            plan_id="plan-layout-orphan",
            proposal_id="layout-proposal-orphan",
        )

        room = runtime.query_state("room-adjust-orphan")["room"]
        self.assertFalse(result["confirmed"])
        self.assertEqual(result["reason"], "no runtime plan")
        self.assertEqual(result["graph"], {})
        self.assertEqual(room["layout_adjustment_proposals"]["plan-layout-orphan"]["status"], "proposed")
        self.assertEqual(room["tool_graphs"], {})
        self.assertIn("layout_adjustment_confirmation_skipped", runtime.operation_log.events())
        self.assertNotIn("layout_adjustment_confirmed", runtime.operation_log.events())

