    def test_scene_snapshot_read_tool_merges_observed_engine_actors(self) -> None:
        def fake_provider(room_id: str) -> dict:
            return {
                "room_id": room_id,
                "source": "fake_engine",
                "actors": [
                    {
                        "actor_id": "engine-actor-1",
                        "name": "钘忓疂绠?",
                        "position": [1.0, 0.0, 2.0],
                        "rotation": [0.0, 90.0, 0.0],
                        "scale": [1.0, 1.0, 1.0],
                        "aabb": {"min": [0.5, 0.0, 1.5], "max": [1.5, 1.0, 2.5]},
                        "version": 7,
                    }
                ],
            }

        runtime = AgentRuntime(scene_snapshot_provider=fake_provider)

        result = runtime.refresh_scene_snapshot("room-1")

        self.assertEqual(result["graph"]["status"], "completed")
        room = runtime.query_state("room-1")["room"]
        self.assertIn("engine-actor-1", room["observed_actors"])
        self.assertIn("engine-actor-1", room["actors"])
        self.assertEqual(room["actors"]["engine-actor-1"]["source"], "fake_engine")
        self.assertEqual(room["actors"]["engine-actor-1"]["version"], 7)
        snapshot = next(iter(room["engine_scene_snapshots"].values()))
        self.assertEqual(snapshot["actor_count"], 1)

