    def test_plan_scoped_snapshot_without_known_identity_does_not_claim_or_rebatch_actors(self) -> None:
        def fake_provider(request: dict[str, Any]) -> dict[str, Any]:
            return {
                "room_id": request.get("room_id"),
                "source": "fake_engine",
                "actors": [
                    {
                        "actor_id": "native-existing-chair",
                        "name": "native-chair",
                        "position": [2.0, 0.0, 1.0],
                        "aabb": {"min": [1.5, 0.0, 0.5], "max": [2.5, 1.0, 1.5]},
                        "bounds_ready": True,
                    },
                    {
                        "actor_id": "native-unmanaged-prop",
                        "name": "unmanaged-prop",
                        "position": [0.0, 0.0, 0.0],
                        "aabb": {"min": [-0.5, 0.0, -0.5], "max": [0.5, 1.0, 0.5]},
                        "bounds_ready": True,
                        "render_status_observed": True,
                        "render_ready": True,
                        "render_failed": False,
                        "gpu_build_state": "Ready",
                        "mesh_count": 1,
                        "renderable_mesh_count": 1,
                        "invalid_mesh_count": 0,
                    },
                ],
            }

        runtime = AgentRuntime(scene_snapshot_provider=fake_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-snapshot-no-claim",
            text="create a room with a chair",
            owner_agent="designer",
        )
        runtime.state.apply_patch(StatePatch(
            room_id="room-snapshot-no-claim",
            changes={
                "actors": {
                    "runtime-chair": {
                        "actor_id": "runtime-chair",
                        "entity_id": "entity-chair",
                        "name": "chair",
                        "plan_id": plan.plan_id,
                        "batch_id": "batch-original",
                        "asset_id": "asset-chair",
                        "model_ref": "chair.glb",
                        "status": "engine_loading",
                    }
                }
            },
        ))
        graph = ToolCallGraph(
            graph_id="graph-plan-scoped-snapshot",
            plan_id=plan.plan_id,
            batch_id="batch-next",
        )
        graph.add(ToolCall(
            tool_call_id="tool-plan-scoped-snapshot",
            tool_name="runtime.scene.snapshot",
            args={
                "room_id": "room-snapshot-no-claim",
                "plan_id": plan.plan_id,
                "batch_id": "batch-next",
            },
            risk_level=RiskLevel.LOW,
        ))

        executed = ToolCallGraphExecutor(
            registry=runtime.registry,
            guard=runtime.guard,
            state=runtime.state,
            operation_log=runtime.operation_log,
        ).execute(graph, room_id="room-snapshot-no-claim")
        room = runtime.query_state("room-snapshot-no-claim")["room"]

        self.assertEqual(executed.status, "completed")
        self.assertEqual(set(room["actors"]), {"runtime-chair"})
        self.assertEqual(room["actors"]["runtime-chair"]["batch_id"], "batch-original")
        self.assertEqual(room["actors"]["runtime-chair"]["asset_id"], "asset-chair")
        self.assertIn("native-existing-chair", room["observed_actors"])
        self.assertIn("native-unmanaged-prop", room["observed_actors"])

    def test_plan_finalizer_recovers_partial_batch_from_native_snapshot(self) -> None:
        def fake_provider(request: dict[str, Any]) -> dict[str, Any]:
            return {
                "room_id": request.get("room_id"),
                "source": "engine_scene_snapshot",
                "actors": [
                    {
                        "actor_id": "engine-chair-ready",
                        "name": "chair",
                        "position": [0.0, 0.0, 0.0],
                        "aabb": {"min": [-0.5, 0.0, -0.5], "max": [0.5, 1.0, 0.5]},
                        "bounds_ready": True,
                        "render_status_observed": True,
                        "render_ready": True,
                        "render_failed": False,
                        "gpu_build_state": "Ready",
                        "mesh_count": 1,
                        "renderable_mesh_count": 1,
                        "invalid_mesh_count": 0,
                    },
                    {
                        "actor_id": "engine-room-floor-ready",
                        "name": "room_floor",
                        "position": [0.0, 0.0, 0.0],
                        "aabb": {"min": [-3.0, -0.1, -3.0], "max": [3.0, 0.0, 3.0]},
                        "bounds_ready": True,
                        "render_status_observed": True,
                        "render_ready": True,
                        "render_failed": False,
                        "gpu_build_state": "Ready",
                        "mesh_count": 1,
                        "renderable_mesh_count": 1,
                        "invalid_mesh_count": 0,
                    },
                ],
            }

        runtime = AgentRuntime(scene_snapshot_provider=fake_provider)
        plan = runtime.propose_scene_plan(
            room_id="room-late-ready-snapshot",
            text="create a room with a chair",
            owner_agent="designer",
        )
        plan.status = ScenePlanStatus.EXECUTING
        batch = BatchPlan(
            batch_id="batch-late-ready-snapshot",
            plan_id=plan.plan_id,
            room_id="room-late-ready-snapshot",
            requested_items=["chair"],
            status=BatchPlanStatus.PARTIAL,
        )
        runtime.scene_plans[plan.plan_id] = plan
        runtime.batch_plans[batch.batch_id] = batch
        applied, reason = runtime.state.apply_patch(StatePatch(
            room_id="room-late-ready-snapshot",
            changes={
                "active_plan_id": plan.plan_id,
                "scene_plans": {plan.plan_id: plan.as_dict()},
                "batch_plans": {batch.batch_id: batch.as_dict()},
                "actors": {
                    "engine-chair-ready": {
                        "actor_id": "engine-chair-ready",
                        "name": "chair",
                        "plan_id": plan.plan_id,
                        "batch_id": batch.batch_id,
                        "asset_id": "asset-chair",
                        "model_ref": "chair.glb",
                        "position": [0.0, 0.0, 0.0],
                        "rotation": [0.0, 0.0, 0.0],
                        "scale": [1.0, 1.0, 1.0],
                        "support_type": "floor_supported",
                        "grounding_status": "needs_review",
                        "sync_status": "local",
                        "status": "engine_loading",
                        "bounds_ready": False,
                        "bounds_source": "estimated",
                        "engine_lifecycle_status": "engine_loading",
                    }
                },
                "custom_import_facts": {
                    f"{batch.batch_id}:actor_import_result": {
                        "status": "engine_loading",
                        "requested_count": 1,
                        "imported_count": 1,
                        "ready_count": 0,
                        "failed_count": 0,
                    },
                    f"{batch.batch_id}:environment_import_result": {
                        "status": "engine_loading",
                        "component_count": 1,
                        "imported_count": 1,
                        "ready_count": 0,
                        "failed_count": 0,
                    },
                },
                "environment_components": {
                    batch.batch_id: {
                        "room_floor": {
                            "component_id": "room_floor",
                            "name": "room_floor",
                            "component_type": "room_floor",
                            "actor_id": "engine-room-floor-ready",
                            "status": "engine_loading",
                            "bounds_ready": False,
                            "bounds_source": "estimated",
                            "engine_lifecycle_status": "engine_loading",
                            "entity_type": "environment",
                            "semantic_role": "walkable_floor",
                        }
                    }
                },
            },
        ))
        self.assertTrue(applied, reason)

        drain_result = runtime.handle_message(
            room_id="room-late-ready-snapshot",
            text="runtime worker drain",
            action="worker_drain",
        )
        room = runtime.query_state("room-late-ready-snapshot")["room"]

        self.assertEqual(drain_result["drain"]["drained_count"], 0)
        self.assertEqual(room["batch_plans"][batch.batch_id]["status"], BatchPlanStatus.COMPLETED.value)
        self.assertEqual(room["scene_plans"][plan.plan_id]["status"], ScenePlanStatus.COMPLETED.value)
        self.assertEqual(
            room["custom_import_facts"][f"{batch.batch_id}:actor_import_result"]["ready_count"],
            1,
        )
        self.assertTrue(room["actors"]["engine-chair-ready"]["bounds_ready"])
        self.assertEqual(room["actors"]["engine-chair-ready"]["grounding_status"], "grounded")
        self.assertTrue(room["environment_components"][batch.batch_id]["room_floor"]["bounds_ready"])
        self.assertEqual(
            room["custom_import_facts"][f"{batch.batch_id}:environment_import_result"]["ready_count"],
            1,
        )
        self.assertIn("engine_readiness_reconciled_from_snapshot", runtime.operation_log.events())
        registry = runtime._scene_entity_registry_for_plan(room, plan.plan_id)
        chair = next(entity for entity in registry["entities"] if entity.get("actor_id") == "engine-chair-ready")
        self.assertTrue(chair["game_ready"], chair)
        self.assertTrue(room["reports"])

